window.MANAMETAL_DATA = {"mod": {"name": "[M3]魔法金属 (ManaMetalMod)", "url": "https://www.mcmod.cn/class/1111.html", "license": "CC BY-NC-SA 3.0 (内容来自 MC百科 mcmod.cn，需署名且非商用)", "scraped_at": "2026-07-20"}, "classes": [{"name": "剑斗士", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "大", "生存": "极强", "刷本效率": "高", "缺蓝": "缺", "对单": "较高", "特殊1": "嘲讽", "特殊2": "自带复活"}, "tiers": {"固有技能": [{"name": "战斗防守", "url": "https://www.mcmod.cn/item/438169.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438169.png?v=12", "category": "剑斗士:固有技能", "description": "基础信息\n- 固有技能\n- 负面效果：嘲讽*30秒\n- 负面半径：12米\n- 自拐能力-防御反击：100%造伤*60秒\n- 怒气消耗：10点\n- 怒气效果：额外给予自身10层绝对抵御\n- 魔力消耗：300点\n- 冷却时间：5秒\n- 持剑时右键发动\n- 每升1级增加6秒的防御反击与绝对抵御持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n架起防守态势，嘲讽半径12米范围内的怪物，将其攻击目标设定为自身，持续30秒。同时给予自身60秒的防御反击：造成的伤害+100%。\n职业专属\n持有怒气驱动发动该技能时，消耗10点怒气，额外给予自身10层持续60秒的绝对抵御：持有效果时可以抵挡伤害，每次抵挡会消耗1层绝对抵御效果。\n历史改动：\n- 7.0.0版本：重制技能，现在不能通过持续释放战斗防守来格挡伤害、恢复生命、获取BUFF了，改为释放技能获取防御反击效果，添加怒气驱动效果：额外获取10层绝对抵御。\n- 5.6.8版本：增强技能，现在格挡条可以抵挡5次伤害，且成功格挡后可以提升剑斗士造成的伤害。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "剑气波", "url": "https://www.mcmod.cn/item/438170.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438170.png?v=10", "category": "剑斗士:固有技能", "description": "基础信息\n- 固有技能\n- 技能倍率：150%*1剑气\n- 怒气消耗：2点\n- 怒气效果：剑气可以贯穿生物，技能倍率增加25%，与总技能倍率加算\n- 魔力消耗：200点\n- 冷却时间：2秒\n- 持剑时按下武器功能键（默认V键）发动\n- 每升1级增加7.5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n用力挥砍武器，向正前方发射剑气波，对命中的目标造成150%物理近战暴风属性劈砍伤害。\n职业专属\n持有怒气驱动发动该技能时，消耗2点怒气值，使得剑气波可穿透目标，并使剑气波技能倍率增加25%，额外倍率与技能总倍率加算。\n历史改动：\n- 7.0.8版本：修正技能，移除剑气波伤害组成的基础伤害额外增加了角色NBT物理攻击力的问题。\n- 7.0.6版本：调整技能，怒气驱动消耗由1提高至2，额外倍率由20%提高至25%，\n- 7.0.0版本：重制技能，伤害系数由300%降低至150%，添加怒气驱动效果：增加技能倍率、可以穿透敌人。\n- 6.2.0版本：增强技能，伤害系数由250%提升至300%。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}], "一转技能": [{"name": "幻影剑", "url": "https://www.mcmod.cn/item/438166.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438166.png?v=15", "category": "剑斗士:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：150%*12抛射物\n- 辅助能力-幻影魔剑：10%职业增幅*60秒\n- 辅助半径：32米\n- 怒气消耗：5点\n- 怒气效果：每个抛射物额外造成一次150%技能倍率，半径4米的爆炸伤害\n- 魔力消耗：400点\n- 冷却时间：16秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加7.5%技能倍率，7.5%怒气驱动爆炸倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n召唤暗影的力量，向正前方发射12把暗影魔法剑，对目标造成150%物理近战黑暗属性影子伤害，并给予发射者与落点位置半径32米范围内所有玩家60秒的幻影魔剑：职业增幅+10%。\n额外效果\n幻影剑直接命中非魔王目标时，技能倍率提升至原先的1.2倍，该增幅对怒气驱动的爆炸伤害无效。\n职业专属\n持有怒气驱动发动该技能时，消耗5点怒气值，幻影剑命中后可触发魔力爆破效果，对半径4米范围内所有敌人造成150%物理近战黑暗属性影子伤害。\n历史改动：\n- 7.4.2版本：增强技能，攻击段数由10增加至12。\n- 7.0.0版本：重制技能，伤害倍率由300%降低至150%，每级倍率由10%降低至7.5%，添加怒气驱动效果：额外触发一次爆炸，直接命中伤害提升。\n- 6.2.0版本：增强技能，伤害倍率由250%提升至300%。\n- 5.4.3版本：增强技能，伤害倍率由200%提升至250%，并且攻击段数增加3段，速度加快。\n- 5.3.8版本：增强技能，攻击段数增加3段。\n- 5.2.7版本：增强技能，攻击段数提高2段。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "玄月斩", "url": "https://www.mcmod.cn/item/438167.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438167.png?v=7", "category": "剑斗士:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：100%*5斩\n- AOE半径：3米斩击\n- 易伤能力-玄月斩：20%*60秒\n- 怒气消耗：5点\n- 怒气效果：伤害范围与角度增加，技能倍率增加40%，与总技能倍率加算\n- 魔力消耗：200点\n- 冷却时间：8秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n以相当快的速度向正前方连续斩击5次，攻击正前方半径3米的72°扇形范围内的至多5个目标，造成100%物理近战黑暗属性劈砍伤害。并对目标施加持续60秒的玄月斩：受到的伤害增加+20%。\n职业专属\n持有怒气驱动发动该技能时，消耗5点怒气值，玄月斩的攻击半径增加1米，攻击角度增加24°，技能伤害倍率增加40%，与总技能倍率加算。\n历史改动：\n- 7.0.0版本：重制技能，魔力消耗由250降低至200，伤害倍率由200%降低至100%，每级倍率由10%降低至5%，攻击段数由9减少至5，现在可以对目标施加玄月斩效果，添加怒气驱动效果：增加范围与伤害倍率。\n- 6.2.0版本：增强技能，伤害倍率由150%提升至200%。\n- 5.4.3版本：增强技能，攻击段数提高3段。\n- 5.1.9版本：增强技能，攻击段数提高。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "连环斩", "url": "https://www.mcmod.cn/item/438168.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438168.png?v=10", "category": "剑斗士:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- AOE半径：3米斩击\n- 自拐能力-连环斩：50%造伤+嘲讽+普攻溅射 * 60秒\n- 怒气消耗：10点\n- 怒气效果：持续时间内普攻与溅射的每个目标都将恢复自身2%最大生命值的血性\n- 魔力消耗：300点\n- 冷却时间：60秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加6秒连环斩持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n凝聚力量，在每一次的攻击中斩出华丽剑气，给予自身60秒连环斩：造成的伤害+50%，持续时间内普通攻击可额外释放协同剑气：额外攻击前方半径3米的72°扇形范围内的其它至多3个目标，协同剑气不会攻击普通攻击的目标。当持有连环斩效果攻击目标时，普通攻击与协同剑气击中怪物会将怪物的攻击目标设定为自身，嘲讽至多持续10秒，重复嘲讽会刷新时间。\n职业专属\n持有怒气驱动发动该技能时，消耗10点怒气值，持续时间内普通攻击与协同剑气每命中1个目标都可恢复自身2%最大生命值的血性值。\n剑术大师\n学习2转被动剑术大师后，连环斩持续时间内，每次普通攻击命中都会给予自身一层持续120秒的防御策略：防御力+1。最高叠加至250层，满层时受到致命伤害将会消耗所有防御策略效果抵御这次伤害，并恢复所有生命值。\n历史改动：\n- 7.4.3版本：平调技能，防御策略上限与免死层数由150层提升至250层。\n- 7.3.7版本：增强技能，当学习剑术大师技能后，普通攻击命中将会额外获得防御策略效果。\n- 7.1.7版本：增强技能，嘲讽时间由7秒延长至10秒。\n- 7.0.0版本：重制技能，造成的伤害增加系数由35%提升至50%，现在协同剑气命中敌人可以嘲讽对方，添加怒气驱动效果：协同剑气每命中一个目标可以恢复自身2%血性值。\n- 6.2.0版本：增强技能，造成的伤害增加系数由25%提升至35%。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "剑术精通", "url": "https://www.mcmod.cn/item/438165.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438165.png?v=4", "category": "剑斗士:一转技能:被动技能", "description": "属性提升\n职业等级5级后开放学习。\n提高10%最终伤害，提高20%重力伤害减免。\n特殊能力\n获得击退抵抗，受到重力伤害时不再出血。\n生命值低于50%时，消耗每点怒气获得的血性值由1%最大生命值提升至2%最大生命值。\n历史改动：\n- 7.0.0版本：重制技能，移除物理攻击力、生命值增益，现在可以提高10%最终伤害，血量低于50%时消耗怒气获得的血性值恢复翻倍。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}], "二转技能": [{"name": "剑术大师", "url": "https://www.mcmod.cn/item/442598.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442598.png?v=4", "category": "剑斗士:二转技能:被动技能", "description": "属性提升\n职业等级70级解锁2转后开放学习。\n提高10%最终伤害，提高20点怒气上限。\n特殊能力\n普通攻击命中目标后，会额外获得1点怒气。\n在连环斩效果持续期间，每次普通攻击命中都会获得一层持续120秒的防御策略效果：防御力+1。最高叠加至250层，满层时受到致命伤害将会消耗所有防御策略效果抵御这次伤害，并恢复所有生命值。\n历史改动：\n- 7.4.3版本：平调技能，防御策略上限与免死层数由150层提升至250层。\n- 7.3.7版本：增强技能，开启连环斩后，普通攻击每次命中都会额外获得一层防御策略效果。\n- 7.0.0版本：重制技能，移除概率施加出血与攻击出血目标提高伤害的效果，现在可以提高10%最终伤害，20点怒气上限，1点怒气恢复。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "血战誓约", "url": "https://www.mcmod.cn/item/442599.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442599.png?v=7", "category": "剑斗士:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 辅助能力-复仇：10%职业增幅 * 60秒\n- 辅助半径：32米\n- 自拐能力-血战誓约：普攻恢复400血（不可叠加）、造伤+2% * 60秒\n- 怒气消耗：20点\n- 怒气效果：额外给予60秒血战狂怒：普攻速度加倍、终伤+20%、每秒损失2%最大生命（不致命）\n- 魔力消耗：800点\n- 冷却时间：90秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加6秒血战誓约、复仇与血战狂怒的持续时间，20点血战誓约普攻恢复量，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n激励自己从而激发自身体能的极限，给予自身60秒血战誓约效果，持续时间内每次普攻都会恢复400点生命值并提升自身一层血战誓约效果：每层提高2%造成的伤害，最大可获得25层血战誓约。同时给予自身与距离自身32米以内所有玩家60秒复仇效果：职业增幅+10%。\n职业专属\n持有怒气驱动发动该技能时，消耗20点怒气值，额外给予自身血战狂怒效果，提高20%最终伤害，使用近战武器时挥击速度由每秒2.5次提升至每秒5次，血战狂怒持续时间内将每秒损失2%最大生命值，当前生命值不足2%最大生命值时，将损失至1点生命值。\n历史改动：\n- 7.4.2版本：增强技能，现在血战狂怒还会使普攻速度翻倍。\n- 7.0.0版本：重制技能，魔力消耗由400增加至800，效果持续时长由90秒缩短至60秒，每级效果时长由5秒延长至6秒，现在可以给予范围玩家复仇效果，添加怒气驱动效果：给予自身血战狂怒效果。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "狂暴剑斩", "url": "https://www.mcmod.cn/item/442600.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442600.png?v=8", "category": "剑斗士:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：420%*12抛射物\n- 段数补正：贯穿抛射物\n- 怒气消耗：15点\n- 怒气效果：技能倍率增加100%，与总技能倍率加算\n- 魔力消耗：600点\n- 冷却时间：12秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加21%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n猛力挥剑，向前方发出共12道猛烈斩击。斩击可以穿透直线目标并造成420%物理近战火焰属性劈砍伤害。\n职业专属\n持有怒气驱动发动该技能时，消耗15点怒气值，使技能倍率增加100%，与总技能倍率加算。\n历史改动：\n- 7.4.2版本：增强技能，攻击段数由10提高至12。\n- 7.2.4版本：增强技能，怒气驱动额外倍率由50%提高至100%，现在怒气驱动下的狂暴剑斩也可以穿透敌人。\n- 7.0.0版本：重制技能，魔力消耗由400提高至600，攻击段数由7提高至10，伤害倍率由650%降低至420%，升级效果由增加1段攻击段数改为增加21%技能倍率，添加怒气爆发效果：技能倍率提高，但无法穿透敌人。\n- 5.6.7版本：增强技能，狂暴剑斩段数由5提高为7。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "怒气爆发", "url": "https://www.mcmod.cn/item/442601.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442601.png?v=8", "category": "剑斗士:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：450%*1段\n- AOE半径：10米\n- 负面效果：吸引*20秒\n- 负面半径：10米\n- 自拐能力-怒气爆发：100%造伤*90秒\n- 怒气消耗：20点\n- 怒气效果：损失15%当前生命，怒气爆发持续时间加倍，吸引时间+10秒\n- 魔力消耗：600点\n- 冷却时间：100秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加22.5%技能倍率，4秒怒气爆发持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n透过刺激自己，发挥狂战士真正的力量，给予自身90秒怒气爆发效果：造成的伤害+100%。同时对距离自身10米内所有目标造成450%物理近战火焰属性精神伤害，并持续吸引该范围内所有敌人20秒，立刻重置所有一转技能的冷却时间。\n职业专属\n持有怒气驱动发动该技能时，消耗20点怒气值，将损失15%当前生命值，但怒气爆发的持续时间会加倍，吸引时间额外延长10秒。\n历史改动：\n- 7.2.4版本：增强技能，现在怒气爆发还会额外牵引附近敌人。\n- 7.0.0版本：重制技能，魔力消耗由400提高至600，伤害倍率由900%降低至450%，每级伤害倍率由100%降低至22.5%，移除升级增加1秒效果持续时间，添加怒气驱动效果：损失15%当前生命使怒气爆发持续时间加倍。\n- 6.1.7版本：削弱技能，现在不再无视目标的韧性\n- 5.6.8版本：增强技能，现在怒气爆发可以无视目标的韧性减伤。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "龙卷剑斩", "url": "https://www.mcmod.cn/item/442602.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442602.png?v=12", "category": "剑斗士:二转技能:超级技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：275%*4段/秒*60秒\n- AOE半径：5米\n- 负面效果：吸引+回复封锁*120秒\n- 负面半径：16米吸引、5米回复封锁\n- 怒气消耗：40点\n- 怒气效果：分裂为3道无吸引力、技能倍率165%、范围4米的小型飓风，额外对怪物施加风切：30%易伤*120秒\n- 魔力消耗：1500点\n- 冷却时间：600秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加13.75%技能倍率，8.25%怒气驱动的小型飓风攻击伤害，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n命中效果\n凝聚全身上下所有力量，向前发出奋力一斩，刮起剧烈飓风，飓风将持续吸引半径16米范围内的目标，同时每秒对5米范围内所有目标造成4段275%物理近战暴风属性劈砍伤害，并给予目标60秒的回复封锁效果，使目标无法恢复生命值。飓风最多存在60秒。\n职业专属\n持有怒气驱动发动该技能时，消耗40点怒气，飓风将分裂为三道小型飓风，小型飓风不再吸引怪物，且每个小型飓风每秒对4米范围内所有目标造成4段165%物理近战暴风属性劈砍伤害，同时给予目标60秒风切、回复封锁效果，使目标受到的伤害增加30%，且无法恢复生命值。小型飓风最多存在60秒。\n历史改动：\n- 7.2.7版本：修正技能，段数由每秒10段恢复为每秒4段。\n- 7.2.4版本：增强技能，现在龙卷剑斩会给予怪物回复封锁效果。\n- 7.0.0版本：重制技能，魔力消耗由800提升至1500，伤害倍率由550%降低至275%，升级效果由减少20秒CD改为增加13.75%技能倍率，现在不再给予深度伤口效果，而是给予风切效果，添加怒气驱动效果：飓风会分裂为3个小型飓风。\n- 6.2.8版本：增强技能，技能持续时间从40秒延长到80秒，并且大幅增强吸引力，降低移动速度。\n- 5.6.7版本：增强技能，攻击间隔大幅缩短，并给予目标深度伤口效果。\n- 5.6.2版本：增强技能，技能倍率由450%提高550%。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}], "三转技能": [{"name": "不屈怒焰", "url": "https://www.mcmod.cn/item/946588.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946588.png?v=2", "category": "剑斗士:三转技能:被动技能", "description": "属性提升\n提高20%最终伤害，提高20点怒气上限，提高200点防御力。\n特殊能力\n基础信息\n- 技能倍率：1050%*1~5抛射物\n- 段数补正：3段\n- 储存时间：252秒（每抛射物独立）\n- 索敌半径：16米\n- 自我治疗：1260点*1~5抛射物\n能力描述\n每当普通攻击获得3点怒气时，就会召唤1颗怒焰火球在身边围绕，最多同时拥有5颗怒焰火球，当发动战斗防守技能时，怒焰火球会全部飞往附近的目标并对单体敌人造成1050%物理近战火焰属性岩浆伤害，会优先攻击注视的目标，发射的每颗怒焰火球都会治疗自身1260点生命值。\n武器提供的额外怒气不会计入怒焰火球的计数，怒气满时不再会累计怒焰火球的计数，不会因为每次获取2点怒气而溢出怒焰火球的计数，无注释目标时会锁定范围内随机敌人，每一轮怒焰火球的发射所有怒焰火球都只会锁定同一名敌人。\n历史改动：\n- 8.0.0-RC3版本：修复技能，现在武器提供的怒气不会计入怒焰火球的计数。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "破阵连斩", "url": "https://www.mcmod.cn/item/946598.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946598.png?v=4", "category": "剑斗士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：800%*20斩+800%*20抛射物+800%*1~5段终结击\n- 段数补正：贯穿抛射物\n- 真实物理伤害：10点*20抛射物+10点*1~5段终结击\n- AOE半径：5米\n- 自拐能力-破阵：4%造伤*1~20层\n- 怒气消耗：20点\n- 怒气效果：斩击与抛射物数量+10，破阵层数上限+10，终结击段数上限+2，斩击命中治疗自身500生命\n- 魔力消耗：600点\n- 技能冷却时间：120秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加40%技能倍率，25点自我治疗量，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n命中效果\n向前连续斩击20次，每次对前方5米48度扇形范围内的所有敌人造成800%物理近战暴风属性劈砍伤害，斩击每命中一次，就获得1层持续20秒的破阵效果：每层增加4%造成的伤害，每次斩击最多叠加1层。\n破阵效果存在时间内若再次释放破阵连斩，则会先清除上一次破阵连斩带来的破阵效果，重新叠层。\n额外效果\n每次斩击后还会额外向前释放1道贯穿剑气，对接触到的敌人每tick造成1次与斩击相同倍率的伤害，并附加10点真实物理伤害，剑气的释放在破阵效果叠加之后。\n斩击释放结束时还会额外发动一次范围斩击，对距离自身5米范围内的所有敌人造成1段与普通斩击相同倍率的伤害伤害，并附加10点真实物理伤害，每拥有5层破阵效果，范围斩击的伤害段数就增加1段，破阵效果还会提升 0.1*破阵层数 倍的范围斩击总技能倍率。剑气与范围斩击无法叠加破阵层数。\n职业专属\n持有怒气驱动发动该技能时，消耗20点怒气，斩击次数增加10次，相应的剑气数量与破阵可叠加层数也增加10，同时每次斩击命中时为自身恢复500点生命值，每次斩击最多恢复1次。\n历史改动：\n- 8.0.0-RC3版本：修正技能，现在剑气与终结击带有10点真实物理伤害，实装冷却减免倍率。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "雷霆重劈", "url": "https://www.mcmod.cn/item/946601.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946601.png?v=5", "category": "剑斗士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：600%*33次雷击\n- 真实物理伤害：5点*33次雷击\n- AOE半径：2米\n- 负面效果：缓慢5*5秒\n- 怒气消耗：10点\n- 怒气效果：每道闪电消失时对半径4米敌人附加3倍技能倍率的爆炸与12段250%倍率的DOT\n- 魔力消耗：600点\n- 冷却时间：30秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加30%技能倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n技能效果\n向前方发出奋力一斩，在前方直线24米距离内引发数道闪电覆盖，每道闪电至多进行33段范围攻击，每段对半径2米的敌人造成600%物理近战闪电属性雷霆伤害，并额外造成5点真实物理伤害。\n注：由于闪电之间的间隔略大于2米，因此敌人往往可以同时受到2~3道闪电的攻击。\n额外效果\n每次雷击伤害还会额外附加5秒的缓慢5，多次命中会刷新持续时间。\n职业专属\n持有怒气驱动发动该技能时，消耗10点怒气，每道闪电上方会额外产生雷霆魔剑，在闪电消失后，雷霆魔剑向下突刺并在地面额外引爆1段半径4米的爆炸伤害，并对爆炸范围内的敌人施加12段持续伤害：每秒造成250%物理近战闪电属性心灵伤害，持续12次。爆炸伤害的倍率为技能倍率的3倍，雷霆魔剑突刺命中没有伤害。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "战神领域", "url": "https://www.mcmod.cn/item/946603.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946603.png?v=2", "category": "剑斗士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 负面效果-回复封锁：禁疗*150秒\n- 负面半径：10米\n- 辅助能力-战神领域：50%造伤+10%职业增幅+10%受到的伤害减免 * 125秒\n- 辅助半径：10米\n- 怒气消耗：10点\n- 怒气效果：不再具有辅助效果，改为仅为自身施加，处于负面半径内的敌人每0.5秒受到100%技能倍率伤害\n- 魔力消耗：600点\n- 冷却时间：240秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加5%技能倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n技能效果\n以骄傲的剑术在地面上刻画下战神领域，存在时每0.5秒对半径10米范围内的所有玩家持续给予5秒的战神领域效果：提升50%造成的伤害，10%职业增幅，10%受到的伤害减免，重复施加可以刷新持续时间。战神领域至多存在120秒。\n额外效果\n战神领域存在时还会对范围内的所有怪物持续施加30秒的回复封锁效果：无法受到治疗，重复施加可以刷新持续时间。\n职业专属\n持有怒气驱动发动该技能时，消耗10点怒气，战神领域不再对任何玩家施加战神领域效果，改为一次性使自身获得120秒的战神领域效果，每0.5秒对战神领域范围内的所有怪物造成100%物理近战魔法属性咒语伤害。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}, {"name": "刀锋剑雨", "url": "https://www.mcmod.cn/item/946605.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946605.png?v=2", "category": "剑斗士:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：900%*960抛射物（期望）\n- 索敌半径：10米\n- 易伤能力-撕裂：30%*60秒\n- 怒气消耗：所有\n- 怒气能力：每消耗1点怒气增加0.5秒撕裂持续时间与0.5秒刀锋剑雨持续时间（期望增加16抛射物）\n- 魔力消耗：1500点\n- 冷却时间：900秒\n- 持剑时按下设定的技能按键发动\n- 每升1级增加45%技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n技能效果\n向前方发射符咒，并在符咒落地位置召唤刀刃符文，以无尽的刀剑撕碎目标，刀刃符文一共有8个，每个符文在每tick都有20%的概率召唤一把追踪剑，随机锁定半径10米内的一名敌人，对命中的敌人造成900%物理近战暴风属性风切伤害，同时施加30秒的撕裂效果：受到的伤害增加30%，重复施加可以刷新持续时间。刀刃符文至多持续30秒，期望共召唤960把追踪剑。\n职业专属\n持有怒气驱动发动该技能时，消耗所有怒气，每消耗1点怒气值，刀锋剑雨的刀刃符文持续时间都会增加0.5秒（期望增加16把追踪剑），相应的撕裂效果持续时间也增加0.5秒。\n你知道吗\n刀刃符文一共会召唤9种剑，分别是：木剑、铁剑、金剑、钻石剑、巨兽之牙、炼狱战神、破天使者、天界光钥、拉普达幻影长剑。\n此段资料引用于“怒气 (怒氣)”并与其保持同步更新。  编辑剑斗士的施法资源，使用剑类武器普通攻击命中敌人可以恢复1点，学习2转被动剑术大师后每次普通攻击命中敌人还可以额外恢复1点，使用拉普达幻影长剑/艾莉西亚的幻影长剑命中敌人时有10%概率额外恢复1点，使用圣界裁决者之光命中敌人时会额外恢复1点。\n持剑时蹲下右击可获得或移除怒气驱动效果，怒气驱动持续时间内释放技能将会消耗怒气强化技能并移除怒气驱动效果。\n消耗怒气时，每消耗1点怒气都会为剑斗士补充1%最大生命值的血性值，学习1转被动剑术精通后，生命值不足50%时该效果翻倍。\n怒气上限20点，学习2转被动剑术大师后提高20点，学习3转被动不屈怒焰后提高20点。\n历史改动：\n- 7.0.6版本：消耗怒气恢复血性效果由2%降低至1%。"}]}}, {"name": "武士", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "很大", "生存": "很强", "刷本效率": "高", "缺蓝": "缺", "对单": "极高", "特殊1": "输出平滑", "特殊2": "需要一定理解和操作水平"}, "tiers": {"固有技能": [{"name": "架势切换", "url": "https://www.mcmod.cn/item/648590.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648590.png?v=2", "category": "武士:固有技能", "description": "固有技能。\n消耗150魔力，切换架势，太刀拥有两种架势，残月与旭日，不同架势会对技能造成不同影响。\n切换为残月时，且普通攻击命中会额外对半径2米内的敌人造成一次伤害。\n切换为旭日时，普通攻击命中敌人会恢复自身5%血性值。\n持太刀时右击发动。\n该技能升级无效。\n历史改动：\n7.0.0版本：\n重制技能，魔力消耗由120提升至150，移除残月的生命恢复提升，移除旭日的暴击率、暴击伤害与普攻提升，改为恢复自身5%血性值。"}, {"name": "瞬斩", "url": "https://www.mcmod.cn/item/648591.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648591.png?v=5", "category": "武士:固有技能", "description": "固有技能。\n消耗150魔力，立即斩切球形半径4米范围内敌人造成180%物理近战暴风属性风切伤害，同时给予命中目标持续30秒的瞬斩效果，提高15%受到的伤害。瞬斩所发出的强大斩击足以劈开并破坏该范围内所有的重力球。瞬斩不需要剑气发动，释放瞬斩也不会消耗剑气\n持太刀时按下武器功能键（默认V）施放。\n每升一级伤害提升9%。\n冷却时间5秒。\n历史改动：\n- 7.2.8版本：冷却时间由1秒延长到5秒，现在瞬斩不需要剑气发动，释放也不会消耗剑气。\n- 7.1.9版本：新增技能效果，释放时破坏附近所有的重力球。\n- 7.0.8版本：增强技能，基础伤害倍率由150%提高至180%，每级伤害倍率由7%提高至9%。\n- 7.0.0版本：重制技能，魔力消耗由200降低至150，基础伤害倍率由250%降低至150%，每级伤害倍率提升由10%降低至7%。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}], "一转技能": [{"name": "玄月/鹰爪", "url": "https://www.mcmod.cn/item/648592.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648592.png?v=6", "category": "武士:一转技能:主动技能", "description": "一转技能。\n消耗150魔力。\n残月，横扫前方范围内敌人造成2段145%物理近战黑暗属性劈砍伤害，在空中使用时会短暂滞留。\n旭日，对正前方范围内敌人造成2段145%物理近战黑暗属性劈砍伤害，若在空中使用会增加落地速度。\n玄月与鹰爪命中敌人后，可给予武士自身与距离武士自身16米范围内的玩家60秒的拔刀效果，提高10%职业增幅。\n玄月与鹰爪对持有麻痹的目标基础技能倍率提升至270%。\n每升一级伤害提升7.25%，最多升为10级。\n历史改动：\n- 7.2.8版本：增强技能，现在玄月与鹰爪对持有麻痹的目标技能倍率提升至270%。\n- 7.1.4版本：增强技能，基础伤害倍率由240%降低至145%，每级伤害倍率由12%降低至7.25%，攻击段数由1段增加至2段。\n- 7.0.8版本：增强技能，基础伤害倍率由200%提高至240%，每级伤害倍率由10%提高至12%。\n- 7.0.0版本：重制技能，魔力消耗由200降低至150，基础伤害倍率由400%降低至200%，现在命中敌人还会给予拔刀效果。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}, {"name": "飞鸭/流打", "url": "https://www.mcmod.cn/item/648593.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648593.png?v=6", "category": "武士:一转技能:主动技能", "description": "一转技能。\n消耗150魔力。\n残月，只能在地面时可用，横扫半径4米范围内的敌人，造成3段155%物理近战黑暗属性劈砍伤害并跳起两格高的距离。\n旭日，斩击正前方4米内最近的单个目标，造成3段155%物理近战黑暗属性劈砍伤害，并对目标敌人施加5秒的眩晕与5秒的缓慢Ⅲ。\n每升一级提升19.5%伤害，最多升为10级。\n历史改动：\n- 7.2.8版本：修正技能，流打施加的缓慢效果时间由100秒缩短至5秒。\n- 7.1.4版本：增强技能，基础伤害倍率由390%降低至155%，每级伤害倍率由19.5%降低至7.75%，攻击段数由1段增加至3段。\n- 7.0.8版本：增强技能，基础伤害倍率由325%提高至390%，每级伤害倍率由16%提高至19.5%。\n- 7.0.0版本：重制技能，魔力消耗由200降低至150，基础伤害倍率由500%/800%降低至325%，每级伤害倍率由10%提升至16%，现在流打命中敌人还会给予对方缓慢效果。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}, {"name": "燕返/居合", "url": "https://www.mcmod.cn/item/648594.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648594.png?v=4", "category": "武士:一转技能:主动技能", "description": "一转技能。\n消耗300魔力。\n残月，只能在空中时可用，连续对前方敌人造成5段180%物理近战黑暗属性劈砍伤害并向后方移动一定距离。\n旭日，对正前方范围内的敌人使出居合斩，造成5段180%物理近战黑暗属性劈砍伤害，当攻击范围内有目标与自身距离>1.5米时，每段攻击可为自身恢复300点生命值。\n每升一级提升9%伤害、居合提升15点恢复量，最多升为10级。\n历史改动：\n7.0.8版本：\n增强技能，基础伤害倍率由150%提高至180%，每级伤害倍率由7%提高至9%。\n7.0.0版本：\n重制技能，魔力消耗由400降低至300，基础伤害倍率由500%降低至150%，每级伤害倍率由15%降低至7%，现在居合对更远的敌人不再造成更大的伤害而是恢复一定量的生命值。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}, {"name": "天地流剑道", "url": "https://www.mcmod.cn/item/648595.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648595.png?v=6", "category": "武士:一转技能:被动技能", "description": "一转技能。\n仔细钻研拔刀术，最大化每一刀的效益，提高50%造成的伤害，获得20%重力伤害减免，获得抵抗击退效果，并且受到重力攻击时可免疫出血效果。使用不同的技能时将会记录，当武士释放与被记录的3个技能不同的技能时，将替换最早的记录，并获得15秒的天地流剑道效果：提高50%最终伤害，提高150%造成的伤害。\n历史改动：\n- 7.1.9版本：天地流剑道效果最终伤害加成由30%提高到50%，效果时长由12秒延长到15秒。\n- 7.0.8版本：天地流剑道效果增加到最终伤害与造成的伤害由20%/100%提高至30%/100%。\n- 7.0.0版本：由释放技能就能叠层改为释放4个不同的技能后获取效果，效果由1层10%造成的伤害，每提升1层增加5%造成的伤害改为固定增加20%最终伤害与100%造成的伤害。"}], "二转技能": [{"name": "天地流秘传", "url": "https://www.mcmod.cn/item/648596.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648596.png?v=10", "category": "武士:二转技能:被动技能", "description": "剑气上限增加10点，减少25%受到的伤害，受到麻痹重力球攻击时5%概率可以免疫麻痹效果，并且每次恢复剑气时有33.3%的几率额外补充1点。当释放任意主动技能、超级技能与瞬斩时，给予自身1层持续60秒的天地流秘传效果，提高20%造成的伤害，天地流秘传效果最高可以获得10层。\n注：额外恢复剑气对自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）均生效。\n历史改动：\n- 7.1.9版本：新增技能效果：减少25%受到的伤害，受到麻痹重力球攻击时有一定的概率可以免疫麻痹效果。剑气上限增加由8提高至10，天地流秘传效果每层提高伤害由10%提升到20%。\n- 7.1.4版本：增强技能，补充剑气额外恢复的概率由25%提高至33.3%。\n- 7.0.0版本：重制技能，现在天地流秘传不再提高天地流剑道效果等级上限，而是会给予天地流秘传效果。\n- 6.3.9版本：剑气上限增加由6提高至8，天地流剑道上限提升由7提高至9。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}, {"name": "受流/猛袭", "url": "https://www.mcmod.cn/item/648597.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648597.png?v=8", "category": "武士:二转技能:主动技能", "description": "消耗300魔力。\n残月，获得受流效果，持续3秒：持续时间内免疫可受防御减免的伤害。如果成功免疫，获得3秒格挡效果：最终伤害+30%。\n旭日，立即朝面向方向冲刺，并伤害路径上所有敌人，连续造成5段400%物理近战火焰属性劈砍伤害，对持有眩晕的目标基础技能倍率提升至525%。\n每升一级提升20%技能倍率，最多升为10级。\n历史改动：\n- 7.2.8版本：增强技能，现在猛袭对持有眩晕的目标基础技能倍率提升至525%。\n- 7.1.4版本：增强技能，基础伤害倍率由420%降低至400%，每级伤害倍率由21%降低至20%，攻击段数由4段增加至5段。\n- 7.0.8版本：增强技能，基础伤害倍率由350%提高至420%，每级伤害倍率由17%提高至21%。\n- 7.0.0版本：重制技能，旭日名称由龙尾改为猛袭，基础伤害倍率由300%提高至350%，每级伤害倍率由20%降低至17%。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}, {"name": "水车/一闪", "url": "https://www.mcmod.cn/item/648598.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648598.png?v=8", "category": "武士:二转技能:主动技能", "description": "消耗300魔力。\n残月，打出一圈斩击对前方区域内敌人造成5段330%物理近战源水属性劈砍伤害，在空中时会额外发射可穿透敌人的一道环形剑气，对接触到的敌人每tick造成1次330%物理近战源水属性劈砍伤害。\n旭日，只能在地面时可用，立即朝面向方向冲刺，并伤害路径上所有敌人，连续造成5段330%物理近战源水属性劈砍伤害并给予目标5秒的麻痹效果，同时给予武士自身2秒无敌效果与10秒一闪效果：一闪效果持续时间内再次释放一闪不会获得无敌效果，且会重置一闪效果的持续时间。\n每升一级提升16.5%伤害，最多升为10级。\n历史改动：\n- 7.2.8版本：削弱技能，现在一闪释放后会获得一闪效果，基础伤害倍率由360%下调至330%，每级伤害倍率由18%下调至16.5，一闪命中后会给予目标5秒麻痹效果。\n- 7.1.4版本：增强技能，基础伤害倍率由500%降低至360%，每级伤害倍率由25%降低至18%，攻击段数由3段增加至5段。\n- 7.0.8版本：增强技能，基础伤害倍率由420%提高至500%，每级伤害倍率由21%提高至25%。\n- 7.0.0版本：重制技能，基础伤害倍率由700%/300%调整至420%，每级伤害倍率由30%降低至21%。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}, {"name": "点水/鹰袭", "url": "https://www.mcmod.cn/item/648600.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648600.png?v=5", "category": "武士:二转技能:主动技能", "description": "消耗300魔力。\n残月，只能在空中时可用，对周身4米内的敌人造成2段320%物理近战源水属性劈砍伤害并往上跳跃一定的距离，同时向正下方发射一道可穿透敌人的剑气，对接触到的敌人每tick造成1次320%物理近战源水属性劈砍伤害，若使用时自身下方10格内没有可站立方块，则不会跳跃。\n旭日，只能在空中时可用，朝前方地板斜向下坠，落地后横扫周围所有目标，造成2段320%物理近战源水属性劈砍伤害。\n每升一级提升16%伤害，最多升为10级。\n历史改动：\n7.1.4版本：\n增强技能，基础伤害倍率由540%降低至320%，每级伤害倍率由27%降低至16%，攻击段数由1段增加至2段。\n7.0.8版本：\n增强技能，基础伤害倍率由450%提高至540%，每级伤害倍率由22.5%提高至27%。\n7.0.0版本：\n重制技能，基础伤害倍率由900%降低至450%，每级伤害倍率由30%降低至22.5%。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}, {"name": "月影/日轮", "url": "https://www.mcmod.cn/item/648601.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/648601.png?v=8", "category": "武士:二转技能:超级技能", "description": "消耗750魔力。\n残月，对附近所有敌人连续造成20次720%物理近战黑暗属性劈砍伤害，恢复所有剑气，并使玩家在接下来的15次恢复剑气时每次额外恢复3点剑气，同时使剑气上限临时提高20点，额外恢复次数耗尽后下次恢复剑气时将会移除临时剑气上限并移除超出上限的剑气。\n旭日，消耗所有剑气，对前方1名敌人连续造成20+ 消耗的剑气*5 次720%物理近战光明属性劈砍伤害，并获得 消耗的剑气*2+2 秒无敌效果。\n月影与日轮每次命中目标都会给予武士自身与附近16米范围内所有玩家90秒的光速斩切效果，提高10%职业增幅。\n技能冷却时间200秒。\n每升一级提升36%伤害，最多升为10级。\n注：月影的额外恢复剑气对自然恢复与普攻恢复（不包括拉普达/艾莉西亚太刀）均生效；日轮的剑气额外消耗计算在正常释放技能消耗剑气之后，因此给予的无敌时间与额外攻击次数以释放技能前的剑气-1来算，最低为0 真的会有人在1剑气的时候用日轮吗 。\n历史改动：\n- 7.1.9版本：冷却时间由300秒缩短至200秒。\n- 7.1.4版本：增强技能，基础伤害倍率由600%提高至720%，每级伤害倍率由30%提高至36%，现在日轮每消耗1点剑气可以增加5次攻击段数，现在月影可提供15次的额外恢复剑气与20点剑气上限。\n- 7.0.8版本：增强技能，基础伤害倍率由500%提高至600%，每级伤害倍率由25%提高至30%。\n- 7.0.0版本：重制技能，魔力消耗由1000降低至750，基础伤害倍率由3000降低至500%，移除月影的易伤黑雾效果，冷却时间由600秒降低至300秒，升级效果由减少20秒冷却改为增加25%每级伤害倍率。\n此段资料引用于“剑气值”并与其保持同步更新。  编辑除了月影/日轮和瞬斩，武士所有的技能都仅有1秒冷却时间，且释放技能需要消耗1点剑气值，连续释放相同的技能会额外消耗1点剑气值。\n剑气值每3.5秒恢复1点，使用任意太刀普通攻击命中时有33.3%概率额外恢复1点，若玩家滞空，则概率提升至50%。使用拉普达月光太刀/艾莉西亚的月光太刀普通攻击命中时将会有10%概率额外恢复1点，使用庇护者苍穹之泪普攻命中时恢复1点剑气。\n学习专精天流秘笈后缩短1秒恢复剑气间隔，学习专精聚精会神且天地流秘传层数达到10层时，缩短0.5秒恢复剑气间隔，瞬斩命中时，5秒内缩短0.5秒恢复剑气间隔。\n释放月影后将会获得15次额外恢复剑气机会，每次通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器的额外恢复）的方式恢复剑气时，都会额外恢复3点剑气。\n学习天地流秘传后通过自然恢复、普攻恢复（不包括拉普达/艾莉西亚武器）的方式恢复剑气时，每次都有33.3%的几率额外恢复1点。\n初始剑气上限为8点，学习天地流秘传后增加10点，学习专精地流秘笈一转增加3点、二转再增加3点，拥有释放月影后的额外恢复剑气机会时增加20点，恢复剑气时若当前剑气超出剑气上限则会移除超出的部分。\n历史改动：\n- 7.2.8版本：瞬斩冷却由1秒上调至5秒，不再依赖剑气：不需要持有剑气发动，也不会消耗剑气。\n- 7.1.9版本：天地流秘传的上限增加由8点提升至10点。\n- 7.1.6版本：现在任意太刀普攻命中都有几率恢复1点剑气。\n- 7.1.4版本：现在释放瞬斩后将会临时加快自然剑气恢复，释放月影后将会获得额外恢复剑气机会，天地流秘传额外恢复剑气几率由25%增加至33.3%\n- 7.0.0版本：现在专精也能缩短恢复剑气间隔。\n- 6.3.9版本：恢复剑气间隔由5秒提高至3.5秒。"}], "三转技能": [{"name": "天地流真传", "url": "https://www.mcmod.cn/item/948766.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948766.png", "category": "武士:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高100%造成的伤害，提高20%最终伤害。\n特殊能力\n基础信息\n- 技能倍率：420%\n- AOE半径：5米\n能力描述\n触发天地流剑道效果时，立刻发动一次斩切，对半径5米范围内所有敌人造成420%物理近战源水属性劈砍伤害，同时恢复400点魔力值。"}, {"name": "沚", "url": "https://www.mcmod.cn/item/948768.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948768.png", "category": "武士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：900%*4段\n- 真实物理伤害：40点*4段\n- AOE半径：5米\n- 负面效果：缓慢2*1秒\n- 负面半径：5米\n- 魔力消耗：300点\n- 冷却时间：1秒\n- 持太刀时按下设定的技能按键发动\n- 每升1级增加45%技能倍率\n技能描述\n技能效果\n挥舞太刀斩切，发出环形气刃，对5米范围内所有敌人造成4段900%物理近战暴风属性风切伤害，并施加1秒的缓慢II。\n额外效果\n该技能不消耗剑气。释放技能时，会立刻清除自身的动能，并向上跃起。\n你知道吗\n沚（zhǐ）：指水中的小块陆地。"}, {"name": "月蚀/日蚀", "url": "https://www.mcmod.cn/item/948769.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948769.png", "category": "武士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：900%*5段斩击+900%*1段爆炸\n- AOE半径：5米斩击+7米爆炸\n- 滞留伤害：900%*1段/秒*10秒\n- 滞留伤害半径：5米\n- 魔力消耗：600点\n- 冷却时间：40秒\n- 持太刀时按下设定的技能按键发动\n- 每升1级增加45%技能倍率\n技能描述\n技能效果\n咏唱光暗魔咒，一刀划破天空。\n残月架势时，对前方砍出一道劈斩并向后跳，劈砍将对5米范围内所有敌人造成5段900%物理近战光明属性波动伤害，同时呼唤月之石重击地面。\n旭日架势时，对前方砍出一道刺击并向后跳，劈砍将对5米范围内所有敌人造成5段900%物理近战光明属性波动伤害，同时呼唤日之石重击地面。\n月之石与日之石落地后会对7米范围内所有敌人造成1段等同于劈砍伤害的伤害，并在地面留下裂缝，每秒对月之石或日之石落点5米范围内所有敌人造成等同于劈砍伤害的伤害，裂缝至多持续10秒。\n额外效果\n释放月蚀/日蚀后的5秒内释放架势切换，会立刻再次释放一次切换架势后的月蚀/日蚀。"}, {"name": "无双乱舞", "url": "https://www.mcmod.cn/item/948771.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948771.png", "category": "武士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：100% * ?段\n- AOE半径：2米\n- 辅助能力-无双乱舞：30%造伤+10%职业增幅 * 120秒\n- 辅助半径：16米\n- 魔力消耗：600点\n- 冷却时间：240秒\n- 持太刀时按下设定的技能按键发动\n- 每升1级增加5%技能倍率\n技能描述\n技能效果\n握紧太刀，全力挥砍，给予自身与16米范围内所有玩家120秒无双乱舞：职业增幅+10%、造成的伤害+30%。向前方以极快的速度连续短距离冲刺，每次冲刺都会使出斩击，对2米范围内所有敌人造成100%物理近战暴风属性劈砍伤害。冲刺无法穿过方块。\n由于无双乱舞的冲刺是范围伤害，因此要打出尽量高的判定需要冲刺的开始与结束位置都与目标保持至少3米的距离，并且需要尽可能的对角冲刺目标的碰撞箱。\n无双乱舞BUFF的施加位置在冲刺开始前。\n额外效果\n释放无双乱舞后会额外获得6次无双乱舞充能，额外充能可以无视冷却释放，但无双乱舞的释放之间必须间隔至少2秒，包括首次无双乱舞的释放。\n额外充能可以长久储存，在技能冷却完毕后使用无双乱舞会优先消耗未使用完的额外充能，但也无法在额外充能消耗完前获得无双乱舞BUFF。"}, {"name": "居合．瞬杀", "url": "https://www.mcmod.cn/item/949045.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/949045.png", "category": "武士:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：900%*199斩\n- AOE半径：3米\n- 魔力消耗：1500点\n- 冷却时间：900秒\n- 持太刀时按下设定的技能按键发动\n- 每升1级增加45%技能倍率\n技能描述\n如同狂风般挥舞太刀，使斩出的旋风成为无尽的噩梦，在10秒内持续斩击并对附近3米范围内所有目标造成至多199段900%物理近战暴风属性风切伤害，最后一击将使出能斩破时空的强力斩击，同时给予自身1.25秒缓慢6。"}]}}, {"name": "暗骑士", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "极小", "生存": "很强", "刷本效率": "很高", "缺蓝": "缺", "对单": "偏弱", "特殊1": "嘲讽，群体解弱", "特殊2": "群体复活甲"}, "tiers": {"固有技能": [{"name": "自我复原", "url": "https://www.mcmod.cn/item/440062.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440062.png?v=4", "category": "暗骑士:固有技能", "description": "基础信息\n- 固有技能\n- 自我治疗：800点\n- 魔力消耗：100点\n- 持战锤时长按使用（默认右键）发动\n- 每升1级增加40点自我治疗量，最多升为10级\n技能描述\n架起防守态势，处于该状态时移动速度减少50%，每0.5秒消耗消耗100魔力并恢复800点生命值，每当结束自我复原时，会获得一层绝对抵御效果，可免疫一次混沌伤害以外的任何伤害，最多获得5层。处于自我复原的情况时，无法使用任何技能。\n恢复生命值与获得绝对抵御都有1秒的释放前摇。\n历史改动：\n- 7.0.0版本：重制技能，魔力消耗由150降低至100，恢复量由5%最大生命值改为800点生命值，现在不再提高防御能力，结束释放技能会获得1层绝对抵御。\n- 5.2.7版本：强化技能，正处于转换时，只会受到50%的伤害（在计算防御之前）。"}, {"name": "战吼", "url": "https://www.mcmod.cn/item/440065.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440065.png?v=8", "category": "暗骑士:固有技能", "description": "基础信息\n- 技能倍率：100%\n- AOE半径：16米\n- 负面效果：嘲讽*30秒\n- 负面半径：16米\n- 自拐能力-战吼：50%造伤+50防御力 * 20秒\n- 魔力消耗：200点\n- 冷却时间：5秒\n- 持战锤时按下武器功能键（默认V键）发动\n- 每升1级增加5%技能倍率，1秒战吼持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n奋力发出一吼，嘲讽距自身16米以内所有的怪物30秒，将其攻击目标设定为自身，并造成100%物理近战黑暗属性精神伤害，同时给予自身持续20秒的战吼效果，防御力提升50点，造成的伤害增加50%。\n职业专属\n学习3转被动回生盾墙后，战吼的效果将可以分享给距离自身16米以内的所有玩家，并使战吼效果增加1级：额外增加20%造成的伤害。\n历史改动：\n- 7.4.8版本：战吼效果的防御力增加由60降低至50，现在可以提高50%造成的伤害。\n- 7.2.4版本：战吼效果由造成伤害提升50%修改为防御力提升60点。\n- 7.0.0版本：重制技能，嘲讽时长由5秒延长至30秒，冷却时间由0秒延长至5秒，现在战吼可以造成伤害，升级效果由延长1秒嘲讽时间改为增加5%伤害倍率。\n- 6.2.0版本：增强技能，从提高20%攻击力加强至提高30%攻击力。"}], "一转技能": [{"name": "动地锤", "url": "https://www.mcmod.cn/item/440055.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440055.png?v=7", "category": "暗骑士:一转技能:主动技能", "description": "基础信息\n- 技能倍率：70%*4段/秒*10秒\n- 段数补正：1段登场伤害\n- AOE半径：2米\n- 负面效果：吸引*10秒\n- 负面半径：2.5米\n- 魔力消耗：400点\n- 冷却时间：30秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加3.5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n猛烈的锤击地面并在直线上隆起至多25道巨石，巨石能够攻击复数目标，每0.25秒对半径2米内的敌人造成70%物理近战大地属性地震伤害，巨石至多持续10秒，持续时间内将吸引2.5米半径内的怪物。\n动地锤对非BOSS目标造成伤害时，总技能倍率会提高至原先的1.3倍。\n每块巨石出现时，会额外造成一段伤害，并击飞怪物一段距离，额外伤害不受非BOSS目标加成。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.1.6版本：削弱技能，伤害系数由100%降低至70%，现在对非BOSS单位的伤害倍率将提升至1.3倍。\n- 7.0.0版本：重制技能，魔力消耗由500降低至400，伤害倍率由220%降低至100%，每级伤害倍率由10%降低至5%，冷却时间由60秒缩短至30秒，现在巨石可以吸引敌人。\n- 6.2.0版本：增强技能，伤害系数由150%提升至220%。\n- 6.1.8版本：增强技能，技能冷却时间由90秒降低到60秒。\n- 6.1.7版本：削弱技能，技能冷却时间由30秒提高到90秒。"}, {"name": "旋风斧", "url": "https://www.mcmod.cn/item/440056.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440056.png?v=6", "category": "暗骑士:一转技能:主动技能", "description": "基础信息\n- 技能倍率：250%\n- 段数补正：贯穿+弹射抛射物\n- 辅助能力-黑暗斩切：50%造伤+10%终伤+10%职业增幅 * 60秒\n- 辅助半径：10米\n- 魔力消耗：400点\n- 冷却时间：5秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加12.5%技能倍率，3秒黑暗斩切持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n将黑魔法注入飞斧中，然后使出全身的力量向前方抛射，对目标造成250%物理近战暴风属性劈砍伤害，对非BOSS生物的伤害倍率提高至原先倍率的1.2倍。旋风斧将在命中目标后自动转换目标，并在复数目标间多次弹跳，飞斧可以穿透实体，并在穿透与弹跳转弯的时候根据速度、转弯半径、怪物体型等因素额外造成多段伤害。旋风斧每次命中目标时，都将给予距离旋风斧10米内的玩家60秒的黑暗斩切效果，提高50%造成的伤害，提高10%最终伤害，提高10%职业增幅。同一把飞斧至多存在20秒，至多切换12次目标，随后消失。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.3.7版本：增强技能，伤害系数由200%提升至250%，每级伤害系数由10%提升至12.5%，现在最多切换12次目标。\n- 7.0.0版本：重制技能，魔力消耗由500降低至400，伤害倍率由400%降低至200%，移除弹射次数限制，现在命中敌人会给予黑暗斩切，且非BOSS生物伤害倍率会提高。\n- 6.2.0版本：增强技能，伤害系数由350%提升至400%。"}, {"name": "牺牲术", "url": "https://www.mcmod.cn/item/440058.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440058.png?v=9", "category": "暗骑士:一转技能:主动技能", "description": "基础信息\n- 技能倍率：250%*5段\n- AOE半径：10米\n- 辅助能力：净化\n- 辅助半径：10米\n- 自拐能力-牺牲：不再因战斗受到创伤 * 60秒\n- 范围治疗：6000点+3000临时生命值\n- 治疗半径：10米（除自身外）\n- 魔力消耗：200点\n- 生命损耗：50%当前生命\n- 冷却时间：25秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加12.5%技能倍率，300点范围治疗量，3秒牺牲持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n咏唱黑暗魔法，发挥强大的力量，使自己的生命值减半，并对半径10米内的怪物造成5段250%物理近战黑暗属性死亡伤害，同时医疗范围内除自身外所有玩家6000点生命值，给予范围内玩家3000点临时生命值，持续90秒，并解除包括自身在内的玩家部分负面状态效果。使用技能后将给予自身60秒的牺牲效果：持续时间内不会因受到攻击而获得创伤。\n可以解除的负面效果有：冰缓，蛊毒，黑暗祈祷，致命熔岩，破灭祈祷，剧毒，石化，冻结，沉默（沉默状态下可以使用牺牲术），抽搐，至残，瘫痪，同命，失明，饥饿，凋零，中毒，挖掘疲劳。\n可以解除的创伤有：皮肉伤、扭伤、拉伤、擦伤、脑震荡。\n专精能力\n当学习专精污染之血后，牺牲术将会立刻杀死当前生命值低于25%的非BOSS敌人。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.4.6版本：增强技能，现在牺牲术可以净化自己的负面效果。\n- 7.0.0版本：重制技能，魔力消耗由300降低至200，伤害倍率由300%最大生命值改为250%攻击力，治疗量由损失的血量改为6000点生命值，牺牲效果由5秒延长至60秒，现在还会给予队友临时生命值，技能升级效果由缩短1秒冷却时间改为增加倍率与治疗量。\n- 6.3.8版本：增强技能，现在释放牺牲术可以在短时间内免疫创伤。\n- 6.2.0版本：增强技能，现在对周遭怪物造成3倍最大生命值的伤害而不是2倍伤害了。\n- 5.6.7版本：现在牺牲术可以移除瘫痪效果。\n- 5.5.4版本：增强技能，牺牲术现在可以治疗部分创伤。"}, {"name": "防御体系", "url": "https://www.mcmod.cn/item/440003.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440003.png?v=4", "category": "暗骑士:一转技能:被动技能", "description": "属性提升\n提高5%造成的伤害，提高10%最终伤害，提高20%重力伤害减免，获得抵抗击退效果，并且受到重力伤害时可免疫出血效果。\n特殊能力\n受到伤害前，若当前生命值低于70%，提升30%受到的伤害减免。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.1.4版本：低生命减伤触发门槛由50%降低至70%，减伤幅度由40%降低至30%。\n- 7.0.0版本：效果由增加5点物理攻击力与200点最大生命值改为50%造成的伤害与10%最终伤害，现在低于半血还会获得40%减伤。"}], "二转技能": [{"name": "惊奇骨骼", "url": "https://www.mcmod.cn/item/443082.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443082.png?v=4", "category": "暗骑士:二转技能:被动技能", "description": "属性提升\n职业等级70级解锁2转后开放学习。\n提高50%造成的伤害，提高10%最终伤害，提高300点防御力。\n特殊能力\n自我复原的总治疗量提高50%。\n受到致死伤害时，将获得3秒无敌效果，并恢复全部生命值与血性值，冷却时间210秒。\n历史改动：\n- 7.2.8版本：现在惊奇骨骼还会在免死触发后给予3秒无敌效果并清除血性值。\n- 7.1.4版本：现在惊奇骨骼还会提高300点防御力，使自我复原总治疗量提高50%，技能冷却时间由150秒延长至210秒。\n- 7.0.0版本：现在惊奇骨骼还可以提高50%造成的伤害与10%最终伤害，冷却时间由50秒延长至150秒。"}, {"name": "暗影巨锤", "url": "https://www.mcmod.cn/item/443083.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443083.png?v=6", "category": "暗骑士:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：135%*4段/秒*20秒\n- AOE半径：4米\n- 负面效果：吸引*20秒\n- 负面半径：10米\n- 魔力消耗：600点\n- 冷却时间：40秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加6.75%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n呼唤黑暗的力量，发射黑暗魔球，黑暗魔球击中目标后，将降下暗影巨锤。暗影巨锤会持续吸引半径10米内的怪物，同时每0.25秒对半径4米内的怪物造成135%物理近战黑暗属性黑魔法伤害，暗影巨锤至多持续20秒。\n暗影巨锤对非BOSS目标造成伤害时，伤害倍率将提高至原先的1.3倍。\n历史改动：\n- 7.1.6版本：削弱技能，伤害倍率由190%降低至135%，现在对非BOSS单位的伤害倍率将提升至1.3倍。\n- 7.0.0版本：重制技能，魔力消耗由500提高至600，伤害倍率由800%降低至190%，每级伤害倍率由30%降低至9.5%，现在暗影巨锤会持续吸引怪物。\n- 6.1.8版本：技能冷却时间由60秒降低到40秒。\n- 6.1.7版本：技能冷却时间由15秒提高到60秒。"}, {"name": "炼狱之炎", "url": "https://www.mcmod.cn/item/443084.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443084.png?v=5", "category": "暗骑士:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：425%\n- AOE半径：3米\n- DOT倍率：50%*10段\n- 负面效果：缓慢I*3秒\n- 负面半径：3米\n- 易伤能力-炼狱：50%*60秒\n- 魔力消耗：800点\n- 冷却时间：15秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加21.25%技能倍率，3秒炼狱持续时间，0.15秒缓慢持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n凝聚炎之力量，同时往5个方向发射能够撕裂目标的致命熔岩，熔岩会向前方持续推进，并对途径的3米范围内的目标造成425%物理近战火焰属性毁灭伤害，同时对目标施加16秒的炼狱效果：受到的伤害增加+50%。命中时还会对目标施加10段持续伤害：每秒造成50%物理近战火焰属性毁灭持续伤害，持续10次。\n历史改动：\n- 7.4.8版本：DOT倍率由50%*技能倍率改为固定的50%。\n- 7.0.0版本：重制技能，魔力消耗由500提高至800，伤害倍率由900%降低至425%，每级伤害倍率由40%降低至21.25%，现在命中目标还能施加DOT伤害。\n- 5.6.7版本：增强技能，冷却时间由24秒降低为20秒。"}, {"name": "大地力量", "url": "https://www.mcmod.cn/item/443085.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443085.png?v=5", "category": "暗骑士:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 辅助能力-大地力量：50%造伤+10%职业增幅+免死 * 120秒\n- 辅助半径：16米\n- 魔力消耗：300点\n- 冷却时间：180秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加12秒大地力量持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n咏唱复杂的地之魔法，借此守护自己与队友，给予自身与半径16米范围内玩家120秒大地力量效果，提高50%造成的伤害，提高10%职业增幅，并在受到致命伤害时，可消耗该效果并抵销伤害。\n历史改动：\n- 7.1.4版本：削弱技能，大地力量冷却时间由120秒延长至180秒。\n- 7.0.0版本：重制技能，魔力消耗由500降低至300，持续时间由60秒延长至120秒，每级持续时间由4秒延长至12秒。"}, {"name": "天罡神盾", "url": "https://www.mcmod.cn/item/443086.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443086.png?v=6", "category": "暗骑士:二转技能:超级技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：750%*10段\n- AOE半径：12米\n- 辅助能力-天罡神盾：50%造伤+300防御力+50%减伤 * 40秒\n- 辅助半径：16米\n- 自拐能力-无敌：免疫绝对伤害以外的伤害 * 30秒\n- 魔力消耗：1500点\n- 冷却时间：600秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加37.5%技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n技能效果\n全神贯注，利用极为强大的意志来发挥黑暗骑士的真正力量，给予自身与半径16米范围内玩家40秒天罡神盾效果：造成的伤害+50%、防御力+300、受到的伤害减免+50%，同时额外给予自身30秒无敌效果：可以免疫绝对伤害以外的任何伤害。并对半径12米范围内所有怪物造成10次750%物理近战光明属性伤害。\n专精能力\n学习专精勇敢之心时，技能天罡神盾将不再给予自身无敌效果，但会给予附近玩家10秒无敌。\n历史改动：\n- 7.4.2版本：削弱技能，给予自身的无敌由40秒缩短至30秒，不再给予队友无敌，现在天罡神盾BUFF会增加防御力与免伤，专精效果给予队友80秒无敌效果改为10秒。\n- 7.0.0版本：重制技能，魔力消耗由800提高至1500，效果时长由30秒提高至40秒，现在可以造成10次750%倍率的伤害，升级效果由减少20秒CD改为增加37.5%倍率。"}], "三转技能": [{"name": "回生盾墙", "url": "https://www.mcmod.cn/item/947431.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947431.png", "category": "暗骑士:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高20%最终伤害，提高200点防御力，提高100%最大血性值，提高10%受到的伤害减免。\n特殊能力\n学习技能后使战吼效果可以分享给距离自身16米以内的所有玩家，并使战吼效果增加1级：额外增加20%造成的伤害。"}, {"name": "炼狱锁链", "url": "https://www.mcmod.cn/item/947433.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947433.png?v=1", "category": "暗骑士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：1200%*2段/秒*10秒\n- 真实物理伤害：30点*2段/秒*10秒\n- AOE半径：7米\n- 负面效果：缓慢6*30秒\n- 负面半径：7米\n- 易伤能力-囚禁：50%*30秒\n- 魔力消耗：600点\n- 冷却时间：180秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加60%技能倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n技能效果\n呼唤炼狱锁链，在指定地点召唤锁链，每0.5秒对球形半径7米范围内的敌人造成1200%物理近战黑暗属性穿刺伤害，同时持续对敌人施加20秒的缓慢6与20秒的囚禁：受到的伤害增加+50%，炼狱锁链至多持续10秒。\n你知道吗\n锁链共有24道，不过不会攻击，仅有装饰效果。"}, {"name": "雷电战斧", "url": "https://www.mcmod.cn/item/947606.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947606.png?v=1", "category": "暗骑士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：500%*40次电击+500%*4段爆炸+500%*1~2道闪电\n- AOE半径：5米\n- DOT倍率：300%*20段\n- 负面效果：吸引*10秒\n- 负面半径：5米\n- 魔力消耗：600点\n- 冷却时间：100秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加25%技能倍率\n- 冷却减免倍率：50%\n技能描述\n技能效果\n抛出威力强大的雷电战斧，命中后召唤雷霆电圈，每秒对球形半径5米范围内所有敌人每秒造成4次500%物理近战闪电属性雷霆伤害，同时持续吸引伤害范围内的敌人至电圈中心，雷霆电圈至多持续10秒。\n雷霆电圈消失时，会产生额外的爆炸，对球形半径5米范围内所有敌人造成4段等同于电圈的伤害，同时施加20段持续伤害：每秒造成300%物理近战闪电元素雷霆伤害，持续10次。\n额外效果\n雷电战斧还会在命中地点额外引来雷击，对小范围造成1~2段等同于电圈的伤害。"}, {"name": "深渊祈祷", "url": "https://www.mcmod.cn/item/947610.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947610.png?v=1", "category": "暗骑士:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 辅助能力-深渊祈祷：60%造伤+10%终伤+10%职业增幅 * 120秒\n- 辅助半径：32米\n- 范围治疗：22500点+6000临时生命值\n- 治疗半径：32米（除自身外）\n- 魔力消耗：600点\n- 生命损耗：50%当前生命+12秒不治\n- 冷却时间：240秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加1秒深渊祈祷持续时间，1125点范围治疗量\n- 冷却减免倍率：50%\n技能描述\n展开强大的黑暗魔咒，奉献自己的力量强化周遭所有队友，给予自身与距离自身32米以内的所有玩家持续120秒的深渊祈祷：提高60%造成的伤害，10%最终伤害，10%职业增幅。同时治疗除自身外所有玩家22500点生命值，并给予6000点临时生命值，临时生命值最多存在120秒。\n释放深渊祈祷会使自身损失50%当前生命值，同时获得12秒的不治效果：无法受到治疗。损失生命值不会致死。\n历史改动：\n- 8.0.0-RC3版本：增强技能，不治持续时间由120秒缩短至12秒。"}, {"name": "地狱之门", "url": "https://www.mcmod.cn/item/947716.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947716.png?v=2", "category": "暗骑士:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：1200%*200段震击\n- AOE半径：16米\n- DOT倍率：500%*10段\n- 炼狱之炎炼数量：40道\n- 魔力消耗：1500点\n- 冷却时间：900秒\n- 持战锤时按下设定的技能按键发动\n- 每升1级增加60%技能倍率\n- 冷却减免倍率：0%\n技能描述\n技能效果\n召唤强大的炼狱火焰焚烧一切，在目标位置召唤地狱之门，每0.2秒对球形半径16米范围内所有敌人造成1200%物理近战火焰属性地狱伤害，同时施加10段持续伤害：每秒造成500%物理近战火焰属性烧伤伤害，持续10次。地狱之门至多存在40秒。\n额外效果\n技能持续期间每秒向周围随机方向发射一道炼狱之炎的熔岩。"}]}}, {"name": "夜行者", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "小", "生存": "正常", "刷本效率": "高", "缺蓝": "不缺", "对单": "极高", "特殊1": "爆发极高", "特殊2": "有大输出极高"}, "tiers": {"固有技能": [{"name": "突刺术", "url": "https://www.mcmod.cn/item/439703.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/439703.png?v=11", "category": "夜行者:固有技能", "description": "基础信息\n- 自拐能力-突刺：50%造伤*5秒\n- 魔力消耗：300点\n- 武器冷却时间[1]：1秒\n- 持匕首时右击向前突刺，蹲下时释放可向上跳跃，挥动武器时无法释放\n- 每升1级增加1秒突刺BUFF持续时间，最多升为10级\n技能描述\n透过在短时间内连续踩踏地面来大幅提升移动速度，以相当快的速度向前方突刺，或向高处跳跃，同时给予自身5秒突刺效果：提高50%造成的伤害。\n[1]武器冷却时间特指使用武器进行冷却计算，该类型技能冷却不受到感知的影响，但玩家可以使用多把武器轮流释放并各自正常冷却。\n历史改动：\n- 7.0.8版本：修正技能，现在突刺术不再属于短刃类型。\n- 7.0.0版本：重制技能，消耗魔力从100提升至300，从每升级一次增加2%突刺效果伤害增幅变为每升级一次增加1秒突刺持续时间，且可以在地下城中产生位移了。\n- 6.2.0版本：增强技能，提高伤害的系数由30%提升至35%。"}, {"name": "短刃:飞毒刃", "url": "https://www.mcmod.cn/item/750656.html", "icon": "https://i.mcmod.cn/item/icon/128x128/75/750656.png?v=17", "category": "夜行者:固有技能", "description": "基础信息\n- 技能倍率：40%*3抛射物\n- 段数补正：2段\n- DOT倍率：50%*10段\n- 易伤能力-毒刃：10%*30秒\n- 魔力消耗：200点\n- 技能冷却时间：12秒\n- 持匕首时按下武器功能键（默认V键）发动\n- 每升1级增加2%技能倍率，2秒毒刃持续时间，最多升为10级\n- 冷却减免倍率：100%\n简单描述\n扇形掷出3把剧毒苦无，对命中目标造成少量伤害并施加DOT与易伤效果，消耗目标身上的暗杀标记少量增加苦无的伤害段数，每把苦无都能消耗全部层数并施加1层暗杀标记。\n学习被动三位一体后，若上个释放的技能不属于短刃，则释放该技能时获得以下效果：恢复10%MP；提升该次技能倍率；冷却除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有技能5%CD（至少1秒）；获得10秒增伤效果。\n详细描述\n命中效果\n扇形掷出3把涂有剧毒的苦无，每把苦无都可以对远距离目标造成2段40%物理近战自然属性毒药伤害，同时对目标施加30秒的毒刃效果：提高10%受到的伤害。\n额外效果\n剧毒苦无还会对命中的目标施加10段持续伤害：每秒造成50%物理近战自然属性毒药伤害，持续10次。\n职业专属\n剧毒苦无命中时若目标已持有暗杀标记效果，则清除所有暗杀标记层数，每清除1层可使该苦无的直接命中伤害增加1段，随后对目标重新施加1层暗杀标记，苦无消耗暗杀标记在施加之前，因此直接使3把苦无命中同个目标通常会因为反复消耗并施加层数打出8段命中伤害同时残留1层暗杀标记。\n三位一体\n短刃:飞毒刃属于短刃技能，学习一转被动三位一体后，若上个释放的技能属于忍法或暗器，则在释放短刃:飞毒刃时会恢复10%最大魔力值，使该次短刃:飞毒刃的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的5%（至少冷却1秒），获得持续10秒的强击效果：增加20%造成的伤害。\n专精能力\n学习左上角红色专精潜行刺杀后，使用短刃:飞毒刃清除暗杀标记可以获得20秒的潜行刺杀效果：降低25%受到的伤害。\n历史改动：\n- 7.4.8版本：DOT倍率由50%*技能倍率改为固定的50%，现在三位一体不再影响DOT倍率。\n- 7.4.3版本：直接命中伤害倍率由50%降低至40%，技能升级伤害倍率由2.5%降低至2%，DOT倍率由25%降低至20%，技能升级DOT倍率由1.25%降低至1%，冷却时间由8秒延长至12秒，直接命中伤害段数由1段提升至2段，现在可以消耗暗杀标记，消耗的每层提升1段直接命中伤害段数。\n- 7.2.8版本：现在会给予目标暗杀标记效果。\n- 7.0.8版本：现在飞毒刃属于短刃类型技能。"}], "一转技能": [{"name": "噬血术", "url": "https://www.mcmod.cn/item/439647.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/439647.png?v=11", "category": "夜行者:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 辅助能力-噬血：10%职业增幅+4%吸血 * 60秒\n- 辅助半径：32米\n- 魔力消耗：300点\n- 技能冷却时间：90秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加6秒噬血BUFF持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n透过刺激自己激发夜使者的力量，给予自身与距离自身32米内玩家60秒的噬血效果，提高10%职业增幅，并且每次攻击可以吸收伤害量的4%补充血性值。\n历史改动：\n- 7.0.0版本：重制技能，消耗魔力由500减少至300，持续时间由30秒延长至60秒，每级持续时间由4秒延长至6秒，技能冷却时间由50秒延长至90秒，现在嗜血效果可以给予范围玩家了。\n- 6.2.0版本：增强技能，造成的伤害提高系数由40%提升至45%。"}, {"name": "忍法:强雷袭", "url": "https://www.mcmod.cn/item/439648.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/439648.png?v=14", "category": "夜行者:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：105%*5抛射物\n- 段数补正：1直接命中+1.4段闪电（期望）\n- 魔力消耗：300点\n- 技能冷却时间：12秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加5.25%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n向前方连续投掷5支蕴含雷电元素的飞镖，对直接命中的目标造成105%物理近战雷电属性雷霆伤害，并在命中目标后呼唤闪电，每道闪电可以在原地造成1~2段伤害等同于直接命中的半径3米的范围伤害。\n职业专属\n强雷袭的飞镖直接命中与闪电命中还会对目标施加持续10秒的暗杀标记效果，每次释放强雷袭只能对每个目标施加1层暗杀标记，除非释放途中暗杀标记被消耗，暗杀标记至多叠加5层，每层暗杀标记都会使短刃:飞毒刃的总段数增加1段，或是短刃:十字连斩的总段数增加2段，又或是短刃:绝杀刃的绝杀刃效果增加1层、斩击段数增加2段。\n三位一体\n忍法:强雷袭属于忍法技能，学习一转被动三位一体后，若上个释放的技能属于短刃或暗器，则在释放忍法:强雷袭时会恢复10%最大魔力值，使该次忍法:强雷袭的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的5%（至少冷却1秒），恢复3000点生命值并补充3000点血性值。\n历史改动：\n- 7.4.3版本：调整技能，技能倍率由150%降低至105%，技能升级倍率由7.5%降低至5.25%，冷却时间由15秒缩短至12秒，现在一次忍法:强雷袭对每个目标都只能施加1层暗杀标记。\n- 7.2.8版本：调整技能，现在会给予目标暗杀标记效果。\n- 7.0.0版本：重制技能，魔力消耗由350降低至300，伤害倍率由420%降低至150%，每级伤害倍率由20%降低至7.5%。\n- 6.2.0版本：增强技能，飞镖伤害系数由400%提升至420%，雷电伤害系数由200%上调至与420%。\n- 6.1.4版本：削弱技能，伤害系数由500%下调为400%\n- 5.5.3版本：增强技能，技能伤害系数由200%变为500%。"}, {"name": "暗器:连环镖", "url": "https://www.mcmod.cn/item/439653.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/439653.png?v=15", "category": "夜行者:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：100%*25抛射物\n- 魔力消耗：300点\n- 技能冷却：12秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n扇形投掷5波，每波5把飞镖，对远距离目标至多造成25段100%物理近战暴风属性穿刺伤害。\n职业专属\n飞镖会对命中的目标施加持续10秒的暗杀标记效果，每次释放暗器:连环镖只能对每个目标施加1层暗杀标记，除非释放途中暗杀标记被消耗，暗杀标记至多叠加5层，每层暗杀标记都会使短刃:飞毒刃的总段数增加1段，或是短刃:十字连斩的总段数增加2段，又或是短刃:绝杀刃的绝杀刃效果增加1层、斩击段数增加2段。\n三位一体\n暗器:连环镖属于暗器技能，学习一转被动三位一体后，若上个释放的技能属于短刃或忍法，则在释放暗器:连环镖时会恢复10%最大魔力值，使该次暗器:连环镖的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的12%（至少冷却1秒），获得持续10秒的铁皮效果：防御力+36。\n历史改动：\n- 7.4.3版本：调整技能，冷却时间由8秒延长至12秒，现在一次暗器:连环镖对每个目标都只能施加1层暗杀标记。\n- 7.2.8版本：调整技能，现在会给予目标暗杀标记效果。\n- 7.0.0版本：重制技能，魔力消耗由200增加至300，伤害系数由230%降低至100%，每级伤害系数由10%降低至5%。\n- 6.2.0版本：增强技能，伤害系数由200%提升至230%。\n- 6.1.4版本：削弱技能，伤害系数由250%降低为200%。\n- 5.5.3版本：增强技能，伤害系数由150%变为250%。"}, {"name": "三位一体", "url": "https://www.mcmod.cn/item/442618.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442618.png?v=8", "category": "夜行者:一转技能:被动技能", "description": "属性提升\n职业等级5级后开放学习。\n提高100%造成的伤害，提高10%最终伤害，提高20%重力伤害减免，获得抵抗击退效果，并且受到重力伤害时可免疫出血效果。\n特殊能力\n不断的学习暗杀技巧，并吸取黑夜的力量来提高自己的能力。\n夜行者的技能分为短刃、暗器、忍法三个类型。当使用的技能类型与上一个使用的技能不同时，立即补充10%最大魔力值，使该次释放的技能总倍率提升至1.2倍，并减少突刺术、忍法:刀刃迷宫、忍法:黑炎修罗斩以外的所有技能5%的冷却时间（至少1秒），同时根据该次释放技能的类型获得特殊效果。\n暗器类：获得10秒铁皮效果；技能冷却量由5%增加至12%（至少1秒）。\n短刃类：获得10秒强击效果；对命中的目标消耗所有暗杀标记，每个标记让攻击的段数增加，短刃:飞毒刃增加1段，短刃:十字连斩增加2段，短刃:绝杀刃的绝杀刃效果增加1层、斩击段数增加2段（暗杀标记相关能力不需要激活三位一体也能触发）。\n忍法类：恢复自身3000点生命值；同时补充自身3000点血性值。\n技能类型分类，暗器：连环镖、匕首剑舞、黑炎咒。\n技能类型分类，短刃：飞毒刃、十字连斩、绝杀刃。\n技能类型分类，忍法：强雷袭、刀刃迷宫、黑炎修罗斩。\n历史改动：\n- 7.4.3版本：调整技能，从二转被动移动至一转被动，增加10%最终伤害，移除普通攻击概率立即杀死非魔王目标，冷却技能从第三个类型改为除终极技能外所有技能，BUFF由3秒延长至10秒，回血由恢复9%最大生命改为恢复3000点生命值并补充3000点血性值。\n- 7.0.8版本：修正技能，短刃由突刺术改为飞毒刃。\n- 7.0.0版本：重制技能，移除背刺伤害、暴击伤害、技能最终伤害增益、移除刀刃迷宫CD缩短效果，现在可以增加100%造成的伤害。\n- 6.0.9版本：增强技能，拥有新效果：使用与上一个不同种类的技能时，本次技能的最终伤害+30%、恢复10% MP且触发技能特殊效果。\n- 5.6.2版本：增强技能，现在背刺攻击时，造成的伤害提升100%。"}], "二转技能": [{"name": "黑夜契约", "url": "https://www.mcmod.cn/item/438507.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438507.png?v=6", "category": "夜行者:二转技能:被动技能", "description": "属性提升\n职业等级70级解锁2转后开放学习。\n提高100%造成的伤害。\n特殊能力\n在历经长年的暗杀磨练后，领悟暗杀者的真谛。\n普通攻击时，有4%概率立即杀死非魔王目标。每当普通攻击命中敌人时，将给予目标持续63秒的黑夜契约效果：受到的伤害增加+10%。当击败拥有黑夜契约效果的目标时，黑夜契约会扩散到半径6米范围内所有敌人身上，扩散的黑夜契约会刷新持续时间。\n专精能力\n学习左下角蓝色专精血色悬赏后，杀死拥有黑色契约效果的单位还会恢复自身10%血性值。\n学习右上角蓝色专精黑夜刺杀后，黑色契约效果等级提升1级：受到的伤害提高量再增加10%。但是杀死拥有黑色契约效果的单位时黑色契约不再会扩散。\n历史改动：\n- 7.4.3版本：调整技能，从一转被动移动至二转被动，移除10%最终伤害，增加普通攻击概率立即杀死非魔王目标。\n- 7.0.0版本：重制技能，移除物理攻击力、回避率、暴击伤害增益，现在可以提高100%造成的伤害与10%最终伤害，现在普通攻击命中敌人有概率给予黑色契约效果。"}, {"name": "暗器:匕首剑舞", "url": "https://www.mcmod.cn/item/442619.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442619.png?v=16", "category": "夜行者:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习。\n- 技能倍率：168%*15抛射物\n- DOT倍率：50%*10段\n- 易伤能力-剧毒斩：10%*30秒\n- 魔力消耗：600点\n- 技能冷却时间：12秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加8.4%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n扇形投掷3波，每波5把匕首，对远距离目标造成至多15段168%物理近战自然属性穿刺伤害，并给予目标30秒的剧毒斩效果：提高10%受到的伤害。\n额外效果\n匕首还会对命中的目标施加10段持续伤害：每秒造成50%物理近战原水属性酸性伤害，持续10次。\n职业专属\n匕首会对命中的目标施加持续10秒的暗杀标记效果，每次释放暗器:匕首剑舞只能对每个目标施加1层暗杀标记，除非释放途中暗杀标记被消耗，暗杀标记至多叠加5层，每层暗杀标记都会使短刃:飞毒刃的总段数增加1段，或是短刃:十字连斩的总段数增加2段，又或是短刃:绝杀刃的绝杀刃效果增加1层、斩击段数增加2段。\n三位一体\n暗器:匕首剑舞属于暗器技能，学习一转被动三位一体后，若上个释放的技能属于短刃或忍法，则在释放暗器:匕首剑舞时会恢复10%最大魔力值，使该次暗器:匕首剑舞的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的12%（至少冷却1秒），获得持续10秒的铁皮效果：防御力+36。\n历史改动：\n- 8.0.0-RC3版本：修正技能，现在能正常施加DOT。\n- 7.4.3版本：调整技能，技能倍率由240%降低至168%，技能升级倍率由12%降低至8.4%，DOT倍率由120%降低至84%，DOT升级倍率由6%降低至4.2%，匕首数量由25减少至15，冷却时间由24秒缩短至12秒，现在一次暗器:匕首剑舞对每个目标都只能施加1层暗杀标记。\n- 7.2.8版本：调整技能，现在会给予目标暗杀标记效果。\n- 7.0.0版本：重制技能，魔力消耗由400提高至600，伤害倍率由720%降低至240%，每级倍率由15%降低至12%，现在给予对方的时剧毒斩而不是弱点标记，效果持续时间由16秒延长至30秒。\n- 6.1.4版本：削弱技能，伤害倍率由900%降低为720%。\n- 5.5.3版本：增强技能，伤害倍率由300%变为900%。"}, {"name": "短刃:十字连斩", "url": "https://www.mcmod.cn/item/442620.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442620.png?v=14", "category": "夜行者:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习。\n- 技能倍率：550%*2斩\n- AOE半径：3米斩击\n- 魔力消耗：800点\n- 技能冷却时间：24秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加27.5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n划出十字型的斩击，攻击前方范围内的所有目标，至多造成2段550%物理近战黑暗属性劈砍伤害.\n额外效果\n十字连斩每次斩击命中的每个目标都能补充自身4%最大生命值的血性值。\n职业专属\n若目标身上拥有暗杀标记效果，则会消耗所有暗杀标记层数，每层效果都会使消耗标记的那段斩击的伤害段数增加2段，十字连斩一次斩击命中会立刻清除暗杀标记，因此第二次斩击难以受到暗杀标记加成，暗杀标记增加的段数不会提高血性值补充量。\n三位一体\n短刃:十字连斩属于短刃技能，学习一转被动三位一体后，若上个释放的技能属于忍法或暗器，则在释放短刃:十字连斩时会恢复10%最大魔力值，使该次短刃:十字连斩的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的5%（至少冷却1秒），获得持续10秒的强击效果：增加20%造成的伤害。\n专精能力\n学习左上角红色专精潜行刺杀后，使用短刃:十字连斩清除暗杀标记可以获得20秒的潜行刺杀效果：降低25%受到的伤害。\n历史改动：\n- 7.4.3版本：调整技能，技能倍率由275%提升至550%，技能升级倍率由13.75%提升至27.5%，冷却时间由8秒延长至24秒。\n- 7.2.8版本：增强技能，现在可以消耗暗杀标记层数为十字连斩提升段数，每层提升2段伤害。\n- 7.0.0版本：重制技能，魔力消耗由400增加至800，伤害系数由1000%降低至275%，十字连斩命中敌人不再恢复生命值而是恢复血性值，移除命中敌人给予致命刺击效果。\n- 6.1.4版本：削弱技能，伤害系数由1200%降低为1000%。\n- 5.6.7版本：增强技能，现在十字连斩将额外给予目标致命刺击效果。\n- 5.5.3版本：增强技能，伤害系数由900%提高为1200%。"}, {"name": "孤注一掷", "url": "https://www.mcmod.cn/item/442621.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442621.png?v=10", "category": "夜行者:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 辅助能力-孤注一掷：50%造伤+10%终伤+10%职业增幅 * 60秒\n- 辅助半径：32米\n- 自拐能力-竭尽所能：30%终伤+40%自身受到的伤害增加 * ?秒\n- 魔力消耗：300点\n- 技能冷却时间：90秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加6秒孤注一掷BUFF持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n不考虑长久作战，将自身的力量全部施放，给予自身与距离自身32米内所有玩家60秒的孤注一掷效果：造成的伤害+50%，最终伤害+10%，职业增幅+10%。并立即重置自身所有一转技能的冷却时间。\n在已经持有孤注一掷效果时再次使用该技能（需要正在冷却中）可消耗800魔力来获得第二个效果竭尽所能：自身受到的伤害增加+40%与最终伤害+30%。竭尽所能的持续时间为孤注一掷的剩余时间+1秒。\n历史改动：\n- 7.2.8版本：增强技能，竭尽所能提供的最终伤害加成由20%提高至30%。\n- 7.0.0版本：重制技能，魔力消耗由400提高至800，持续时间由20秒延长至60秒，冷却时间由100秒缩短至90秒，每级持续时间由2秒延长至6秒，现在在持有孤注一掷效果时蹲下再次释放技能可以获得竭尽所能效果，现在孤注一掷效果可以给予范围玩家。"}, {"name": "忍法:刀刃迷宫", "url": "https://www.mcmod.cn/item/442976.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442976.png?v=13", "category": "夜行者:二转技能:超级技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习。\n- 技能倍率：255%*10段/秒*30秒/每个抛射物\n- AOE半径：2米\n- 魔力消耗：1500点\n- 技能冷却时间：600秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加12.75%技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n技能效果\n施展强大的咒语，在极短的时间内召唤无数锋利刀刃。\n逐渐的扇形铺开7排刀刃，每把刀刃每秒对2米范围内的敌人造成10段255%物理近战暴风属性风切伤害，在空旷处使用能够呼唤更多的刀刃，每把刀刃最多存在30秒。\n注：由于同直线的刀刃间隔略大于4米，因此在攻击范围内的敌人往往会同时受到2把刀刃的攻击，处于第一圈中心刀刃与第二圈中心刀刃中间时，可受到4把刀刃的攻击，最高可打出1200段伤害，此时要求释放时距离目标7米，正好是普通攻击触及不到的距离+1格。\n三位一体\n忍法:刀刃迷宫属于忍法技能，学习一转被动三位一体后，若上个释放的技能属于短刃或暗器，则在释放忍法:刀刃迷宫时会恢复10%最大魔力值，使该次忍法:刀刃迷宫的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的5%（至少冷却1秒），恢复3000点生命值并补充3000点血性值。\n历史改动：\n- 7.0.0版本：重制技能，魔力消耗由800提高至1500，伤害系数由800%降低至255%，升级效果由缩短20秒CD改为增加12.75%伤害系数，提高刀刃迷宫攻击速度。\n- 6.1.4版本：削弱技能，伤害系数由1000%降低为800%。\n- 5.5.3版本：增强技能，伤害系数由400%变为1000%，并大幅提高技能的持续时间。"}], "三转技能": [{"name": "致命连击", "url": "https://www.mcmod.cn/item/946913.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946913.png?v=1", "category": "夜行者:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高50%造成的伤害，提高20%最终伤害。\n特殊能力\n基础信息\n- 技能倍率：1050%\n- 伤害半径：6米\n- 负面效果-暗杀标记：被短刃类技能命中时，消耗暗杀标记增加伤害段数*252秒\n- 负面半径：6米\n能力描述\n在地下城使用瞬身术的冷却时间减半，强化三位一体：每次成功触发三位一体时，立即对距离自身6米范围内所有目标造成1050%物理近战火焰属性岩浆伤害，同时给予1层暗杀标记，持续252秒，暗杀标记至多叠加至5层。"}, {"name": "暗器:黑炎咒", "url": "https://www.mcmod.cn/item/947024.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947024.png?v=3", "category": "夜行者:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：600%*15抛射物\n- DOT倍率：300%*10段\n- 滞留伤害：600%*4段/秒*10秒*15抛射物\n- 滞留伤害半径：2米，覆盖范围内无法再生成新的\n- 魔力消耗：600点\n- 冷却时间：20秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加30%技能倍率、30%滞留伤害倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n命中效果\n将附魔火焰注入飞镖中，使其蕴含强大的黑炎力量，扇形抛出3波、每波5枚附魔飞镖，每枚飞镖对远距离目标造成600%物理近战火焰属性岩浆伤害。\n附魔飞镖会在命中方块或实体后发生爆炸，产生黑炎风暴，黑炎风暴每秒对半径2米范围内的敌人造成4次600%物理近战火焰属性岩浆伤害，至多持续10秒。\n属于自己的黑炎风暴的攻击范围内无法生成新的自己的黑炎风暴，因此无法同时重叠15个黑炎风暴，但怪物可同时接触到少量的黑炎风暴。暗器:黑炎咒的黑炎风暴与忍法:黑炎修罗斩的黑炎风暴属于同一种，会相互占用位置，忍法:黑炎修罗斩的黑炎风暴攻击频率比暗器:黑炎咒的黑炎风暴更高。\n额外效果\n附魔飞镖还会对命中的目标施加10段持续伤害：每秒造成300%物理近战火焰属性烧伤伤害，持续10次。\n职业专属\n飞镖会对命中的目标施加持续10秒的暗杀标记效果，每次释放暗器:黑炎咒只能对每个目标施加1层暗杀标记，除非释放途中暗杀标记被消耗，暗杀标记至多叠加5层，每层暗杀标记都会使短刃:飞毒刃的总段数增加1段，或是短刃:十字连斩的总段数增加2段，又或是短刃:绝杀刃的绝杀刃效果增加1层、斩击段数增加2段。\n三位一体\n暗器:黑炎咒属于暗器技能，学习一转被动三位一体后，若上个释放的技能属于短刃或忍法，则在释放暗器:黑炎咒时会恢复10%最大魔力值，使该次暗器:黑炎咒的附魔飞镖、黑炎风暴技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的12%（至少冷却1秒），获得持续10秒的铁皮效果：防御力+36。"}, {"name": "短刃:绝杀刃", "url": "https://www.mcmod.cn/item/947073.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947073.png?v=3", "category": "夜行者:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：600%*10斩\n- 段数补正：2段斩击\n- 真实物理伤害：40点*10斩*2段\n- AOE半径：4米斩击\n- 自拐能力-绝杀刃：3%造伤 * 最大30层 * 60秒\n- 魔力消耗：600点\n- 冷却时间：20秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加30%技能倍率，1秒绝杀刃持续时间，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n命中效果\n挥舞手中的锐利匕首，以华丽的刀法斩切目标，对前方距离自身4米以内所有目标发动10次斩击，每次斩击造成2段600%物理近战暴风属性切割伤害。同时每段斩击伤害还将额外附加40点真实物理伤害。\n职业专属\n一次短刃:绝杀刃将会对单个持有0/1/2/3/4/5层暗杀标记的目标造成20/58/60/62/66/68段伤害，详细规则如下：\n一次斩击成功命中拥有至少1层暗杀标记的目标时会立刻消耗暗杀标记，并触发如下效果：每消耗1层暗杀标记会使该次斩击增加2段伤害，可无限叠加，仅对当次斩击生效，并对目标返还持续10秒、75%消耗层数的暗杀标记效果，至少返还2层暗杀标记。此外每消耗1层暗杀标记，都会给予自身该次斩击共消耗的暗杀标记总层数的绝杀刃效果：每层使造成的伤害增加+3%，持续60秒，最多叠加30层。\n一次斩击同时命中多个敌人时，将逐个消耗标记、增加段数、返还标记、叠加绝杀刃，因此其它敌人不仅会受到自身应有的伤害，还会额外受到来自前一个被斩击命中的敌人的斩击段数增加的伤害。\n斩击命中的敌人未持有暗杀标记时，将不会触发消耗层数增加段数并返还标记，但仍可以受到该次斩击内由其它怪物提供的段数增加效果。\n由于短刃:绝杀刃会不断刷新暗杀标记，因此其它拥有单个技能内仅能施加一次暗杀标记限制的技能也能突破该限制，能使短刃:绝杀刃的伤害段数略微增加。\n三位一体\n短刃:绝杀刃属于短刃技能，学习一转被动三位一体后，若上个释放的技能属于忍法或暗器，则在释放短刃:绝杀刃时会恢复10%最大魔力值，使该次短刃:绝杀刃的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫、忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的5%（至少冷却1秒），获得持续10秒的强击效果：增加20%造成的伤害。"}, {"name": "轮回幻影", "url": "https://www.mcmod.cn/item/947100.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947100.png?v=2", "category": "夜行者:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：100%*62~82抛射物\n- 索敌半径：10米\n- 辅助能力-轮回幻影：10无敌帧+30回避值+10%职业增幅 *120秒\n- 辅助半径：10米\n- 魔力消耗：1000点\n- 冷却时间：240秒\n- 持匕首时按下设定的技能按键发动\n- 每升1级增加5%技能倍率，1秒轮回幻影效果持续时间，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n将自己藏身在黑暗中，以无尽的轮回黑暗保护自己，给予自身与附近10米内所有玩家持续120秒的轮回幻影：无敌帧+10、回避值+30、职业增幅+10%。施放后会召唤2个影分身在自身附近并跟随玩家的动作，每个影分身每1.5~2秒会投掷1个飞镖，攻击10米内随机目标，造成100%物理近战魔法属性隐化伤害，影分身无其它特殊效果，影分身至多持续60秒。"}, {"name": "忍法:黑炎修罗斩", "url": "https://www.mcmod.cn/item/947158.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947158.png?v=4", "category": "夜行者:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：900%*60斩\n- AOE半径：4米斩击\n- 滞留伤害：900%*5段/秒*10秒*60斩\n- 滞留伤害半径：2米，玩家周围1米已有黑炎风暴时不会生成新的\n- 自拐能力-黑炎修罗斩：100%造伤+10%终伤+持续时间内可以释放黑炎修罗斩 *10秒\n- 自我治疗：全部生命值\n- 魔力消耗：1500点\n- 冷却时间：900秒\n- 持匕首时按下设定的技能按键发动，随后按下突刺技能键开始突刺\n- 每升1级增加45%技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n技能效果\n举起手中的刀刃，化身为暗影中的屠杀恶魔，补充自身全部生命值，并给予自身持续10秒的无敌、缓慢与黑炎修罗斩：造成的伤害+100%、最终伤害+10%。黑炎修罗斩BUFF持续时间内使用突刺术将改为朝向面相的方向发动斩击，并高速向目标突刺10次，连续多次使用突刺术可以重置斩击与突刺次数。每次斩击会对前方4米范围内的敌人造成900%物理近战光明属性劈砍伤害，同时斩击的路径上将斩出数道产生黑炎风暴，黑炎风暴每秒对半径2米范围内的敌人造成5次900%物理近战火焰属性岩浆伤害，至多持续10秒。生成黑炎风暴时，若玩家周围1米内已有黑炎风暴，则不会生成新的，暗器:黑炎咒的黑炎风暴与忍法:黑炎修罗斩的黑炎风暴属于同一种，会相互占用位置，忍法:黑炎修罗斩的黑炎风暴攻击频率比暗器:黑炎咒的黑炎风暴更高。\n由忍法:黑炎修罗斩释放的突刺也会给予与突刺术相同的突刺效果。\n职业专属\n斩击会对目标施加持续10秒、5级的暗杀标记效果，无法叠加，每层暗杀标记都会使短刃:飞毒刃的总段数增加1段，或是短刃:十字连斩的总段数增加2段，又或是短刃:绝杀刃的绝杀刃效果增加1层、斩击段数增加2段。\n三位一体\n忍法:黑炎修罗斩属于忍法技能，学习一转被动三位一体后，若上个释放的技能属于短刃或暗器，则在释放忍法:黑炎修罗斩时会恢复10%最大魔力值，使该次忍法:黑炎修罗斩的技能倍率提升至原先的1.2倍，使除忍法:刀刃迷宫与忍法:黑炎修罗斩外所有职业技能立刻冷却其最大冷却时间的5%（至少冷却1秒），恢复3000点生命值并补充3000点血性值。 虽然黑炎修罗斩本身就会恢复全部生命"}]}}, {"name": "大法师", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "小", "生存": "正常", "刷本效率": "很高", "缺蓝": "不缺", "对单": "较高", "特殊1": "群体无限魔力", "特殊2": "爆发输出"}, "tiers": {"固有技能": [{"name": "魔力律动", "url": "https://www.mcmod.cn/item/438404.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438404.png?v=5", "category": "大法师:固有技能", "description": "基础信息\n- 固有技能\n- 辅助能力：恢复所有玩家魔力至满\n- 辅助半径：32米\n- 自拐能力-魔力律动：50%造伤+70%普攻魔力减免 * 60秒\n- 魔力消耗：100点\n- 冷却时间：90秒\n- 持法杖潜行状态下按下武器功能键（默认V键）发动\n- 每升1级增加6秒魔力吸收持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n聚精会神、将体内蕴含的魔力全部施放，恢复自身与距离自身32米内的所有玩家全部魔力值，并给予自身60秒的魔力律动效果：造成的伤害+50%，使用法杖时普通攻击消耗魔力值-70%。\n历史改动：\n- 7.2.8版本：增强技能，现在拥有魔力吸收效果时，大法师的普通攻击消耗魔力值-70%。\n- 7.0.0版本：现在可以恢复范围玩家全部魔力值，冷却时间由0秒延长至90秒，魔力吸收效果移除攻击恢复魔力，改为增加50%造成的伤害。\n- 5.4.9版本：攻击恢复的魔力值由100点降低至50点。"}, {"name": "寒冰咒", "url": "https://www.mcmod.cn/item/438405.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438405.png?v=6", "category": "大法师:固有技能", "description": "基础信息\n- 固有技能\n- 技能倍率：75%*4段/秒*2.5秒\n- AOE半径：1米，逐渐扩散至10米\n- 负面效果：缓慢3+冰缓*7.5秒\n- 负面半径：1米，逐渐扩散至10米\n- 魔力消耗：200点\n- 冷却时间：10秒\n- 持法杖时按下武器功能键（默认V键）发动\n- 每升1级增加3.75%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n利用严寒之力，召唤寒冰魔法阵在脚下。魔法阵会逐渐扩大，每0.25秒对范围内的敌人造成75%魔法攻击寒冰属性冻伤伤害，并施加5秒的缓慢Ⅲ与冰缓效果。魔法阵至多存在2.5秒，半径初始1米，至多扩大至10米。寒冰咒只能在地面时使用。\n职业专属\n学习3转被动大师魔导后，寒冰咒的总技能倍率将提高至原先的3倍。\n历史改动：\n- 7.0.0版本：重制技能，修改技能名称与图标，伤害系数由150%降低至75%，每级伤害系数由10%降低至3.75%，现在还可以给予怪物缓慢与冰缓效果。\n- 6.2.0版本：增强技能，伤害系数由50%增强到150%。"}], "一转技能": [{"name": "魔力盾", "url": "https://www.mcmod.cn/item/438395.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438395.png?v=3", "category": "大法师:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 辅助能力-魔力盾：10%职业增幅+100防御力 * 60秒\n- 辅助半径：32米\n- 魔力消耗：300点\n- 冷却时间：60秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加6秒魔力盾持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n召唤防护魔法，张开防御魔法盾，并将魔力注入于盔甲中，给予自身与距离自身32米范围内玩家60秒的魔力盾效果，提高10%职业增幅，提高100点防御力。\n历史改动：\n- 7.0.0版本：重制技能，魔力消耗由500降低至300，魔力盾持续时间由30秒延长至60秒，每级持续时间由4秒延长至6秒，现在可以给予范围玩家魔力盾效果。"}, {"name": "魔法箭", "url": "https://www.mcmod.cn/item/438400.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438400.png?v=6", "category": "大法师:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：100%*12抛射物\n- 易伤能力-魔箭：10%*30秒\n- 魔力消耗：400点\n- 冷却时间：16秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加5%技能倍率，2秒魔箭持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n张开魔力弹幕，连续召唤12发魔法诱导箭矢，对目标造成100%魔法攻击魔法属性波动伤害，同时对目标施加魔箭效果：受到的伤害增加+10%。\n当拥有无限魔力效果时，魔法诱导箭矢增加4发，由12发提高至16发。\n历史改动：\n- 7.3.5版本：增强技能，拥有无限魔力效果时，魔法诱导箭矢增加4发。\n- 7.0.0版本：重制技能，伤害系数由200%降低至100%，每级伤害系数由10%降低至5%，箭矢数量由16减少至12。\n- 6.2.0版本：增强技能，伤害系数由150%增加到200%。"}, {"name": "爆裂弹", "url": "https://www.mcmod.cn/item/438403.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438403.png?v=5", "category": "大法师:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：55%*9抛射物\n- 段数补正：1直接命中+1爆炸\n- AOE半径：4米\n- 自拐能力-魔焰：50%造伤 * 60秒\n- 魔力消耗：200点\n- 冷却时间：10秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加2.75%技能倍率，3秒魔焰持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n呼唤炎之魔咒，召唤数道火焰球袭击目标，火焰球共3波，每波3个呈扇形分布，共9个，对命中目标造成55%魔法攻击火焰属性烧伤伤害，并在命中目标后引燃火焰魔法，造成半径4米、伤害等同于直接命中伤害的范围伤害，使用魔焰弹时，可给予自身60秒魔焰效果：造成的伤害+50%。\n当存在无限魔力效果时，火焰球增加一波，总数由9个提高至12个。\n历史改动：\n- 7.3.5版本：增强技能，无限魔力效果存在时，火焰球增加一波。\n- 7.0.0版本：重制技能，伤害系数由300%降低至55%，每级伤害系数由20%降低至2.75%，现在释放技能会给予自身魔焰效果，技能名称改为魔焰弹。\n- 6.2.0版本：增强技能，伤害系数由250%增加到300%。"}, {"name": "法力精通", "url": "https://www.mcmod.cn/item/438394.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438394.png?v=4", "category": "大法师:一转技能:被动技能", "description": "属性提升\n职业等级5级后开放学习。\n提高50%造成的伤害，提高10%最终伤害，提高1000点最大魔力值。\n获得击退抵抗。\n历史改动：\n- 7.3.7版本：增强技能，现在还会使玩家免疫击退。\n- 7.0.0版本：重制技能，移除魔法攻击力与暴击率增益，现在可以提高10%最终伤害、50%造成的伤害、1000点最大魔力值。"}], "二转技能": [{"name": "魔力存储", "url": "https://www.mcmod.cn/item/442608.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442608.png?v=12", "category": "大法师:二转技能:被动技能", "description": "属性提升\n职业等级70级解锁2转后开放学习。\n提高1000点最大魔力值。\n特殊能力\n每5秒将获得一层魔力存储效果，每层效果提升2%最终伤害、20%造成的伤害，最多叠加至5层。\n受到可以被防御力减免的攻击类型时将失去一层魔力储存效果，并使本次受到的伤害减免+50%。\n达到最大层数5层时,可增加一个法力风暴的数量上限。\n专精能力\n学习专精高速存储时，魔力存储间隔减少2秒，抵御伤害时伤害减免增加量减少至25%。\n学习专精强化存储时，魔力存储间隔增加2秒，抵御伤害时可以完全抵御。\n历史改动：\n- 7.2.8版本：增强技能，受到伤害后，失去所有魔力储存效果改为失去一层魔力储存效果\n- 7.0.0版本：变更技能消灭魔法并改名为魔力存储。\n- 5.6.2版本：增强技能，现在魔力值高于60%时，提高40%伤害。\n- 5.5.3版本：增强技能，属性克制伤害加成效果由40%变为120%。\n- 5.5.0版本：增强技能，属性克制效果翻倍，即伤害加成由20%变为40%。"}, {"name": "冰柱连击", "url": "https://www.mcmod.cn/item/442609.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442609.png?v=11", "category": "大法师:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：60%*20段/秒*20秒\n- 索敌半径：50米\n- 自拐能力-冰柱连击：持续期间可以释放冰柱连击 * 20秒\n- 魔力消耗：600点\n- 冷却时间：80秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加3%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n利用冰河的力量召唤寒冰风暴，瞄准目标并对其降下无数冰柱，对目标造成60%魔法攻击寒冰属性冻伤伤害，持续20秒，冰柱连击持续时间内将替换法杖的攻击模式，持续使用法杖可连环施展。\n冰柱连击攻击速度最大为每秒20次，处于沉默状态下时，冰柱连击不会落下冰锥，只能发射法杖原先的魔法球。\n拥有无限魔力效果时，冰柱连击会改为召唤巨大冰柱，冰柱连击总技能倍率提升0.1倍，材质缩放增大30%。\n职业专属\n学习3转被动大师魔导后，冰柱连击总技能倍率提升0.5倍，与无限魔力的提升0.1倍加算，总计提升0.6倍。\n历史改动：\n- 7.3.5版本：增强技能，技能倍率由55%提高至60%，每级伤害倍率由2.75%提升至3%，无限魔力效果存在时，冰柱连击的伤害倍率提高0.1倍。\n- 7.2.8版本：增强技能，攻击频率由18次/秒提升至20次/秒。\n- 7.1.6版本：削弱技能，攻击频率由20次/秒降低至18次/秒，伤害倍率由50%提升至55%，每级伤害倍率由2.5%提升至2.75%。\n- 7.0.8版本：增强技能，持续时间由18秒延长至20秒。\n- 7.0.7版本：增强技能，持续时间由15秒延长至18秒。\n- 7.0.6版本：增强技能，持续时间由10秒延长至15秒。\n- 7.0.0版本：重制技能，魔力消耗由800降低至600，伤害系数由300%降低至50%，升级效果由延长1秒冰柱连击持续时间改为增加2.5%伤害系数，持续时间由20秒缩短至10秒。\n- 6.1.7版本：削弱技能，伤害系数由350%降低为300%，且现在处于沉默状态下冰柱连击将无法使用。\n- 5.6.7版本：增强技能，冰柱连击攻击速度提高为原来的2倍（最大攻击速度由每秒10次提高为每秒20次）。\n- 5.5.3版本：增强技能，冰柱连击伤害系数由250%变为350%。"}, {"name": "元素爆裂", "url": "https://www.mcmod.cn/item/442610.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442610.png?v=6", "category": "大法师:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：100%*3抛射物\n- 段数补正：5段\n- AOE半径：7米\n- 魔力消耗：800点\n- 冷却时间：10秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n张开魔力弹幕，发射扇形三个元素魔法球袭击目标，命中目标后依序使用火焰、源水、寒冰、黑暗与自然元素造成半径7米的100%魔法攻击对应属性消灭伤害。\n当存在无限魔力效果时，元素魔法球数量由3个提高至5个。\n历史改动：\n- 7.3.5版本：增强技能，无限魔力效果存在时，元素魔法球数量增加2个。\n- 7.0.0版本：重制技能，魔力消耗由900降低至800，伤害系数由1200%降低至100%，每级伤害系数由60%降低至5%，额外增加一段自然属性攻击。\n- 5.6.7版本：增强技能，技能系数由800%提高为1200%。"}, {"name": "无尽魔力", "url": "https://www.mcmod.cn/item/442611.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442611.png?v=13", "category": "大法师:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 辅助能力-无限魔力：10%职业增幅+100%魔力消耗减免 * 60秒\n- 辅助半径：32米\n- 魔力消耗：800点\n- 冷却时间：120秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加6秒无限魔力持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n集中精神冥想，以引发出体内魔法的真正力量，给予自身与距离自身32米范围内所有玩家60秒无限魔力效果：职业增幅+10%，并且施放技能时不消耗魔力。\n当拥有无限魔力效果时，冰柱连击会改为召唤巨大冰柱，冰柱连击总技能倍率提升0.1倍，元素爆裂额外发射2道魔法球弹幕，魔法箭数量增加4，爆裂弹额外增加一波。\n历史改动：\n- 7.3.5版本：修改技能，冷却技能由90秒提高至120秒，现在无限魔力效果会增强其他技能。\n- 7.0.0版本：重制技能，魔力消耗由100提高至800，持续时间由20秒延长至60秒，每级持续时间由2秒延长至6秒，冷却时间由120秒缩短至90秒，移除造成的伤害、穿透值、最大伤害提升增益，现在可以提高10%职业增幅，并且效果可以给予范围玩家。\n- 6.3.0版本：增强技能，现在还会使最大伤害上限提高至原来的2倍。\n- 5.6.7版本：增强技能，伤害增加量由100%提高为150%。\n- 5.5.0版本：增强技能，持有效果时额外提高100%造成的伤害、并提升12点穿透值。"}, {"name": "万雷殒落", "url": "https://www.mcmod.cn/item/442612.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442612.png?v=8", "category": "大法师:二转技能:超级技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：425%*10道/秒*30秒\n- 段数补正：1.4段闪电（期望）\n- 索敌半径：16米\n- AOE半径：3米\n- 易伤能力-禁断雷电：20%*60秒\n- 魔力消耗：1500点\n- 冷却时间：600秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加21.25%技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n咏唱万雷之咒，当咒语结束之时，天打雷劈，万雷殒落，发射雷电魔法球，碰撞后呼唤雷电魔法，在上方召唤巨大的雷电魔法阵，在持续时间内以每秒10次的速度召唤落雷，对法阵内的随机单体敌人造成半径3米的425%魔法攻击闪电属性雷霆伤害，并对该单体目标施加30秒的禁断雷电效果：受到的伤害增加+20%。每道落雷有约40%概率攻击2次。\n历史改动：\n- 7.0.0版本：重制技能，魔力消耗由3000降低至1500，伤害系数由3200%降低至425%，升级效果由缩短20秒CD改为提高21.25%伤害系数，闪电生成间隔由4tick缩短至2tick。\n- 5.6.7版本：增强技能，技能伤害系数由2800%提高为3200%，并会向目标施加禁断雷电效果。\n- 5.6.2版本：增强技能，技能伤害系数由2000%提高为2800%，并提高攻击速度。\n- 5.5.3版本：增强技能，现在技能的持续时间加倍。"}], "三转技能": [{"name": "大师魔导", "url": "https://www.mcmod.cn/item/946886.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946886.png?v=1", "category": "大法师:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高2000点最大魔力值，提高20%最终伤害。\n特殊能力\n魔力存储BUFF达到5层时，冰柱连击总技能倍率提升0.5倍，与无限魔力的提升0.1倍加算，总计提升0.6倍。\n魔力存储BUFF达到5层时，消灭光束每次的伤害段数都将增加1段。\n学习技能后，寒冰咒的技能倍率提升至原先的3倍。"}, {"name": "消灭光束", "url": "https://www.mcmod.cn/item/946889.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946889.png?v=2", "category": "大法师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：550%*20次/秒*20秒\n- 段数补正：2段+1段（魔力存储5时触发）\n- 真实魔法伤害：30点*20次/秒*20秒*（2段+1段）\n- 自拐能力-消灭光束：持续期间可以释放消灭光束 * 20秒\n- 魔力消耗：2000点\n- 冷却时间：180秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加27.5%技能倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n凝聚高度压缩的纯粹魔力，向前方持续释放毁灭性的魔法光束，给予自身消灭光束效果，持续内将替换法杖的普通攻击模式，持续使用法杖可以释放消灭光束：对目标每秒造成20次，每次2段的550%魔法攻击魔法属性激光伤害，至多持续20秒。\n学习3转被动大师魔导后当魔力存储达到5层时，消灭光束每次攻击都会额外增加1段伤害，消灭光束持续期间无法启用冰柱连击，若通过特殊方式获得了冰柱连击，则冰柱连击被消灭光束覆盖，直到消灭光束结束。\n消灭光束不受到沉默的限制。"}, {"name": "炼狱火雨", "url": "https://www.mcmod.cn/item/946890.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946890.png?v=2", "category": "大法师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：300%*49抛射物\n- AOE半径：4米\n- 魔力消耗：1500点\n- 冷却时间：20秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加15%技能倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n在准星处召唤强大的炎之魔咒，在6*6的矩形范围内召唤49颗炼狱火球轰炸范围目标，每颗火球落地时产生爆炸，对半径4米球形范围内目标造成300%魔法攻击火焰属性烧伤伤害。"}, {"name": "霹雳电球", "url": "https://www.mcmod.cn/item/946892.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946892.png?v=2", "category": "大法师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：150%\n- 辅助能力-电盾：10%终伤+10%职业增幅+120防御力 * 80秒\n- 辅助半径：32米\n- 魔力消耗：1500点\n- 冷却时间：240秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加7.5%技能倍率，1秒电盾持续时间，1秒雷电法球持续时间，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n技能效果\n激发雷电魔法，给予距离自身32米范围内所有玩家持续80秒的电盾效果：提高10%最终伤害、10%职业增幅、120点防御力。\n额外效果\n额外召唤一颗雷电法球在自身周围环绕，雷电法球撞击到目标时每tick会造成150%魔法攻击闪电属性电波伤害，雷电法球至多持续80秒。"}, {"name": "冰河地狱", "url": "https://www.mcmod.cn/item/946893.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946893.png?v=2", "category": "大法师:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 暴风雪倍率：950%*500抛射物\n- 暴风雪索敌半径：16米\n- 范围冰冻倍率：950%*25段\n- 范围冰冻半径：16米\n- 龙卷风倍率：950%*20次/秒*25秒\n- 龙卷风伤害半径：2.5米\n- 龙卷风吸引半径：16米\n- 龙卷风数量：3\n- 冰柱负面半径：3米\n- 冰柱负面能力：缓慢II * 5秒\n- 冰柱数量：31个\n- 魔力消耗：2000点\n- 冷却时间：900秒\n- 持法杖时按下设定的技能按键发动\n- 每升1级增加47.5%暴风雪、龙卷风、范围冰冻技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n技能效果\n引导极寒的终极魔法，持续期间内对距离冰河地狱中心16米范围内的敌人发射至多500颗追踪寒冰魔法球，对随机单体目标造成950%魔法攻击寒冰属性冻伤伤害，同时每秒对索敌范围内的所有敌人额外造成一次等同于寒冰魔法球的伤害。冰河地狱持续25秒。\n额外效果\n冰河地狱范围内还会生成3个龙卷风，龙卷风各自持续吸引16米范围内的敌人，并对距离龙卷风2.5米以内的敌人每秒造成20次等同于寒冰魔法球的伤害。\n冰河地狱范围内每0.8秒会在随机位置生成1个巨大冰柱，每个巨大冰柱出现时对周围3米范围内的敌人施加持续5秒的缓慢II。\n注：由于龙卷风伤害半径较小且会相互吸引，因此实战中龙卷风的伤害次数往往会远低于预期，打稻草人等不会被牵引的固定靶时，控制稻草人处于龙卷风的巡逻路径上的伤害比稻草人放在冰河地狱正中心更高。\n历史改动：\n- 8.0.0-RC3版本：现在生成的巨大冰柱会对周围的敌人施加5秒的缓慢II。"}]}}, {"name": "驯兽师", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "无", "生存": "很强", "刷本效率": "高", "缺蓝": "不缺", "对单": "偏弱", "特殊1": "嘲讽，有大输出高", "特殊2": "团战容易挡队友"}, "tiers": {"固有技能": [{"name": "灵魂灯笼", "url": "https://www.mcmod.cn/item/643393.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643393.png?v=3", "category": "驯兽师:固有技能", "description": "固有技能。\n消耗200魔力，打开召唤灵魂的灯笼，使自身周围的伙伴回到天界，并医疗自身与8米内所有玩家2000点生命值。\n持指挥杖时蹲下按下武器功能键（默认V）施放。\n技能冷却时间20秒。\n每升级一次提升100点恢复的生命值量，最多升为10级。\n历史改动：\n7.0.0版本：\n重制技能，恢复量由50%最大生命值改为2000点生命值，每级恢复量由5%最大生命值改为100点生命值，现在可以范围治疗，冷却时间由10秒提高至20秒。"}, {"name": "契约召唤", "url": "https://www.mcmod.cn/item/643394.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643394.png?v=5", "category": "驯兽师:固有技能", "description": "固有技能。\n消耗800魔力、召唤石*1，召唤伙伴，重复召唤会刷新伙伴，最多一次存在一个伙伴，伙伴的生命值为玩家最大生命值的4000%+10000点。\n持指挥杖时按下武器功能键（默认V）施放。\n技能冷却时间90秒。\n每升一级提高100%契约雪狼基础生命值倍率，最多升为10级。\n历史改动：\n7.0.7版本：\n削弱技能，降低契约雪狼生命值基础倍率，技能CD由60秒延长至90秒。\n7.0.0版本：\n重制技能，魔力消耗由1000降低至800，移除技能升级效果。\n6.2.8版本：\n削弱技能，冷却时间由30秒提高至60秒。"}], "一转技能": [{"name": "毒针连击", "url": "https://www.mcmod.cn/item/643395.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643395.png?v=3", "category": "驯兽师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗200魔力，呼唤猛烈的风之魔法，向前方发射5波不同色彩的毒针攻击目标，对远距离目标造成75%魔法攻击暴风属性毒药伤害，毒针命中目标后，将给予自身与32米内玩家持续60秒的毒性标记效果，提高10%职业增幅。若学习了技能齐心协力，命中目标后还会给予目标10秒的持续伤害，每秒造成18.75%魔法攻击自然元素毒药伤害。\n每升一级增加3.75%毒针连击攻击伤害，0.94%DOT伤害。\n技能冷却时间20秒。\n历史改动：\n7.0.0版本：\n重制技能，魔力消耗由400降低至200，基础伤害倍率由300%降低至75%，每级伤害倍率由10%降低至3.75%，现在命中敌人还会给予dot伤害与毒性标记效果。"}, {"name": "红旗指导", "url": "https://www.mcmod.cn/item/643396.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643396.png?v=5", "category": "驯兽师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗 200 魔力，呼唤技能，挥舞红色旗帜，指挥伙伴发动技能，同时补充自身1200点生命值。\n技能冷却时间24秒。\n每升一级增加60点补充的生命值、一级对应的呼唤技能等级。\n历史改动：\n7.0.8版本：\n削弱技能，技能冷却时间由20秒延长至24秒。\n7.0.0版本：\n重制技能，魔力消耗由400点降低至200点，恢复量由50%最大生命值改为1200点生命值，升级效果由减少1秒冷却时间改为增加60点补充的生命值。"}, {"name": "蓝旗指导", "url": "https://www.mcmod.cn/item/643397.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643397.png?v=4", "category": "驯兽师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗 200 魔力，呼唤技能，挥舞蓝色旗帜，指挥伙伴发动技能，同时补充自身800点魔力值。\n技能冷却时间24秒。\n每升一级增加一级对应的呼唤技能等级。\n历史改动：\n7.0.8版本：\n削弱技能， 技能冷却时间由20秒延长至24秒。\n7.0.0版本：\n重制技能，魔力消耗由400降低至200，补充的魔力值由50%改为800点，移除升级技能减少1秒冷却时间的效果。"}, {"name": "动物专精", "url": "https://www.mcmod.cn/item/643398.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643398.png?v=3", "category": "驯兽师:一转技能:被动技能", "description": "一转技能。\n最低学习等级5等。\n透过仔细研究伙伴的特性，领悟出训兽师的真正力量，提高10%最终伤害，提高最大魔力值1000点，获得抵抗击退效果，使用合适的食物喂食伙伴时，可给予驯兽师自身狼之谢礼效果，提高50%造成的伤害，所有伙伴的呼唤技能等级提升两等，更好的食物将持续更长的时间。\n注：\n- 合适的食物为：狼喜欢的肉类、魔法金属的任意生肉、生鱼、凤梨、黄金凤梨、牛奶冰棍、草莓冰棍、蓝莓冰棍、奶油冰棍、巧克力冰棍。\n- 狼之谢礼持续时间为食物提供的饥饿值*9+饱和系数*30（饱和系数=饱和度/饥饿值/2）。学习专精伙伴照护后持续时间加备。由于每次给予玩家4秒效果时长，因此实际时长比公式长3秒。\n历史改动：\n- 7.3.7版本：增强技能，现在还会使玩家免疫击退。\n- 7.0.0版本：重制技能，现在可以喂食伙伴。\n- 6.4.4及以前：增加魔法攻击力与暴击值。并强化契约召唤，可召唤更强大的伙伴，增加伙伴的伤害与生命值。"}], "二转技能": [{"name": "齐心协力", "url": "https://www.mcmod.cn/item/643399.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643399.png?v=7", "category": "驯兽师:二转技能:被动技能", "description": "与伙伴建立更强的羁绊，两者同心，其利断金，强化毒针连击，命中后可给予目标毒药的持续伤害效果。\n驯兽师获得职业资源同调值，同调值每3秒恢复1点，最多可获得100点。驯兽师可右键点击骑乘伙伴，并每秒消耗1点同调值，处于骑乘状态时若至少拥有1点同调，将医疗训兽师本身210点生命值并获得3秒的齐心协力效果，同时伙伴仍可继续攻击，并依照玩家的意识移动。\n玩家拥有同调值且处于骑乘状态承受伤害的话，玩家的伤害减免提高50%，该伤害的50%由伙伴代为承受。替代承受伤害最多使契约雪狼损失9999点生命值。\n学习专精同步心灵后，乘骑时若拥有同调值，玩家的伤害减免提高15%，伙伴替代承受的伤害提高15%。\n历史改动：\n- 7.3.7版本：增强技能，当玩家拥有该效果并骑乘且伙伴处于温饱状态时，会获得额外的10%最终伤害与10%职业增幅。\n- 7.0.7版本：削弱技能，每秒恢复生命值由420点降低至210点。\n- 7.0.0版本：重制技能，每秒恢复生命由5%最大生命调整为420点生命值，现在乘骑状态伙伴会分担50%伤害，乘骑时免疫重力伤害的出血效果。"}, {"name": "猎鹰冲击", "url": "https://www.mcmod.cn/item/643400.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643400.png?v=3", "category": "驯兽师:二转技能:主动技能", "description": "消耗 600 魔力，以惊人的驯兽知识召唤3只猎鹰，向前方冲撞并攻击目标，对目标地点造成半径3米的范围 125% 魔法攻击自然属性动物伤害，猎鹰直接命中目标后将额外造成一次伤害并给予目标慢性毒效果，使其受到的伤害提高30%，持续90秒。\n技能冷却时间15秒。\n每升一级增加6.25%伤害，最多升为10级。\n历史改动：\n7.0.0版本：\n重制技能，魔力消耗由500提高至600，伤害倍率由900%降低至125%，每级伤害倍率由30%降低至6.25%，冷却时间由10秒增加至15秒，移除视当前魔力值额外增伤的效果。"}, {"name": "野性领导", "url": "https://www.mcmod.cn/item/643401.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643401.png?v=4", "category": "驯兽师:二转技能:主动技能", "description": "消耗 500 魔力，呼唤技能，领导伙伴使其发动伙伴技能，同时给予自身与16米内的玩家60秒野性领导BUFF，持续时间内职业增幅+10%。\n技能冷却时间24秒。\n每升一级增加一级对应的呼唤技能等级。\n历史改动：\n7.0.8版本：\n削弱技能，技能冷却时间由20秒延长至24秒。\n7.0.0版本：\n重制技能，现在野性领导可以给予范围内玩家，效果由+30防御力改为+10%职业增幅，移除升级减少冷却时间的效果。"}, {"name": "野性呐喊", "url": "https://www.mcmod.cn/item/643402.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643402.png?v=3", "category": "驯兽师:二转技能:主动技能", "description": "消耗 500 魔力，呼唤技能，领导伙伴使其发动伙伴技能，同时给予自身与16米内的玩家60秒野性呐喊BUFF，持续时间内造成的伤害+50%。\n技能冷却时间24秒。\n每升一级增加一级对应的呼唤技能等级。\n历史改动：\n7.0.8版本：\n削弱技能，技能冷却时间由20秒延长至24秒。\n7.0.0版本：\n重制技能，现在野性呐喊可以给予范围内玩家，效果由+40%造成的伤害提高至+50%，移除升级减少冷却时间的效果。"}, {"name": "兽魔无极", "url": "https://www.mcmod.cn/item/643403.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643403.png?v=4", "category": "驯兽师:二转技能:超级技能", "description": "消耗 1500 魔力发动兽魔无极，所选的伙伴会进化，并且持续时间内大幅提升攻击力。期间内伙伴将进入无敌状态，乘骑时同调值不会低于1点，乘骑状态受伤时，受到的伤害减少75%。\n兽魔无极持续3分钟。\n技能冷却时间600秒。\n每升级一次增加27.5%兽魔无极状态下伙伴的额外能力伤害，最多升为10级。\n历史改动：\n- 7.3.7版本：基础伤害倍率由500%提高至550%，每级伤害倍率由25%提高至27.5%。\n- 7.0.0版本：重制技能，升级效果由减少20秒冷却改为增加25%每级伤害倍率，现在乘骑时会减少75%受到的伤害。"}], "三转技能": [{"name": "大师驯兽", "url": "https://www.mcmod.cn/item/948684.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948684.png", "category": "驯兽师:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高2000点最大魔力值，提高20%最终伤害。\n特殊能力\n释放红旗指导、蓝旗指导时，对应的呼唤技能等级提升5级，释放野性领导、野性呐喊时，对应的呼唤技能等级提升3级。"}, {"name": "幻彩灵蝶", "url": "https://www.mcmod.cn/item/948685.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948685.png", "category": "驯兽师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：450%*32~37抛射物\n- 真实魔法伤害：50点*32~37抛射物\n- 魔力消耗：800点\n- 冷却时间：35秒\n- 持指挥杖时按下设定的技能按键发动\n- 每升1级增加22.5%技能倍率\n技能描述\n技能效果\n从森林中召唤美丽的七彩蝴蝶，召唤12波幻彩灵蝶向前方飞舞并追踪附近的目标，对命中的目标造成450%魔法攻击魔法属性神兽伤害。\n每波召唤1只幻彩灵蝶，剩余波数不足7波时，每波数量提升至3只，剩余波数不足5波时，每波数量提升至5只，共计可召唤32只幻彩灵蝶。\n额外效果\n乘骑伙伴时释放幻彩灵蝶，会使该次技能波数增加5波，但只有固定最后几波会增加数量，因此增加的波数每波只有1只幻彩灵蝶。"}, {"name": "战斗指令", "url": "https://www.mcmod.cn/item/948687.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948687.png?v=2", "category": "驯兽师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 辅助能力-战斗指令：10%职业增幅 *20秒\n- 辅助半径：未知\n- 魔力消耗：600点\n- 冷却时间：60秒\n- 持指挥杖时按下设定的技能按键发动\n- 每升1级增加1级对应的呼唤技能等级\n技能描述\n挥舞战旗，给伙伴下达战斗指令，指挥伙伴发动对应的呼唤技能，同时给予自身与附近玩家战斗指令：提高10%职业增幅。\n战斗指令控制着伙伴技能设定中三转呼唤技能里靠左的技能。"}, {"name": "征服指令", "url": "https://www.mcmod.cn/item/948689.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948689.png?v=2", "category": "驯兽师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 辅助能力-征服指令：50%造伤 *20秒\n- 辅助半径：未知\n- 魔力消耗：600点\n- 冷却时间：60秒\n- 持指挥杖时按下设定的技能按键发动\n- 每升1级增加1级对应的呼唤技能等级\n技能描述\n挥舞战旗，给伙伴下达征服指令，指挥伙伴发动对应的呼唤技能，同时给予自身与附近玩家征服指令：提高50%造成的伤害。\n征服指令控制着伙伴技能设定中三转呼唤技能里靠右的技能。"}, {"name": "神兽幻境", "url": "https://www.mcmod.cn/item/948765.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948765.png", "category": "驯兽师:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 阿尔西斯技能倍率：650%*471~561段\n- 弗瑞司迪技能倍率：650%*321段（期望）\n- 芙木瑞尔技能倍率：650%*312段\n- 樱雪霜华技能倍率：650%*240段\n- 累计技能倍率：650%*1344~1434段\n- 范围治疗：2000点*90次\n- 治疗半径：16米\n- 魔力消耗：2200点\n- 冷却时间：900秒\n- 持指挥杖时按下设定的技能按键发动\n- 每升1级增加32.5%技能倍率，100点范围治疗量\n技能描述\n咏唱七彩魔咒，打开通往幻境的传送门，召唤神兽与三春柳在自身附近，协助玩家战斗，神兽与三春柳会存在90秒，所有神兽的技能倍率均为650%。\n- 阿尔西斯根据距离每0.5~1秒发射一颗寒冰魔法球，每8秒连射13颗寒冰魔法球，每12.5秒召唤34根冰锥。\n- 弗瑞司迪每3秒召唤雷霆造成10段伤害，每6秒召唤落雷对半径3米范围内的目标造成约1.4段伤害。\n- 芙木瑞尔每7.5秒召唤一道能量光束对目标造成26段伤害。\n- 樱雪霜华每3秒召唤一道火焰龙卷风，对半径2米范围内的目标造成8段伤害。\n- 三春柳会漂浮在原地，每秒治疗半径16米范围内所有玩家2000点生命值。"}]}}, {"name": "召唤师", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "较大", "生存": "很强", "刷本效率": "高", "缺蓝": "不缺", "对单": "较高", "特殊1": "需要手动控制", "特殊2": "有大输出高"}, "tiers": {"固有技能": [{"name": "魔界召回", "url": "https://www.mcmod.cn/item/440078.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440078.png?v=2", "category": "召唤师:固有技能", "description": "基础信息\n- 固有技能\n- 自拐能力：速度II+生命恢复II * 20秒\n- 魔力消耗：100点\n- 持镰刀潜行状态下按下武器功能键（默认V键）发动\n- 每升1级增加2秒速度与生命恢复持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n咏唱魔法咒语，给予召唤师自身20秒的速度II与生命恢复II，同时呼唤附近所有的召唤物回到自己身边，并且重置附近所有的召唤物的攻击目标。\n历史改动：\n- 7.0.0版本：现在召回还可以给予自身速度与生命恢复效果，升级效果由减少魔力消耗改为延长效果持续时间。"}, {"name": "魔界召唤", "url": "https://www.mcmod.cn/item/440079.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440079.png?v=5", "category": "召唤师:固有技能", "description": "基础信息\n- 固有技能\n- 自拐能力：召唤 * 200分钟\n- 魔力消耗：200点+召唤石*1\n- 冷却时间：10秒\n- 持镰刀时按下武器功能键（默认V键）发动\n- 每升1级增加10分钟召唤兽存在时间，1级召唤兽等级，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n咏唱魔法咒语，打开通往魔界的传送门，召唤属于自身的召唤物来到身旁，并持续200分钟，若在召唤物尚未消失时使用魔界召唤，旧的召唤物将会消失。\n职业专属\n学习3转被动天界召唤后，释放魔界召唤还会额外召唤天界飞蛇。\n历史改动：\n- 7.0.0版本：重制技能，魔力消耗由500降低至200，升级效果由增加召唤兽攻击力与生命值改为增加召唤兽存在时间与召唤兽等级，冷却时间由0秒延长至10秒。"}], "一转技能": [{"name": "还魂术", "url": "https://www.mcmod.cn/item/440076.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440076.png?v=3", "category": "召唤师:一转技能:主动技能", "description": "基础信息\n- 技能倍率：400% * 召唤物数量\n- AOE半径：6米\n- 自我治疗：3000点+30%最大魔力 * 召唤物数量\n- 魔力消耗：100点\n- 冷却时间：10秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加20%技能倍率，150点自我治疗量，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n咏唱回归魔法，释放召唤物的灵魂，消除半径16米范围内自己所有的魔界召唤召唤物，每个召唤物医疗自己3000点生命值并补充30%的魔力值。清除召唤物时，每个召唤物都会引发魔力爆裂，对半径6米内的所有目标造成400%魔法攻击魔法属性神秘伤害。\n职业专属\n学习2转被动心灵水滴后，受还魂术影响的召唤物也能触发心灵水滴的叠层。\n学习3转被动天界召唤后，还魂术也能对天界飞蛇生效。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.2.8版本：增强技能，冷却时间由12秒下调至10秒，魔力消耗由300减少到100，基础治疗量由2500提高至3000，每等级额外提供的治疗量由125增加至150，魔力值恢复由20%提高至30%。新增效果：召唤物消失时将会引发魔力爆裂，攻击范围内所有目标。\n- 7.0.0版本：恢复的生命值由20%最大生命值改为2500点生命值，移除着魔的额外恢复量，升级效果由2%恢复量改为125点治疗量。"}, {"name": "着魔", "url": "https://www.mcmod.cn/item/440077.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440077.png?v=5", "category": "召唤师:一转技能:主动技能", "description": "基础信息\n- 辅助能力-着魔：50%造伤+10%职业增幅+5穿透 * 60秒\n- 辅助半径：32米\n- 自拐能力：恢复魔力至满\n- 魔力消耗：600点\n- 冷却时间：20秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加6秒着魔持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n将来自魔界的神秘魔法注入于自身，以激发召唤物的真正力量，补充自己所有的魔力值，并给予自身与半径32米范围内玩家60秒着魔效果：造成的伤害+50%，职业增幅+10%，穿透值+5。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.2.8版本：着魔新增效果：提升5点穿透值。\n- 7.0.0版本：重制技能，魔力消耗由100增加至600，持续时间由30秒延长至60秒，升级效果由减少2秒着魔技能冷却时间改为增加6秒着魔BUFF持续时间。\n- 5.5.3版本：调整技能，CD时间从60秒改为90秒，召唤物存在着魔效果时，伤害上升从20%增强为200%。"}, {"name": "幻影悦灵", "url": "https://www.mcmod.cn/item/749981.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/749981.png?v=2", "category": "召唤师:一转技能:主动技能", "description": "基础信息\n- 技能倍率：140%*5抛射物\n- 段数补正：1直接命中+1爆炸\n- AOE半径：4米\n- 易伤能力-破魔：20%*60秒\n- 魔力消耗：200点\n- 冷却时间：10秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加7%技能倍率，2秒破魔持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n召唤5个幻影悦灵，幻影悦灵会持续向前飞行并不断追踪周围的目标，每个幻影悦灵命中目标后会造成140%魔法攻击魔法属性神秘伤害，同时对目标施加60秒的破魔效果：受到的伤害增加+20%。并额外造成1段半径4米，等同于直接命中伤害的爆炸伤害。若幻影悦灵在12.5秒内没有搜寻到目标，则会自爆。\n爆炸伤害对非BOSS目标造成伤害时技能倍率提高至原先的1.3倍，该效果对直接命中伤害无效。\n专精能力\n当学习专精利刃悦灵后，幻影悦灵的爆炸半径缩短至2米，直接命中与爆炸伤害技能倍率提高至原先的1.3倍，该效果与非BOSS目标爆炸伤害增加乘算。\n当学习专精悦灵再生后 ，召唤的幻影悦灵数量提升2只。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.2.8版本：增强技能，新增效果：对非魔王目标造成额外30%的伤害，学习悦灵再生专精后，召唤的幻影悦灵数量提升2只。"}, {"name": "生命圣火", "url": "https://www.mcmod.cn/item/440068.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440068.png?v=7", "category": "召唤师:一转技能:被动技能", "description": "属性提升\n提高50%造成的伤害，提高10%最终伤害，提高1000点最大魔力值。\n获得击退抵抗。\n特殊能力\n普通攻击命中目标可以医疗自身105点生命值，并对目标施加10段持续伤害：每秒造成50%魔法攻击火焰属性烧伤持续伤害，持续10次。魔界召唤的6种召唤物每存在2秒提升自身2%全攻击方式的攻击力倍率，与召唤物攻击力倍率乘算，最多叠加60层。\n专精能力\n当学习专精火魂扩散后，普通攻击施加的DOT伤害倍率降低至35%，普通攻击可以对被命中的敌人周围6米内的敌人施加与普通攻击相同的持续伤害。\n历史改动：\n- 8.0.0版本：现在学习技能没有等级限制。\n- 7.3.7版本：增强技能，使玩家免疫击退，基础召唤物每2秒可以提升2%攻击力倍率，最多叠加60层。\n- 7.0.0版本：重制技能，移除召唤物与魔法攻击力增益，现在可以提高50%造成的伤害，10%最终伤害，1000点最大生命值，现在命中敌人可以治疗自身并施加DOT伤害。"}], "二转技能": [{"name": "心灵水滴", "url": "https://www.mcmod.cn/item/443087.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443087.png?v=9", "category": "召唤师:二转技能:被动技能", "description": "属性提升\n职业等级70级解锁2转后开放学习。\n提高100%造成的伤害，提高10%最终伤害。\n特殊能力\n魔界召唤、圣兽守护与誓约之龙的召唤物攻击力倍率提升0.4倍、召唤物生命值提升2.5倍，当受到致死伤害时，将由半径16米内随机一只自己魔界召唤的召唤物顶替该次伤害，受到顶替的召唤物会消失。当召唤物风蛇、影狼、灵猫、冰龙、火狐、或魔蝎死亡时，召唤师自身将获得一层心灵水滴效果，最多叠加至5层。尝试获取心灵水滴层数时若至少拥有5层，恢复召唤师自身与半径16米范围内玩家2,147,483,647点生命值。\n顶替死亡效果冷却时间600秒。\n专精能力\n学习专精悦灵再生后，召唤师每获得一层心灵水滴，将会在前方召唤2只幻影悦灵技能中的悦灵，该悦灵伤害视幻影悦灵技能等级，也可以受到专精利刃悦灵影响。\n历史改动：\n- 7.3.4版本：增强技能，召唤物攻击力提升由20%提升至40%，召唤物生命值提升由100%提升至250%。\n- 7.2.8版本：增强技能，现在召唤物攻击力倍率提升效果还可以作用于火凤凰与誓约之龙，治疗量由10000提高至int最大值。\n- 7.2.4版本：增强技能，治疗量由3000提高至10000，现在还可以使召唤物攻击力倍率提升0.2倍，还魂术现在也能触发心灵水滴。\n- 7.0.0版本：重制技能，替死CD由60秒延长至600秒，移除周围召唤物提高自身伤害效果，现在学习技能后可以提高100%造成的伤害与10%最终伤害，召唤物死亡后可以提供心灵水滴效果。\n- 5.5.3版本：增强技能，现在攻击时，身边8格内的召唤兽每个都将提高自己的伤害，每个召唤兽提高 100% 伤害。"}, {"name": "圣兽守护", "url": "https://www.mcmod.cn/item/443089.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443089.png?v=15", "category": "召唤师:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：115%\n- 辅助能力-火之祈祷：50%造伤+10%职业增幅 * 90秒\n- 辅助半径：32米\n- 范围治疗：400点\n- 治疗半径：4米\n- 魔力消耗：600点\n- 冷却时间：60秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加5.75%技能倍率，20点范围治疗量，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n咏唱魔法咒语，以神圣的力量，召唤圣兽火凤凰前来协助，火凤凰将协助召唤师攻击，每次造成115%魔法攻击火焰属性烧伤伤害，并同时降下治疗光环，每秒医疗距离火凤凰4米以内的玩家400点生命值，持续90秒。施展圣兽守护技能时将给予自身与半径32米范围内所有玩家90秒的火之祈祷效果，提高50%造成的伤害，提高10%职业增幅。\n学习被动心灵水滴后，火凤凰的伤害倍率提高至原先的1.2倍，生命值提高至原先的2倍。\n专精能力\n学习专精涅槃之火后，火凤凰将不再治愈附近的玩家，而是每秒对距离火凤凰7米内的敌人造成2倍圣兽守护伤害倍率的魔法攻击火焰属性烧伤伤害。\n变更历史：\n- 7.2.8版本：修正技能，现在火凤凰也会受到心灵水滴的效果。\n- 7.0.0版本：重制技能，伤害倍率由150%降低至115%，每级伤害倍率由5%提高至5.75%，治疗量由10%最大生命值改为400点生命值，技能升级效果新增20点治疗量提升，技能冷却时间由200秒缩短至60秒。\n- 5.6.7版本：削弱技能，冷却时间由150秒提高为200秒。\n- 5.6.4版本：削弱技能，火凤凰伤害系数由300%改为150%。\n- 5.6.2版本：削弱技能，火凤凰伤害系数由800%改为300%。\n- 5.6.1版本：削弱技能，火凤凰伤害系数由1000%改为800%。\n- 5.5.3版本：增强技能，现在使用技能时能获得火之祈祷效果，将火凤凰的每秒治疗量改为以前的两倍，并提升火凤凰的攻击力。\n- 5.4.9版本：重新调整技能的伤害值"}, {"name": "魔法导弹", "url": "https://www.mcmod.cn/item/443090.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443090.png?v=7", "category": "召唤师:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：60%*25抛射物\n- 魔力消耗：800点\n- 冷却时间：20秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加3%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n呼唤剧烈的魔法风暴，召唤无数魔法球袭击目标，对远距离目标造成至多25段60%魔法攻击魔法属性回馈伤害，如果引导之矢曾经命中的目标仍然存在，魔法导弹将会追踪该目标。\n对持有破魔的目标造成伤害时，技能倍率将提升至原先的2倍。\n职业专属\n学习3转被动天界召唤后，每波魔法导弹额外增加2发，即总数量增加10发。\n历史改动：\n- 7.2.8版本:增强技能，现在对持有破魔的目标造成双倍伤害。\n- 7.0.0版本：重制技能，伤害系数由1000%降低至60%，每级伤害系数由30%降低至5%，冷却时间由12秒延长至20秒，现在魔法导弹可以追踪引导之矢命中目标。\n- 5.6.1版本：削弱技能，伤害系数由1600%变为1000%。\n- 5.5.3版本：增强技能，伤害系数由800%变为1600%。"}, {"name": "引导之矢", "url": "https://www.mcmod.cn/item/750651.html", "icon": "https://i.mcmod.cn/item/icon/128x128/75/750651.png?v=2", "category": "召唤师:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：50%\n- 易伤能力-引导：20%*60秒\n- 魔力消耗：100点\n- 冷却时间：1秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加2.5%技能倍率，2秒引导持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n展开魔法弹幕，向正前方发射注入魔法力量的箭矢，对远距离目标造成一次50%魔法攻击光明属性穿刺伤害，引导之矢命中目标后，将指定目标为自己的召唤兽的攻击目标，并且指定魔法导弹与九狱蝙蝠的追踪目标，同时对目标施加20秒的引导效果：受到的伤害增加+20%。\n历史改动：\n- 7.2.8版本：增强技能，冷却时间由2秒缩短至1秒，魔力消耗由600减少至100。"}, {"name": "誓约之龙", "url": "https://www.mcmod.cn/item/443091.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443091.png?v=16", "category": "召唤师:二转技能:超级技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：225%\n- 负面效果：回复封锁 * 122秒\n- 负面半径：20米\n- 自拐能力-龙之祈祷：100%造伤+30%受到的伤害减免 * 120秒\n- 魔力消耗：1500点\n- 冷却时间：600秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加11.25%技能倍率，2秒龙之祈祷持续时间，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n咏唱高阶咒语，打开通往异界的大门，召唤誓约之龙前来协助，誓约之龙免疫一切伤害，并以225%的倍率造成魔法攻击黑暗属性黑魔法伤害，持续120秒。释放誓约之龙技能时将给予召唤师自身120秒的龙之祈祷效果：造成的伤害+100%，受到的伤害减免+30%。\n学习2转被动心灵水滴后，誓约之龙的伤害倍率提高至原先的1.2倍，生命值提高至2倍。\n誓约之龙出场10秒后会对球形半径20米范围内怪物施加12秒的回复封锁，后续每10秒对范围内目标再次施加一次。\n誓约之龙每隔5秒会在2.5秒内快速进行共25次攻击，该特殊攻击每7.5秒循环一次。\n历史改动：\n- 7.2.8版本：修正技能，现在誓约之龙也会受到心灵水滴的效果。\n- 7.2.4版本：增强技能，新增回复封锁效果。\n- 7.0.0版本：重制技能，魔力消耗由1000增加至1500，伤害倍率由200%提高至225%，升级效果由减少20秒CD改为增加11.25%倍率，现在只能召唤一只誓约之龙。\n- 6.1.7版本：增强技能，现在誓约之龙每次召唤两只。\n- 5.6.4版本：削弱技能，誓约之龙伤害系数由600%改为200%。\n- 5.6.2版本：削弱技能，誓约之龙伤害系数由3000%改为600%。\n- 5.6.1版本：削弱技能，誓约之龙伤害系数由3500%改为3000%。\n- 5.5.3版本：增强技能，现在使用技能时能获得龙之祈祷效果，提高誓约之龙的攻击速度，并增加誓约之龙的攻击力。\n- 5.4.9版本：修正召唤物攻击倍率异常，并重新调整伤害系数。"}], "三转技能": [{"name": "天界召唤", "url": "https://www.mcmod.cn/item/948197.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948197.png", "category": "召唤师:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高2000点最大魔力值，提高20%最终伤害。\n特殊能力\n施展魔界召唤时，额外召唤天界飞蛇，天界飞蛇将根据距离以1~3秒的间隔发射落星，对单体目标造成367.5%技能倍率的魔法攻击光明属性能量伤害，天界飞蛇存在时每秒治疗召唤者262.5点生命值，并每秒给予召唤者持续20秒的羽蛇守护：造成的伤害+30%、防御力+30。\n强化魔法导弹，每波魔法导弹都将额外发射2颗魔力球。"}, {"name": "地狱雷霆", "url": "https://www.mcmod.cn/item/948208.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948208.png?v=1", "category": "召唤师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：1200%*5次/秒*20秒\n- 真实魔法伤害：50点*5次/秒*20秒\n- 倍率增幅：每次技能倍率+10%，单次技能释放内与原技能倍率无限加算叠加，下次释放地狱雷霆时重置\n- 自拐能力-地狱雷霆：持续期间可以发射地狱雷霆 * 20秒\n- 魔力消耗：800点\n- 冷却时间：120秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加60%技能倍率\n- 冷却减免倍率：50%\n技能描述\n命中效果\n召唤强力的雷霆魔咒，向目标发射致命雷电，给予自身地狱雷霆效果，持续期间内将替换镰刀的普通攻击模式，持续使用镰刀可以释放地狱雷霆：每0.2秒对目标造成1200%魔法攻击闪电属性雷霆伤害，并额外附加30点真实魔法伤害，至多持续20秒。\n地狱雷霆最远可攻击到16米外的目标。\n地狱雷霆不受到沉默的限制。\n额外效果\n地狱雷霆成功命中目标后，会使该次技能中下一次地狱雷霆伤害的技能倍率+10%，技能倍率增加量与原技能倍率加算，可无限叠加，层数在下一次释放地狱雷霆技能时重置。"}, {"name": "九狱蝙蝠", "url": "https://www.mcmod.cn/item/948211.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948211.png?v=1", "category": "召唤师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：600%*120抛射物\n- 索敌半径：16米\n- DOT倍率：300%*20段\n- 自我治疗：400点*120抛射物\n- 魔力消耗：800点\n- 冷却时间：120秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加30%技能倍率，20点自我治疗量\n- 冷却减免倍率：50%\n技能描述\n命中效果\n呼唤凶灵魔咒，召唤无数九狱蝙蝠撕咬敌人，打开通往邪魔世界的传送门，传送门每0.5秒召唤一只九狱蝙蝠，对目标造成600%魔法攻击火焰属性动物伤害，并对目标施加20段持续伤害：每秒造成300%魔法攻击火焰属性地狱伤害，持续20次。传送门至多存在60秒，九狱蝙蝠会随机飞往附近的目标，优先攻击玩家上一个攻击过目标，若玩家使用引导之矢锁定了目标，则只会攻击引导之矢的目标。\n由于九狱蝙蝠飞行需要时间，若玩家没有使用引导之矢锁定目标，则可能会出现玩家攻击了新的目标，但已释放并锁定了旧目标的九狱蝙蝠又命中了旧的目标，导致上一个攻击过的目标又被覆盖回旧目标的情况。实战中的自由索敌可能因为更多目标和DOT持续存在变得更不可预测。\n额外效果\n每只九狱蝙蝠命中目标时，会治疗自身400点生命值。"}, {"name": "凶灵附体", "url": "https://www.mcmod.cn/item/948216.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948216.png?v=1", "category": "召唤师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 辅助能力-凶灵附体：30%造伤+10%职业增幅 * 80秒\n- 辅助半径：32米\n- 魔力消耗：800点\n- 冷却时间：300秒\n- 持镰刀时按下设定的技能按键发动\n- 该技能升级没有效果\n- 冷却减免倍率：50%\n技能描述\n命中效果\n咏唱黑暗魔咒，召唤强大的凶灵附身，给予自身与距离自身32米范围内所有玩家80秒凶灵附体效果：提升30%造成的伤害、提升10%职业增幅。同时施放魔界召唤，一次性召唤风蛇、影狼、灵猫、冰龙、火狐、魔蝎，若学习了天界召唤，还会额外召唤天界飞蛇。\n通过凶灵附体召唤的召唤兽，攻击力都会提升至原先的1.5倍，该效果为独立乘区。\n历史改动：\n- 8.0.0-RC3版本：增强技能，现在凶灵附体召唤的召唤兽攻击力是原先的1.5倍。"}, {"name": "至尊红龙", "url": "https://www.mcmod.cn/item/948218.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948218.png?v=2", "category": "召唤师:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：1200%*90秒（约820段）\n- 负面效果：回复封锁*95秒\n- 负面半径：32米\n- 易伤能力-巨龙之火：30%*120秒\n- 魔力消耗：2000点\n- 冷却时间：700秒\n- 持镰刀时按下设定的技能按键发动\n- 每升1级增加60%技能倍率\n- 冷却减免倍率：0%\n技能描述\n召唤强大的幻影巨龙，对目标降下地狱之火，幻影巨龙会撕咬小范围目标，造成1200%魔法攻击火焰属性神兽伤害，并在俯冲时对目标发射一连串火球，造成1200%魔法攻击火焰属性能量伤害，火球会对目标施加30秒的巨龙之火：受到的伤害增加+30%。幻影巨龙存在时每2.5秒对半径32米球形范围的内所有怪物施加5秒的回复封锁：抵销目标所有的生命回复效果。幻影巨龙至多持续90秒。"}]}}, {"name": "白魔导", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "小", "生存": "很强", "刷本效率": "偏低", "缺蓝": "不缺", "对单": "较高", "特殊1": "群体解沉默", "特殊2": "群体解弱、经验buff"}, "tiers": {"固有技能": [{"name": "战意", "url": "https://www.mcmod.cn/item/442573.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442573.png?v=2", "category": "白魔导:固有技能", "description": "固有技能。\n消耗200魔力，咏唱激烈的圣光咒语，激发潜在的力量，给予自身与32米范围内的玩家持续60秒的战意效果，提高50%造成的伤害，提高10%最终伤害，提高10%职业增幅，提高25%击败怪物获得的职业经验量。\n持法书时按下武器功能键（默认V键）发动。\n每升级一次增加6秒战意效果持续时间，最多升为10级。\n历史改动：\n7.0.0版本：\n重制技能，魔力消耗由250降低至200，持续时间由20秒延长至60秒，每级持续时间由4秒延长至6秒。"}, {"name": "治愈之光", "url": "https://www.mcmod.cn/item/442574.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442574.png?v=13", "category": "白魔导:固有技能", "description": "固有技能。\n消耗200魔力，透过咏唱来引导光明的正极力量，医疗自己与10米范围内所有玩家1200点生命值，并对10米范围内所有怪物造成100%魔法攻击光明属性神圣伤害，若怪物不是BOSS，则总伤害倍率额外增加1.5倍。治愈之光可同时医疗多名玩家。每医疗一名包括自身在内的玩家，缩短1秒治疗术CD，CD最多被缩减至1秒。若医疗范围内只有自身，则额外缩短50%治疗术CD，由于取整原因此时CD仅有4秒。\n学习二转被动圣光灼烧后，提升1倍治愈之光总治疗量，提升0.25倍治愈之光总伤害倍率，均为独立乘区，同时使治疗与伤害半径增加3米。\n此外，治愈之光的总治疗量还会提高 玩家等级×4%，独立乘区。\n技能冷却时间10秒。\n每升级一次增加60点治愈之光恢复的生命量，5%治愈之光的攻击伤害，最多升为10级。\n治愈之光治疗量总公式为：(1200+60×技能等级)×恢复量×(1+玩家等级×4%)，当玩家学习圣光灼烧后，总治疗量还会额外 ×2，若释放技能的武器是传说武器，还会额外提高传说武器的提升量，独立乘区。\n历史改动：\n- 7.4.2版本：技能基础伤害倍率由50%提升至100%，技能升级伤害倍率由2.5%提升至5%，治疗与伤害半径由7米增加至10米，对非BOSS伤害倍率提高1.5倍，二转被动圣光灼烧的增强额外增加0.25倍伤害倍率与3米治疗与伤害半径。\n- 7.1.6版本：现在每级玩家等级会使治愈之光总治疗量提高4%。\n- 7.1.4版本：现在二转被动圣光灼烧会使治愈之光总治疗量提高1倍。\n- 7.0.3版本：现在释放治愈之光时若医疗范围内只有自身，则额外缩短50%治疗术CD。\n- 7.0.0版本：重制技能，6.4.4及以前治疗术的计算方式为：\n- 使用技能后，将消耗所有治愈能量的层数，并获得2秒破绽效果。\n- 治疗量受到白魔导自身恢复量属性（专精中的强力恢复增加的治疗量与人体改造的药物适应也可以增加恢复量属性），治疗术技能等级，法书基础攻击力，传奇武器法书范围治疗量加成。\n- 不受到角色魔法攻击力，武器额外魔法攻击力（除了基础攻击力以外的部分，包括宝玉，质量改造，武器卷轴，星等强化，附魔）和治愈能量的加成。\n- 治疗术的回血量计算方式为：治疗术发动者自身恢复量属性×（1+治疗术等级/10）×武器基础攻击力×12（二转学习光能爆破后增加至24）×传奇武器额外治疗量增加。此外，治疗术发动者自身会受到双倍的回血效果。"}], "一转技能": [{"name": "愈疗之泉", "url": "https://www.mcmod.cn/item/440107.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440107.png?v=6", "category": "白魔导:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗800魔力与治疗粉，以强大的光之魔咒召唤愈疗之泉在身边，愈疗之泉每秒医疗5米范围内的所有玩家1200点生命值，学习二转被动圣光灼烧后，愈疗之泉每秒会对治疗范围内的玩家施加持续30秒的纯净之泉BUFF，使玩家职业增幅+5%、经验获得量+15%、额外增加10点不受限制的额外感知。只能同时拥有一个愈疗之泉。\n技能冷却时间90秒。\n每升级一次增加60点愈疗之泉的治疗量，最多升为10级。\n学习专精心灵之泉后，减少愈疗之泉的35%冷却时间与持续时间。\n学习专精奉献之泉后，愈疗之泉每次治疗可以恢复被治疗者 愈疗之泉恢复量*10% 的血性值。\n历史改动：\n- 7.3.4版本：增强技能，学习圣光灼烧后会额外给予玩家纯净之泉效果。\n- 7.1.4版本：增强技能，基础治疗量由800提高至1200，每级治疗量由40提高至60。\n- 7.0.0版本：重制技能，魔力消耗由500提高至800，治疗范围由半径11米缩小至半径5米，治疗量由20%最大生命值调整为800点生命值。"}, {"name": "神圣祈祷", "url": "https://www.mcmod.cn/item/442529.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442529.png?v=13", "category": "白魔导:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗 400 魔力，虔诚的向天空祈祷，降下神圣的光芒，医疗自己与12米范围内的所有玩家4200点生命值，并解除自己与周遭玩家的部分负面状态效果，同时对12米范围内所有怪物造成100%魔法攻击光明属性神圣伤害，施展神圣祈祷时会召唤圣光守护龙来协助战斗，只能同时拥有一个圣光守护龙。\n神圣祈祷对非BOSS目标造成的伤害倍率提高至150%。\n可以解除的负面效果有：冰缓，蛊毒，黑暗祈祷，致命熔岩，破灭祈祷，剧毒，石化，冻结，沉默（沉默状态下可以使用神圣祈祷），抽搐，至残，瘫痪，同命，失明，饥饿，凋零，中毒，挖掘疲劳。\n可以解除的创伤有：皮肉伤、扭伤、拉伤、擦伤、脑震荡。\n技能冷却时间20秒。\n每升级一次增加5%神圣祈祷对BOSS伤害，7.5%对非BOSS伤害，210点神圣祈祷治疗量，最多升为10级。\n变更历史：\n- 7.1.4版本：增强技能，现在神圣祈祷对非BOSS目标伤害倍率提升50%。\n- 7.0.0版本：重制技能，魔力消耗由300提高至400，伤害倍率由300降低至100%，不再给予圣光祝福效果。\n- 6.2.0版本：增加新效果，释放神圣祈祷时可以对周围造成300%伤害。\n- 6.1.7版本：技能由净化术更名为神圣祈祷，在释放技能时召唤守护光龙。\n- 6.1.4版本：现在净化术可以重置血性值。\n- 5.6.7版本：现在净化术可以解除瘫痪buff，并且增加了圣光祝福buff增幅的职业经验获取量。\n- 5.5.4版本：现在净化术可以解除部分创伤。"}, {"name": "圣光矢", "url": "https://www.mcmod.cn/item/442552.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442552.png?v=5", "category": "白魔导:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗 200 魔力，展开光之羽翼发射8支蕴含圣光的魔箭攻击目标，造成190%魔法攻击光明属性纯净伤害。每当圣光矢命中目标时，都能补充自身10%的最大魔力值。\n圣光矢命中非BOSS目标时，伤害倍率将会提高至285%。\n技能冷却时间10秒。\n每升级一次增加9.5%圣光矢对BOSS伤害，14.25%对非BOSS伤害，最多升为10级。\n历史改动：\n- 7.1.4版本：增强技能，对非BOSS目标的倍率提升由30%提高至50%。\n- 7.0.0版本：重制技能，伤害倍率由300%降低至190%，每级伤害倍率由10%降低至9.5%，现在命中非BOSS生物会使伤害倍率提高原倍率的30%。\n- 6.2.0版本：增强技能，伤害系数由250%提升至300%。\n- 6.1.7版本：增强技能，圣光矢的发射速度提高，现在能一共发射10支箭矢。"}, {"name": "神圣经典", "url": "https://www.mcmod.cn/item/440105.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440105.png?v=5", "category": "白魔导:一转技能:被动技能", "description": "一转技能。\n最低学习等级5等。\n阅读经典来强化自己与神光的交流。提高50%造成的伤害，提高10%最终伤害，提高最大魔力值1000点，获得抵抗击退效果，每当普通攻击时给予自身与8米范围内所有队友持续16秒的神圣经典效果，每层给予8%经验加成，神圣经典的维持层数等同于周遭包括自身在内的玩家人数，最高5层，若作用范围内只有自身，则层数提高至4层。\n学习专精福音传递后，神圣经典最大层数增加1层。\n历史改动：\n- 7.4.2版本：增强技能，现在范围内只有自身时会获得4层神圣经典效果。\n- 7.3.7版本：增强技能，现在还会使玩家免疫击退。\n- 7.0.0版本：重制技能，移除治疗量与最大生命提升，改为提高50%造成的伤害、10%最终伤害、1000最大魔力值，现在普攻会给予范围玩家神圣经典效果。"}], "二转技能": [{"name": "圣光灼烧", "url": "https://www.mcmod.cn/item/443097.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443097.png?v=8", "category": "白魔导:二转技能:被动技能", "description": "反转圣光魔法，将能量转换为致命的圣光灼烧。提高50%造成的伤害，每次普通攻击命中时，对目标施加持续10秒的持续伤害，每秒造成50%魔法攻击火焰属性神圣效果，并有50%的概率可减少圣光矢或神圣祈祷1秒的冷却时间。\n强化治愈之光的效果，增加治疗与伤害半径3米，提升0.25倍总技能伤害倍率，并且治愈之光会治疗两倍的医疗量，强化神圣经典的效果，给予神圣经典的最大层数提升1层。\n强化愈疗之泉，愈疗之泉将给予附近所有玩家纯净之泉效果，提高15%职业经验值获得量、提高5%职业增幅、提高0.05技能冷却进度。\n学习专精圣光审判后，普攻命中还会造成等同于直接命中伤害的半径2米的范围伤害。\n减少冷却时间效果优先作用于圣光矢，圣光矢冷却完毕后才会作用于神圣祈祷上。\n历史改动：\n- 7.4.2版本：增强技能，现在圣光灼烧会使治愈之光总伤害倍率提高0.25倍，治疗与伤害半径增加3米。\n- 7.1.4版本：增强技能，现在圣光灼烧会使治愈之光总治疗量提高1倍。\n- 7.0.0版本：重制技能，移除提高治疗量与爆破效果，造成的伤害提高由30%提高至50%，现在普攻命中可以附加DOT伤害，并有50%概率缩短圣光矢或神圣祈祷CD。\n- 5.6.7版本：现在光能爆破将提高白魔导使用法书时的补血量。"}, {"name": "光耀直击", "url": "https://www.mcmod.cn/item/443098.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443098.png?v=3", "category": "白魔导:二转技能:主动技能", "description": "消耗600魔力，呼唤来自天空的神圣光芒，持续对正前方降下3道制裁之光，每道制裁之光能够攻击宽度为7米的直线上的复数目标并造成75%魔法攻击光明属性神圣伤害，同时对目标施加持续30秒的神圣光照效果，提高30%受到的伤害。每当光耀直击引发制裁之光时，将给予制裁之光半径5米范围内的玩家1200点临时生命，持续90秒。光耀直击会处决血量低于15%的非BOSS生物。\n技能冷却时间8秒。\n每升一级增加3.75%光耀直击攻击伤害，最多升为10级。\n改动历史：\n- 7.0.0版本：重制技能，魔力消耗由500提高至600，伤害倍率由1000%降低至75%，每级伤害倍率由30%降低至3.75%，现在会给予对方神圣光照效果，处决血量低于15%的非BOSS生物，或是给予玩家临时生命值。\n- 6.1.7版本：增强技能，伤害系数由700%提高到1000%。"}, {"name": "神圣领域", "url": "https://www.mcmod.cn/item/443099.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443099.png?v=6", "category": "白魔导:二转技能:主动技能", "description": "消耗800魔力，将凝聚的圣光力量释放，以形成由圣光庇护的神圣力场，召唤持续60秒的圣光魔法阵在身边，每秒给予圣光魔法阵半径6米范围内的玩家持续60秒的神圣领域效果，提高50%造成的伤害，并且每次攻击可以补充伤害值4%的生命力。圣光魔法阵还将持续解除范围内玩家的沉默效果。\n技能冷却时间90秒。\n每升一级神圣领域BUFF持续时间增加6秒，最多升为10级。\n改动历史：\n- 7.0.0版本：重制技能，改动神圣领域BUFF的效果，现在神圣领域技能会召唤圣光魔法阵在原地持续生效，圣光魔法阵可以解除沉默DEBUFF。\n- 6.2.1版本：神圣领域对法书的攻击速度加成降低至每秒3次。\n- 6.1.8版本：神圣领域对法书的攻击速度加成降低至每秒5次。\n- 6.1.7版本：现在施放神圣领域后，法书攻击速度提升至每秒10次。\n- 6.1.4版本：现在神圣领域将提高玩家25%掉宝率。"}, {"name": "神圣烙印", "url": "https://www.mcmod.cn/item/443100.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443100.png?v=11", "category": "白魔导:二转技能:主动技能", "description": "消耗800魔力，引导光明的力量，向前方发射神圣之箭，对远距离目标造成75%魔法攻击光明属性纯净伤害，并对命中的目标施加神圣烙印，持有神圣烙印的敌人会持续被圣光球攻击，造成等同于直接命中伤害的追加伤害，若目标在持有烙印时死亡且附近有其他目标，烙印会保留剩余持续时间并转移到周围另一名目标身上。\n技能冷却时间12秒。\n每升一级增加3.75%神圣之箭攻击伤害，最多升为10级。\n神圣之箭命中目标后，圣光球会锁定攻击被直接命中的怪物，不论距离有多远。圣光球从天空砸落，对单体敌人造成伤害，无法穿透方块，持续时间15秒，每秒召唤4颗圣光球。可同时存在多个神圣烙印。\n历史改动：\n- 7.2.8版本：冷却时间由24秒缩短至12秒，效果持续时间由30秒缩短至15秒。\n- 7.0.0版本：神圣之箭改名为神圣烙印，魔力消耗由500增加至800，伤害倍率由1300%降低至75%，每级伤害倍率由30%降低至3.75%，圣光球攻击频率由每秒5次降低至每秒4次。\n- 6.2.0版本：圣光球攻击频率从每秒10次降低至每秒5次。\n- 6.1.7版本：神圣之箭追打时间从8秒提升至30秒，圣光球的攻击频率从每秒3次提升至每秒10次。\n- 6.1.4版本：神圣之箭伤害从1200%提升至1300%。\n- 5.7.2版本：神圣之箭伤害从850%提升至1200%，圣光球追打伤害从500%提升至神圣之箭攻击力的一半。"}, {"name": "真理之门", "url": "https://www.mcmod.cn/item/443101.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443101.png?v=18", "category": "白魔导:二转技能:超级技能", "description": "超级技能。\n消耗1500魔力，展开神圣咒语并咏唱圣光力量的最强魔法，打开通往真理的大门，对半径16米范围内的敌人造成20段500%魔法攻击光明属性神圣伤害，医疗自己与半径32米范围内所有玩家50000点生命值，给予20秒的无敌效果，并解除自己与周遭玩家的部分负面状态效果、清除所有血性值与创伤，同时给予自身与附近玩家持续60秒的真理之门效果，提高50%造成的伤害，提高10%最终伤害，提高10%职业增幅。当玩家施放真理之门时若自身周围有死亡玩家，无视其是否拥有致残立即复活该玩家。\n可以解除的负面效果有：冰缓，蛊毒，黑暗祈祷，致命熔岩，破灭祈祷，剧毒，石化，冻结，沉默（沉默状态下可以使用真理之门），抽搐，至残，瘫痪，同命，失明，饥饿，凋零，中毒，挖掘疲劳。\n技能冷却时间600秒。\n每升级一次增加25%真理之门攻击伤害与2500点治疗量，最多升为10级。\n历史改动：\n- 7.4.2版本：增强技能，现在开启真理之门还会给予20秒无敌。\n- 7.2.8版本：增强技能，提高治疗量，基础治疗量由20000提高至50000，每级增加治疗量由1000提高至2500，修正伤害、复活与治疗范围错误的问题。\n- 7.0.0版本：重制技能，伤害倍率由3600%降低至500%，移除重置自身CD效果，现在可以无视致残直接复活玩家。\n- 6.1.7版本：增强技能，真理之门现在可以重置所有技能CD。\n- 6.1.4版本：增强技能，技能伤害系数由3000%改为3600%，使用真理之门时会重置血性值。\n- 5.7.2版本：增强技能，现在可以在沉默状态下施放，且技能持续时间内不会被沉默。\n- 5.6.7版本：增强技能，buff持续时间由30秒提高为60秒，buff效果大幅提高，并且可以解除瘫痪buff了。\n- 5.5.9版本：增强技能，小幅增加真理之门的攻击速度。\n- 5.5.4版本：真理之门现在可以解除所有创伤。"}], "三转技能": [{"name": "圣光誓言", "url": "https://www.mcmod.cn/item/947717.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947717.png", "category": "白魔导:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高20%最终伤害，提高2000点最大魔力，提高50%恢复量。\n特殊能力\n解锁职业专属资源：神迹，释放治愈之光时可以获得1点神迹值，神迹值最多存储10点，可用于强化三转技能。\n强化圣光矢，总攻击次数提升5次，攻击间隔由0.35秒缩短至0.2秒。"}, {"name": "天界制裁", "url": "https://www.mcmod.cn/item/947719.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947719.png", "category": "白魔导:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：850%*23雷击+850%*5圣光+850%*1圣光球\n- 索敌半径：16米\n- AOE半径：2米\n- 负面效果-天界制裁：穿透防御-5 * 60秒\n- 魔力消耗：800点\n- 冷却时间：10秒\n- 持法书时按下设定的技能按键发动\n- 每升1级增加42.5%技能倍率\n技能描述\n技能效果\n咏唱来自天界的神圣审判，随机锁定16米范围内的1名敌人，优先锁定注视的目标，在目标位置连续降下23道落雷，对半径2米范围内的所有敌人造成850%魔法攻击光明属性神圣伤害，持续时间内每秒召唤一道圣光，圣光会随机打击距离落雷3.15米范围内的区域，圣光可以对自身周围2米范围内的所有敌人造成等同于落雷的伤害，至多持续5秒。\n落雷与圣光打击还会额外对目标施加持续60秒的天界制裁：持续时间内穿透防御-5。\n天界制裁结束后会额外对距离落雷5米范围内所有敌人发射一轮圣光球，造成1段等同于落雷的伤害。\n额外效果\n天界制裁的所有攻击对非BOSS目标造成伤害时，技能倍率会变为原先的1.5倍。\n职业专属\n潜行时释放天界制裁，将消耗1点神迹，落雷攻击将会处决生命值低于40%的非BOSS目标。"}, {"name": "神盾庇护", "url": "https://www.mcmod.cn/item/947940.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947940.png", "category": "白魔导:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 辅助能力-神盾庇护：抵挡伤害 * 10次 * 30秒\n- 辅助半径：8米\n- 魔力消耗：600点\n- 冷却时间：240秒\n- 持法书时按下设定的技能按键发动\n- 每升1级增加1秒最大持续时间\n技能描述\n技能效果\n呼唤神盾魔法，使一阵强大的正极能量涌向身边的队友，给予自身与距离自身8米以内所有玩家10层持续30秒的神盾庇护效果：持有时可以抵挡伤害，每次抵挡会消耗1层神盾庇护效果。\n职业专属\n潜行时释放神盾庇护，将消耗5点神迹值，给予的神盾庇护效果增加5层。"}, {"name": "和平之光", "url": "https://www.mcmod.cn/item/947952.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947952.png?v=1", "category": "白魔导:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 辅助能力-和平之光：30%击败怪物获得的职业经验量+100%造伤+20%职业增幅+120防御力+0.05冷却进度 * 120秒\n- 辅助半径：16米\n- 自拐能力：每秒额外冷却治愈之光1秒 * 120秒\n- 范围治疗：2000点*1次/秒*120秒\n- 治疗半径：16米\n- 魔力消耗：600点\n- 冷却时间：240秒\n- 持法书时按下设定的技能按键发动\n- 每升1级增加1秒和平之光与和平光环持续时间，100点范围治疗量\n技能描述\n技能效果\n咏唱祝福魔咒，召唤祈祷之光守护身边的队友，给予自身与距离自身16米以内所有玩家持续120秒的和平之光：提高30%击败怪物获得的职业经验量、100%造成的伤害、10%职业增幅、0.05冷却进度、120点防御力。\n额外效果\n额外召唤一个和平光环围绕在自身身边，和平光环每秒治疗自身与距离自身16米以内所有玩家2000点生命值，并缩短自身治愈之光1秒冷却时间，和平光环可以治疗被禁疗的玩家，但治疗量只有原先的30%，和平光环至多持续120秒。\n职业专属\n潜行时释放和平之光，将消耗5点神迹值，和平之光的职业增幅额外提高10%，冷却进度额外增加0.05。"}, {"name": "辉煌世纪", "url": "https://www.mcmod.cn/item/947953.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/947953.png", "category": "白魔导:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：950%*213抛射物+950%*42闪电（期望）\n- 段数补正：3段雷击\n- 索敌半径：16米\n- 范围治疗：2000点*2次/秒*40秒\n- 治疗半径：12米\n- 净化能力：致残、濒死CD * 2次/秒 * 40秒\n- 净化半径：12米\n- 魔力消耗：3000点\n- 冷却时间：900秒\n- 持法书时按下设定的技能按键发动\n- 每升1级增加47.5%技能倍率，100点范围治疗量\n技能描述\n技能效果\n咏唱无上的圣光魔法，展开所向披靡的强力阵法，在自身周围召唤跟随自身移动的辉煌阵法与4颗辉煌水晶。\n每颗辉煌水晶随机间隔0.5~1秒发射一颗圣光球，对随机单体目标造成950%魔法攻击光明属性心灵伤害，每颗辉煌水晶每发射5颗圣光球就会追加一道闪电，造成3段等同于圣光球的伤害。\n辉煌法阵每0.5秒治疗自身与距离自身12米以内所有玩家2000点生命值，同时解除周围玩家的致残与清除濒死CD，但无法解除已经因致残或濒死CD而倒地且无法救起的玩家。\n辉煌阵法与辉煌水晶至多持续40秒，每颗辉煌水晶初始生成时的攻击冷却与闪电攻击计数都不一样。\n职业专属\n潜行时释放辉煌世纪，将消耗10点神迹值，使本次辉煌世纪的技能倍率增加至原先的1.5倍。"}]}}, {"name": "咒术师", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "正常", "生存": "很强", "刷本效率": "高", "缺蓝": "不缺", "对单": "极高", "特殊1": "穿透增幅", "特殊2": "高额群体buff"}, "tiers": {"固有技能": [{"name": "符咒解散", "url": "https://www.mcmod.cn/item/440084.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440084.png?v=4", "category": "咒术师:固有技能", "description": "固有技能。\n消耗200点魔力，呼唤符文魔法，解散半径12米范围内的所有魔力残骸[1]，每一个残骸都将补充自身300魔力值，只有存在至少1秒及以上的符咒残骸能够被解散，当符咒解放后，咒术师自身的魔力值全满时，将会额外医疗咒术师自身与距离咒术师12米范围内的玩家3000点生命值，且补充咒术师自身3000点血性值。\n持扇子时蹲下按武器功能键（默认V键）发动。\n技能冷却时间1秒。\n每升级一次增加150点恢复的生命值与恢复的血性值，最多升为10级。\n[1] 扇子发射的符咒命中方块或实体后，将在命中位置生成一个对应的魔力残骸，魔力残骸最多存在12.5秒。\n历史改动：\n- 7.3.4版本：调整技能，降低血性值改为补充血性值。\n- 7.1.9版本：增强技能，基础治疗量由1200提升至3000，每级治疗量由60提升至150，现在可以治疗周围队友。\n- 7.0.0版本：重置技能，效果由补满魔力并获得魔导效果改为解散附近魔力残骸并恢复魔法值与生命值，冷却时间由30秒缩短为1秒，升级效果由增加魔导持续时间改为增加恢复量。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}, {"name": "符咒充能", "url": "https://www.mcmod.cn/item/440085.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440085.png?v=17", "category": "咒术师:固有技能", "description": "固有技能。\n消耗200魔力，充能半径12米范围内所有的魔力残骸[1]，只有存在至少1秒及以上的魔力残骸能够被解散，每一种残骸充能效果都不同。\n- 魔魂符：恢复半径12米范围内的玩家200点魔力值，给予范围内的玩家60秒的魔力恢复，学习二转被动符咒精通后瞬间恢复的魔力值提高200点，充能魔魂符获得的魔灵值增加1点。\n- 极冰符：给予半径12米范围内的敌人持续10秒的缓慢I与冻结I效果，学习二转被动符咒精通后持续时间延长至15秒。\n- 烈火符：制造爆炸，对半径4米范围内的敌人造成75%魔法攻击魔法属性爆破伤害，学习二转被动符咒精通后总技能倍率提高至原先的1.5倍。\n- 圣光符：治疗半径12米范围内的友方实体400点生命值并恢复400点血性，学习二转被动符咒精通后圣光符治疗量与血性恢复量翻倍。\n- 大地符：将半径8米范围内的怪物持续向大地符充能位置牵引，每3tick牵引0.03米，持续10秒，可以叠加，学习二转被动符咒精通后持续时间延长至13秒。\n- 暗黑符：为半径4米范围内的怪物施加50%技能倍率的DOT，持续7秒，多次充能重置持续时间，无法叠加DOT层数或个数，多名玩家的DOT相互独立计算，学习二转被动符咒精通后DOT的技能倍率提高至100%，充能暗黑符获得的魔灵值增加2点。\n持扇子时按下武器功能键（默认V键）发动。\n技能冷却时间1秒。\n每升级一次增加3.75%烈火符攻击伤害，20点圣光符治疗量与血性恢复量，最多升为10级。\n学习专精护佑符咒后，符咒充能成功充能符咒时，将给予距离符咒8米内且最近的玩家1000点临时生命值，持续300秒。\n符咒精通增益计算在技能升级效果之后。\n[1] 扇子发射的符咒命中方块或实体后，将在命中位置生成一个对应的魔力残骸，魔力残骸最多存在12.5秒。\n历史改动：\n- 7.3.4版本：新增大地符与暗黑符，符咒精通效果增强，圣光符现在还可以恢复血性值，技能倍率由50%提高至75%，每级技能倍率由2.5%提高至3.75%，效果持续时间由60秒缩短至10秒。\n- 7.0.0版本：重置技能，魔力消耗由100提高至200，魔魂符与极冰符效果时间由15秒延长至60秒，魔魂符现在会瞬间恢复200点魔力值，烈火符技能倍率由100%降低至50%，圣光符治疗量由10%最大生命值调整为400点生命值。\n- 6.1.7版本：削弱技能，圣光符的回血效果由30%改为10%\n- 5.6.8版本：修正技能，现在符咒充能有1秒的冷却时间，可以防止一些意外的出现。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}], "一转技能": [{"name": "风速符", "url": "https://www.mcmod.cn/item/440081.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440081.png?v=12", "category": "咒术师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗200魔力，施放暴风属性的符咒，向前方发射2波共计6发风速符，对命中目标每tick造成60%魔法攻击暴风属性诅咒伤害，并对目标施加持续30秒的风破效果，提高10%受到的伤害。\n风速符命中非BOSS目标时，总技能倍率将提高至原先的1.5倍。\n学习二转被动技能符咒精通后风速符总技能倍率永久增加20%，与总技能倍率加算，与非BOSS目标倍率增加乘算，每波风速符都会向外额外散射2枚相同的风速符。\n技能冷却时间5秒。\n每升级一次增加3%技能倍率，最多升为10级。\n历史改动：\n- 7.3.4版本：调整技能，学习心灵之火后增加技能倍率改为学习符咒精通后增加技能倍率，增加量由70%降低至20%，学习符咒精通后每波风速符都会向外额外散射2枚风速符，对非BOSS单位的增伤由1.3倍提高至1.5倍。\n- 7.1.6版本：重置技能，伤害系数由110%降低至60%，每级伤害系数由5.5%降低至3%，攻击段数由5段减少至2段，冷却时间由20秒缩短至5秒，现在风速符可以穿透生物，对非BOSS目标的总技能倍率提高至1.3倍，学习被动心灵之火后伤害系数+70%。\n- 7.0.6版本：增强技能，伤害系数由100%提升至110%，每级伤害系数由5%提升至5.5%。\n- 7.0.0版本：重置技能，伤害系数由250%降低至100%，每级伤害系数由10%降低至5%，符咒总数量由30减少至15，现在命中敌人会施加风破效果。\n- 6.3.1版本：增强技能，伤害系数由200%提升至250%，发射速度提升。\n- 6.2.0版本：增强技能，伤害系数由150%提升至200%。"}, {"name": "自然晨光", "url": "https://www.mcmod.cn/item/440082.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440082.png?v=7", "category": "咒术师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗200魔力与治疗粉，以光属性的符咒召唤一道持续60秒的自然晨光在身边，自然晨光每秒可医疗半径4米范围内的玩家200点生命值与100点魔力值，并给予持续60秒的晨光效果，提高50%造成的伤害，提高10%职业增幅，提高5点穿透值，额外增加20点不受限制的额外感知，同一个玩家只能同时拥有一个自然晨光区域。\n技能冷却时间60秒。\n每升级一次增加10点自然晨光的治疗量，5点自然晨光补充的魔力值，最多升为10级。\n当学习专精灵脉轮转后，减少自然晨光的35%持续时间与冷却时间。\n历史改动：\n- 7.3.4版本：增强技能，现在晨光效果还会额外增加20点额外感知。\n- 7.1.8版本：增强技能，现在晨光效果还会额外给予5点穿透值。\n- 7.1.4版本：增强技能，现在每秒可以恢复50%自然晨光治疗量的魔力值。\n- 7.0.0版本：重置技能，魔力消耗由300降低至200，持续时间由50秒延长至60秒，每秒治疗量由16%最大生命值改为200点生命值，升级效果由增加5秒自然晨光持续时间改为增加10点治疗量与6秒BUFF时间。"}, {"name": "闪雷符", "url": "https://www.mcmod.cn/item/440083.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440083.png?v=6", "category": "咒术师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗200魔力，施放雷电属性的符咒，向前方发射1次闪雷符，对直接命中的目标造成185%魔法攻击闪电属性能量伤害，并在命中目标后呼唤落雷，对半径4米的敌人造成5段等同于直接命中伤害的范围伤害，同时在命中处留下闪雷符残骸。当该残骸被符咒充能时，将会呼唤落雷，造成1~2段与命中落雷相同的范围伤害。\n学习二转被动符咒精通后，闪雷符残骸被符咒充能时的总技能倍率提高至原先的2.5倍。\n技能冷却时间20秒。\n每升级一次增加7.25%闪雷符攻击伤害，最多升为10级。\n变更历史：\n- 7.1.6版本：重置技能，技能倍率由145%提高至185%，每级技能倍率由7.25%提高至9.25%，闪电攻击段数由1段增加至5段，冷却时间由4秒延长至20秒。\n- 7.0.6版本：增强技能，技能倍率由125%提高至145%，每级技能倍率由6.25%提高至7.25%。\n- 7.0.0版本：重制技能，技能倍率由300%降低至125%，每级技能倍率由10%降低至6.25%，现在还会在命中处留下可被充能的残骸。\n- 6.2.0版本：增强技能，闪雷符技能倍率由250%提升至300%，雷电伤害由150%提升至与闪雷符伤害相同。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}, {"name": "心灵之火", "url": "https://www.mcmod.cn/item/440080.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440080.png?v=6", "category": "咒术师:一转技能:被动技能", "description": "一转技能。\n最低学习等级5等。\n不断的学习咒法，领悟灵魂的力量，提高10%最终伤害，提高最大魔力值1000点，获得抵抗击退效果，每次成功充能一个符咒的魔力残骸，将获得一层心灵之火效果，提高12%造成的伤害，心灵之火效果最高可以获得10层。\n式神斩的纸式神属于状态效果而非魔力残骸，因此无法触发心灵之火的效果。\n当学习专精灵魂之火后，若使用心灵之火技能使心灵之火效果提高到了20层，将移除心灵之火效果，并给予自身与附近所有玩家职业等级*70点临时生命值，持续600秒。冷却时间20秒。（需配合二转被动符咒精通提高心灵之火效果上限）\n历史改动：\n- 7.3.7版本：增强技能，现在还会使玩家免疫击退。\n- 7.3.4版本：风速符伤害倍率增加的效果从心灵之火移动到符咒精通。\n- 7.1.6版本：现在可以使风速符伤害倍率增加70%。\n- 7.0.0版本：重制技能，移除提高魔法攻击力与魔力恢复效果，改为提高最终伤害与最大魔力，现在充能符咒可以获得心灵之火效果了。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}], "二转技能": [{"name": "符咒精通", "url": "https://www.mcmod.cn/item/443092.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443092.png?v=4", "category": "咒术师:二转技能:被动技能", "description": "仔细钻研魔法，追求更高深的符咒知识，提高10%最终伤害，提升30点最大魔灵值，强化心灵之火效果，最大层数提升至20层，并且每次充能符咒能获得2层效果。强化所有符咒充能的效果，圣光符提升100%治疗量与血性补充，烈火符提升50%爆炸伤害，极冰符提升50%缓速与冻结时长，魔魂符提升200点魔力恢复与1点魔灵值获得，闪雷符提升150%造成的雷电伤害，大地符增加30%吸引怪物的持续时间，暗黑符增加100%DOT攻击的伤害与2点魔灵值获得，风速符提升20%造成的伤害，并且增加召唤的范围与符咒数量。\n历史：\n- 7.3.4版本：增强技能，圣光符的恢复量增加由20%提高至100%，烈火符的倍率增加由20%提高至50%，极冰符的持续时间增加由20%延长至50%，魔魂符的魔力恢复由100增加至200，现在还会额外给予1点充能魔魂符时的魔灵值，闪雷符伤害倍率增加由30%提高至150%，新增大地符与暗黑符，风速符额外散射2枚，提升20%风速符的伤害倍率。\n- 7.0.0版本：重制技能，移除普攻额外伤害和月之神力效果，现在可以提高10%最终伤害，并强化所有魔力残骸的符咒充能效果。\n- 6.3.1版本：增强技能，现在进行普通攻击还能获得月之神力效果。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}, {"name": "灵转符", "url": "https://www.mcmod.cn/item/745716.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/745716.png?v=7", "category": "咒术师:二转技能:主动技能", "description": "消耗400魔力，呼唤符文魔法，召唤一道充能灵转符在身边，同时给予自身4秒的幻灵效果：受到的伤害-35%。充能灵转符在4秒后将引发魔力爆炸，对充能灵转符半径4米范围内的敌人造成1200%魔法攻击魔法属性爆破伤害，并在原地留下虚无灵转符，虚无灵转符可再次被冷却完毕的灵转符技能触发（该次触发不会使技能进入CD），被触发后将会在虚无灵转符的位置再次引发等同于充能灵转符的爆炸，对半径8米范围内的怪物施加持续20秒的缓慢X与冻结I效果，并给予咒术师自身30点魔灵值，若虚无灵转符的爆炸成功造成了伤害，则会治疗咒术师30000点生命值。虚无灵转符最多存在30秒。\n技能冷却时间10秒。\n每升一级增加60%灵转符攻击伤害，1500点治疗量，最多升为10级。\n学习专精防护转移后，触发虚无灵转符的爆炸后将会获得持续2秒的无敌效果。\n历史改动：\n- 7.4.3版本：削弱技能，幻灵的伤害减免效果由75%降低至35%。\n- 7.3.4版本：调整技能，技能倍率由600%提升至1200%，每级技能倍率由30%提升至60%，基础治疗量由3000提升至30000，每级治疗量由150提升至1500，冷却时间由8秒延长至10秒，现在释放充能灵转符会给予自身幻灵效果，触发虚无灵转符不再传送咒术师自身，且虚无灵转符的爆炸伤害位置从咒术师位置改为虚无灵转符位置。\n- 7.1.9版本：现在灵转符会给予咒术师16点魔灵值。\n- 7.1.6版本：增强技能，魔力消耗由600减少至400点，冷却时间由10秒缩短至8秒，虚无灵转符不再能被符咒充能触发，而是需要使用冷却完毕的灵转符技能触发。\n- 7.1.4版本：增强技能，伤害倍率由500%提高至600%，每级伤害倍率由25%提高至30%，现在传送爆炸成功造成伤害时会给予咒术师一层纸式神并治疗一定生命值。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}, {"name": "式神斩", "url": "https://www.mcmod.cn/item/745717.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/745717.png?v=5", "category": "咒术师:二转技能:主动技能", "description": "消耗600魔力，展开弹幕结界，向前方发射3波共计共计27发纸式神，对命中目标造成220%魔法攻击光明属性纯净伤害，每次释放式神斩可给予咒术师自身一层纸式神效果，每次命中敌人可以对其施加一层纸式神效果，纸式神效果最高可以获得5层。\n咒术师施展式神斩前，若咒术师自身已拥有纸式神效果，每层纸式神效果会降低10%式神斩的冷却时间。\n受击者持有纸式神效果时，降低10点穿透防御。\n当施放符咒充能时，若符咒充能范围内怪物拥有纸式神效果，将在怪物身上引发魔力爆炸，并根据纸式神的层数而造成基础倍率为220%的魔法攻击光明属性纯净伤害，并消除目标身上的纸式神效果，目标身上的每层纸式神都会使总技能倍率提高原技能倍率的0.2倍。5层纸式神与10级式神斩技能等级时，可造成515%倍率的伤害，该效果无法触发心灵之火与式神操演引爆魔力残骸叠加层数的效果。\n纸式神直接命中非BOSS目标时，总伤害倍率将会提高至原先的1.2倍。在非BOSS目标上引爆纸式神时，总伤害倍率将会额外提高至原先的2倍，与纸式神层数倍率乘算。\n技能冷却时间14秒。\n每升一级增加11%纸式神直接命中伤害，3.75%纸式神爆炸伤害，最多升为10级。\n历史改动：\n- 7.3.4版本：增强技能，每波飞弹数量由7枚增加至9枚，冷却时间由16秒缩短至14秒，在非BOSS目标上引爆纸式神时技能倍率翻倍，符咒充能技能倍率增加使纸式神引爆时每级技能倍率也从2.5%增加至3.75%。\n- 7.2.4版本：增强技能，现在纸式神效果可以使受击者被玩家忽略10点穿透防御。\n- 7.1.4版本：增强技能，式神斩的技能倍率由200%提高至220%，每级技能倍率由10%提高至11%，现在灵转符的传送爆炸命中敌人时会给予咒术师自身一层纸式神。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}, {"name": "守灵结界", "url": "https://www.mcmod.cn/item/745718.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/745718.png?v=7", "category": "咒术师:二转技能:主动技能", "description": "消耗900魔力，利用光之结界的力量，召唤一朵持续5分钟的结界花在身边，结界花每0.75秒给予召唤者1点魔灵值，恢复半径4米范围内玩家250点魔力值，并且向该范围内的玩家给予或叠加持续300秒的结界守护效果，至多叠加15层，每层效果给予1%职业增幅与1点穿透值。当咒术师自身释放符咒充能成功充能符咒，且符咒充能范围内有属于自己的结界花时，结界花将召唤魔力脉冲攻击半径24米范围内的目标，造成350%魔法攻击自然属性植物伤害，每个成功充能的符咒都将增加2道魔力脉冲的次数，结界花每0.75秒至多召唤1道魔力脉冲。\n技能冷却时间60秒。\n每升一级增加17.5%魔力脉冲攻击伤害，最多升为10级。\n注：\n- 引爆纸式神不计入结界花的魔力脉冲数量。\n历史改动：\n- 7.3.4版本：增强技能，魔力消耗由800增加至900，结界花持续时间与结界守护效果持续时间由1分钟延长至5分钟，索敌范围由20米扩大至24米，结界花给予效果、魔灵值与攻击间隔由1秒缩短至0.75秒，结界守护由视咒术师穿透叠层改为范围内持续叠层，技能倍率由300%提升至350%，每级技能倍率由15%提升至17.5%。\n- 7.2.8版本：增强技能，结界花的攻击范围由16增加至20。\n- 7.1.9版本：结界守护伤害倍率由200%提升至300%，每级伤害倍率由10%提升至15%，现在结界花每秒会给予召唤者1点魔灵值。\n- 7.1.8版本：现在结界守护还会给予玩家10点穿透值。\n- 7.1.6版本：结界花给予玩家的结界守护效果层数提升，提升指为咒术师自身穿透值的30%，现在结界守护每层可以提升1点物理攻击力与1点魔法攻击力。\n- 7.1.4版本：守灵结界的伤害倍率由100%提升至200%，每级伤害倍率由5%提升至10%。\n此段资料引用于“魔灵 (魔靈)”并与其保持同步更新。  编辑7.1.9版本开始，咒术师开始拥有魔灵值。\n以咒术师为中心球形半径12米范围内有怪物时，魔灵值每0.6秒消耗1点，自动召唤1道纸式神从上方落下攻击单体目标。魔灵值召唤的纸式神仅有伤害的效果，无法为敌人或自身叠加纸式神效果。\n纸式神基础技能倍率为100%，心灵之火技能每提升1级，技能倍率提升5%，即最大105%技能倍率。\n魔灵值持有上限为30点，学习二转被动符咒精通后，额外提升30点魔灵值上限。\n咒术师释放符咒充能时，只要成功充能了符咒就会根据被充能的符咒类型来增加自身魔灵值。\n- 魔魂符会增加4点魔灵值，学习符咒精通后额外+1\n- 极冰符会增加2点魔灵值\n- 烈火符会增加1点魔灵值\n- 圣光符会增加3点魔灵值\n- 大地符会增加2点魔灵值\n- 暗黑符会增加5点魔灵值，学习符咒精通后额外+2\n- 闪雷符会增加8点魔灵值\n- 咒术师使用灵转符技能成功充能虚无灵转符会增加30点魔灵值\n- 释放式神斩技能会增加10点魔灵值。\n- 咒术师的守灵结界生效时，不论距离多远，只要咒术师的魔灵值低于10点就会每秒为咒术师增加1点魔灵值。\n此外，咒术师使用永恒开拓者之心普通攻击时也能获得1点魔灵值。\n历史改动：\n- 7.4.8版本：新增永恒开拓者之心，每次普攻获得1点魔灵值。\n- 7.3.4版本：新增大地符玉暗黑符，魔魂符学习符咒精通后魔灵值+1，虚无灵转符充能后魔灵值由16增加至30。\n- 7.2.8版本：魔灵攻击间隔由0.75秒缩短至0.6秒，现在咒术师周围没有怪物也不会消耗魔灵值了。"}, {"name": "六壬神域", "url": "https://www.mcmod.cn/item/443096.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443096.png?v=12", "category": "咒术师:二转技能:超级技能", "description": "超级技能。\n消耗1500魔力，展开最为强大的魔力弹幕，在空中召唤巨大的魔法阵，并给予32米范围内玩家持续30秒的六壬神域效果：每5秒自动提升1级，每级增加5%最终伤害、20点物理攻击力与20点魔法攻击力。魔法阵将持续召唤流星攻击处于法阵内的随机单体目标，造成半径2米的3段950%魔法攻击黑暗属性震击伤害，给予命中目标一层持续30秒的纸式神效果，每当流星爆炸并命中目标时，可在地面留下陨石坑，陨石坑将持续烧伤附近的所有目标，造成47.5%魔法攻击黑暗属性震击伤害，并且给予30秒的缓慢效果。当魔法阵消失时，将移除半径32米范围内所有玩家致残与沉默效果。\n技能冷却时间600秒。\n每升级一次增加47.5%六壬神域攻击伤害，2.38%陨石坑烧伤伤害，最多升为10级。\n魔法阵索敌半径16米，每秒对随机单体敌人发动1波半径2米的范围攻击，每波造成3段伤害并留下1个陨石坑，每波攻击只会对每个命中敌人施加1次纸式神效果，魔法阵持续60秒。\n陨石坑持续8.75秒，每秒造成1次伤害，最多造成8次伤害。\n变更历史：\n- 7.3.4版本：调整技能，六壬神域效果的3000最大伤害改为20点物理与魔法攻击力。\n- 7.1.6版本：增强技能，现在施法六壬神域技能将会给予32米范围内所有玩家30秒的六壬神域效果。\n- 7.0.0版本：重制技能，魔力消耗由900提高至1500，伤害倍率由3500%降低至950，总攻击段数由1200降低至180，现在命中敌人还会给予纸式神效果并生成陨石坑，移除星破效果。\n- 6.3.1版本：增强技能，范围攻击持续时间由16秒延长至60秒，攻击段数由每波2次提升至每波10次。\n- 5.6.7版本：调整技能，现在星辰重击将给予星破效果，而不是风切。\n- 5.5.9版本：增强技能，大幅增加星辰重击的攻击速度。\n- 5.4.9版本：重新调整技能的伤害值。"}], "三转技能": [{"name": "式神操演", "url": "https://www.mcmod.cn/item/948219.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948219.png", "category": "咒术师:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高20%最终伤害，提高2000点最大魔力值，提高30点最大魔灵值。\n特殊能力\n基础信息\n- 技能倍率：420%*70抛射物\n- 储存时间：120秒（共享储存时间，无法重置或延长）\n- 索敌半径：16米\n- 范围治疗：3675\n- 治疗半径：17米\n能力描述\n施放符咒解散成功解散符咒后，魔灵值召唤纸式神的间隔由0.6秒缩短至0.25秒，持续10秒，另外成功使用符咒充能充能符咒后，除式神斩的纸式神外，每个被充能的符咒都将召唤1个纸式神在身边环绕，纸式神至多持续120秒，召唤后无法重置或延长持续时间，所有纸式神持续时间与第一个纸式神相同，最多拥有15个纸式神环绕。\n当获得15个纸式神时，立刻补充自己与附近17米范围内所有玩家3675点生命值，纸式神会以每0.15秒1颗的速度发射至多70颗魔法球攻击距离自身16米范围内随机的目标，每次造成420%魔法攻击光明属性回馈伤害，所有魔法球发射后环绕的纸式神将会消失，发射耗时共计10.5秒。\n魔法球发射时无法重复触发式神操演相关效果，若发射魔法球时环绕的纸式神正好达到了最大存在时间，则会直接消失并中断魔法球的发射。\n学习二转被动符咒精通后，充能符咒获得的环绕自身的纸式神数量也会翻倍。"}, {"name": "幻犬神击", "url": "https://www.mcmod.cn/item/948289.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948289.png", "category": "咒术师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：1350%*12段\n- 真实魔法伤害：50点*12段\n- AOE半径：2米\n- 负面效果-咬碎：韧性削减10% * 22秒\n- 魔力消耗：800点\n- 冷却时间：10秒\n- 持扇子时按下设定的技能按键发动\n- 每升1级增加67.5%技能倍率\n技能描述\n命中效果\n召唤强大的幻影之狼，对目标降下残酷的撕咬，在准星指向的地面上召唤幻影之狼，对半径2米范围内所有敌人造成12段1350%魔法攻击魔法属性神兽伤害，每段伤害还会附加50点真实魔法伤害，同时给予目标20秒咬碎效果：韧性降低10%。幻犬神击能够处决生命值低于30%的非BOSS生物。\n幻犬神击的释放地点上方3格需要都是空气，否则将无法释放。\n职业专属\n施放幻犬神击时，若至少拥有5点魔灵值，则消耗5点魔灵值，使总技能倍率提升至原先的1.2倍，并且返还50%冷却时间。"}, {"name": "灵体幻影", "url": "https://www.mcmod.cn/item/948293.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948293.png?v=1", "category": "咒术师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：15%*25秒\n- 索敌半径：16米\n- 魔力消耗：600点\n- 冷却时间：90秒\n- 持扇子时按下设定的技能按键发动\n- 该技能升级没有效果\n技能描述\n呼唤灵体魔咒，将准星指向的目标的灵魂抽离，在自身位置召唤目标的灵体幻影，灵体幻影不会移动、施放技能或攻击。灵体幻影受到攻击时，会将伤害按比例传递给目标，目标死亡后，灵体幻影会立即消失，灵体幻影必须与目标存在相同维度，并且需要目标距离灵体幻影不超过16米，才能对目标造成伤害，灵体幻影至多持续25秒。\n对于魔法金属类型的伤害，灵体幻影会将其降低85%后传递给目标，独立乘区；对于非魔法金属类型的伤害，灵体幻影会将其基础攻击力降低85%后传递给目标。\n由于灵体幻影不会阻挡抛射物，因此部分箭矢、标枪即使不具备穿透能力也能穿透造成多段伤害，但部分命中效果无法触发，如命中后引爆。大部分抛射物由于是命中后自行消散，不会触发该特性。\n由于是传递基础伤害，因此为幻影施加受到的伤害增加类效果不会增幅伤害。\n特定情况下召唤索敌距离会比16米更远，因此可能出现召唤成功但无法打出伤害的距离，释放时需注意避免该情况。"}, {"name": "御守连结", "url": "https://www.mcmod.cn/item/948295.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948295.png?v=1", "category": "咒术师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 辅助能力-御守连结：20%终伤+20%职业增幅+10%受到的伤害减免+10无敌帧 * 83秒\n- 锁定距离：10米\n- 魔力消耗：600点\n- 冷却时间：240秒\n- 持扇子时按下设定的技能按键发动\n- 每升1级增加1秒守护连结持续时间（由于每2秒施加一次BUFF，因此每2级才会延长2秒实际持续时间）\n技能描述\n技能效果\n咏唱光之咒语，召唤守护队友的灵魂连结，瞄准一名玩家，召唤守护连结在双方附近，守护连结至多持续80秒，持续时间内每2秒给予自身与该玩家5秒的御守连结：职业增幅+20%、最终伤害+20%、受到的伤害减免+10%、无敌帧+10，一次只能与一名玩家进行守护连结，重新对其他玩家施放的候会解除原来玩家的守护连结效果。如果施放守护连结时没有其他玩家，将只对自身有效，且效果等级提升至2级，但数值不会提升。\n御守连结释放时，需要等待2秒后才会给予效果。\n释放守护连结时最远锁定距离为10米，成功释放后守护连结将会自动跟随玩家，若释放者与被守护目标相距不超过16米，则会持续出现光束特效，不论释放者与被守护者相距多远都不会影响守护连结的生效。"}, {"name": "饕餮绘卷", "url": "https://www.mcmod.cn/item/948298.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948298.png", "category": "咒术师:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：1550%*2段/秒*100秒\n- AOE半径：16米\n- 负面效果-饕餮贪欲：穿透防御-20%*125秒\n- 负面半径：16米\n- 辅助能力-饕餮绘卷：最终伤害增加 [目标已损失生命百分比] * 125秒\n- 辅助半径：32米\n- 魔力消耗：1800点\n- 冷却时间：900秒\n- 持扇子时按下设定的技能按键发动\n- 每升1级增加77.5%技能倍率\n技能描述\n在准星指向的方块处摊开封印的卷轴，从中释放出四凶饕餮，贪婪的汲取精气，每0.5秒对半径16米范围内目标造成1550%魔法攻击寒冰属性冻伤伤害，同时给予目标25秒饕餮贪欲效果：降低20%穿透防御（百分比穿透防御削减的计算在固定值穿透防御削减之后）。并每2秒给予自身与半径32米范围内所有玩家25秒饕餮绘卷效果：最终伤害增加 [目标已损失生命百分比]。饕餮绘卷至多存在100秒，饕餮绘卷的攻击能够处决生命值低于30%的非BOSS生物。\n饕餮绘卷的释放地点上方3格需要都是空气，否则将无法释放。"}]}}, {"name": "神射手", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "大，且繁琐", "生存": "很弱", "刷本效率": "正常", "缺蓝": "缺", "对单": "极高", "特殊1": "有大输出爆炸", "特殊2": "准头要求高"}, "tiers": {"固有技能": [{"name": "穿空箭", "url": "https://www.mcmod.cn/item/438191.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438191.png?v=8", "category": "神射手:固有技能", "description": "基础信息\n- 固有技能\n- 技能倍率：100%*1抛射物\n- 段数补正：贯穿抛射物\n- 易伤能力-击穿：10%*30秒\n- 魔力消耗：200点\n- 冷却时间：3秒\n- 持弓时潜行射击发动，该技能释放优先于其它神射手技能\n- 每升1级增加5%技能倍率，1秒击穿与元素箭矢持续时间，最多升为10级\n- 冷却减免倍率：100%\n简单描述\n发射具有贯穿能力的穿空箭，造成100%物理远程伤害，同时对目标施加30秒击穿：易伤+10%。\n释放时若已装填了爆裂箭或闪雷矢，则会释放组合技，同时使组合的技能与穿空箭一同进入冷却，组合技每次造成伤害都会额外附加伤害更高的范围伤害，组合技造成伤害会给予神射手30秒元素箭矢，使后续直接直接释放或与穿空箭组合释放的爆裂箭、闪雷矢冷却时间减少30%。\n穿空箭直接命中非BOSS会使技能倍率提高，学习专精分裂射击或轻盈弓法会使该效果进一步提高，但会降低基础技能倍率，分裂射击对组合技也有效。\n学习二转被动与三转被动会进一步提高技能倍率。\n详细描述\n命中效果\n借助暴风元素的力量发射穿空箭矢，能够贯穿直线目标并造成100%的物理远程暴风属性波动伤害，同时对目标施加30秒的击穿效果：受到的伤害增加+10%。\n穿空箭直接命中非BOSS目标时，技能倍率将提高至原先的1.3倍，该效果与专精非BOSS增伤加算生效，对组合技的范围伤害乘算生效，即使范围伤害命中的是BOSS目标也会生效。\n组合技\n释放时若已装填了爆裂箭，则会发射爆裂穿空箭，并使爆裂箭与穿空箭一同进入冷却。爆裂穿空箭每次造成伤害都会附加1段半径4米的爆炸伤害，爆炸技能倍率为直接命中的1.2倍。\n释放时若已装填了闪雷矢，则会发射雷霆穿空箭，并使闪雷矢与穿空箭一同进入冷却。雷霆穿空箭每次造成伤害都会附加2段半径6米的范围伤害，每次范围伤害最多命中5个目标，范围伤害技能倍率为直接命中的1.2倍。\n组合技命中敌人后，会给予神射手自身30秒的元素箭矢效果，持续时间内后续释放的爆裂箭、闪雷矢或组合技的爆裂箭与闪雷矢冷却时间缩短30%（向下取整）。\n专精能力\n学习专精分裂射击后，穿空箭与通过连成一气释放的穿空箭都会在水平方向上额外发射2支，额外的穿空箭不会消耗箭矢，穿空箭的总技能倍率将降低至0.6倍；命中非BOSS单位的额外增伤增加0.2倍。\n学习专精轻盈弓法后，穿空箭的技能冷却时间将减少2秒，常规释放穿空箭的技能倍率将降低至0.8倍，而通过连成一气释放的穿空箭技能倍率则提升0.1倍；命中非BOSS单位时，2种方式释放的穿空箭额外增伤都将增加0.3倍。\n职业专属\n学习一转被动弓术精通后，弓箭手以任意方式造成击杀都会使穿空箭的冷却时间减少1秒。\n学习二转被动蓄力射击后，穿空箭的总伤害倍率将会提高至原先的3倍，与其它技能倍率乘区均为乘算。\n学习三转被动弱点狙击后，穿空箭的总伤害倍率将会提高至原先的2倍，与其它技能倍率乘区均为乘算。\n注\n穿空箭的技能倍率乘区组成为：技能倍率*组合技增幅*专精衰减*(自带非BOSS增伤+专精非BOSS增伤)*二转被动*三转被动。\n装填了爆裂箭或闪雷矢后，若尝试在魔力不足的情况下释放爆裂穿空箭或雷霆穿空箭会使爆裂箭或闪雷矢直接进入冷却时间。\n历史改动：\n- 7.2.8版本：增强技能，现在穿空箭可以与爆裂箭或闪雷矢共存成为组合技。\n- 7.1.6版本：调整技能，伤害倍率由175%降低至100%，每级伤害倍率由8.75%降低至5%，技能冷却时间由5秒缩短至3秒，现在穿空箭命中非BOSS单位时将会提高0.3倍技能倍率，现在穿空箭可以被分裂射击与轻盈弓法专精影响。\n- 7.0.0版本：重制技能，伤害倍率由420%降低至175%，每级倍率由10%降低至8.75%，冷却时间由0秒延长至5秒，现在对非BOSS目标倍率会提高至原倍率的115%，现在命中敌人会给予击穿效果。\n- 6.2.0版本：增强技能，伤害倍率从400%提高到420%。"}, {"name": "麻痹陷阱", "url": "https://www.mcmod.cn/item/438192.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438192.png?v=5", "category": "神射手:固有技能", "description": "基础信息\n- 固有技能\n- 技能倍率：50%*1段/秒*20秒\n- AOE半径：4米\n- 负面效果：缓慢6+麻痹*5秒\n- 负面半径：4米\n- 自拐能力-麻药：100%造伤 * 80秒\n- 魔力消耗：200点\n- 冷却时间：20秒\n- 持弓时按下武器功能键（默认V键）发动\n- 每升1级增加2.5%技能倍率，3秒麻药持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n技能效果\n运用狩猎知识在脚下迅速安装麻痹陷阱。陷阱附近4米有敌方目标时，将每秒造成1次50%物理远程闪电属性雷霆伤害并给予目标5秒的缓慢Ⅵ与麻痹效果。另外麻痹陷阱对目标造成伤害时可给予神射手自身60秒麻药效果：提高100%造成的伤害。陷阱至多持续20秒，最多同时命中6个目标。\n历史改动：\n- 7.0.0版本：重制技能，伤害倍率由270降低至50%，每级伤害倍率由10%降低至2.5%，技能冷却时间由5秒延长至20秒，麻痹持续时长由9秒缩短至5秒，现在命中敌人还会给予缓慢效果并给予自身麻药效果。\n- 6.2.0版本：增强技能，伤害系数由250%提升至270%。"}], "一转技能": [{"name": "闪雷矢", "url": "https://www.mcmod.cn/item/438187.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438187.png?v=5", "category": "神射手:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：240%*1抛射物\n- 滞留伤害：240%*1.4段/秒*5秒（期望）\n- 滞留伤害半径：3米\n- 魔力消耗：300点\n- 冷却时间：20秒\n- 持弓时按下设定的技能按键装填，射箭后发动\n- 每升1级增加12%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n呼唤雷电的力量发射闪雷箭矢。对命中目标造成240%物理远程闪电属性雷霆伤害，并在命中目标后呼唤持续5秒的落雷魔法阵，落雷魔法阵每秒召唤1道伤害等同于直接命中伤害的落雷造成范围伤害。\n历史改动：\n- 7.0.0版本：重制技能，魔力消耗由500降低至300，伤害倍率由280%降低至240%，每级倍率由20%降低至12%。\n- 6.2.0版本：增强技能，落雷由造成100%魔法攻击雷电属性能量伤害转变为造成与箭矢相同的伤害，箭矢伤害系数由250%提升至280%。"}, {"name": "爆裂箭", "url": "https://www.mcmod.cn/item/438188.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438188.png?v=6", "category": "神射手:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：240%*3抛射物\n- 段数补正：1直接命中+1爆炸\n- AOE半径：4米\n- 辅助能力-火元：10%职业增幅 * 60秒\n- 辅助半径：32米\n- 魔力消耗：300点\n- 冷却时间：15秒\n- 持弓时按下设定的技能按键装填，射箭后发动\n- 每升1级增加12%技能倍率，3秒火元持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n连续发射3发注入火焰元素的魔法箭矢。命中目标时造成240%物理远程火焰属性爆破伤害，随后引爆火焰魔法对半径4米的敌人造成等同于直接命中伤害的爆炸伤害。爆裂箭直接命中目标或爆破波及到目标时可给予距离落点32米范围内所有玩家60秒火元效果：职业增幅+10%。\n历史改动：\n- 7.2.8版本：修正技能，现在爆裂箭可以造成直接命中伤害。\n- 7.0.0版本：重制技能，伤害倍率由200%提高至240%，每级倍率由20%降低至12%，冷却时间由14秒延长至15秒，现在命中敌人还会给予范围玩家火元效果。"}, {"name": "五重矢", "url": "https://www.mcmod.cn/item/438190.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438190.png?v=6", "category": "神射手:一转技能:主动技能", "description": "基础信息\n- 职业等级5级后开放学习\n- 技能倍率：100%*5抛射物\n- 段数补正：贯穿抛射物（2次）\n- 魔力消耗：300点\n- 冷却时间：10秒\n- 持弓时按下设定的技能按键装填，射箭后发动\n- 每升1级增加5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n以极快的速度连续发射5发箭矢对远距离目标造成100%物理远程暴风属性穿刺伤害，每支箭矢至多穿透2次，即造成3次伤害。\n学习1转被动弓术精通后，箭矢每次造成伤害都会为玩家叠加1层20秒的箭技效果：每层使最终伤害增加3%。至多叠加5层，学习二转被动蓄力射击后，最大叠加层数增加至10层。\n历史改动：\n- 7.2.8版本：增强技能，现在箭矢可以穿透至多3次，同时穿透的每次伤害也可叠加箭技。\n- 7.1.9版本：增强技能，现在箭矢每次造成伤害都会叠加箭技效果。\n- 7.0.0版本：重制技能，伤害系数由250%降低至100%，每级伤害系数由10%降低至5%，冷却时间由3秒延长至10秒。\n- 6.2.0版本：增强技能，伤害系数由200%提升至250%。"}, {"name": "弓术精通", "url": "https://www.mcmod.cn/item/438185.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438185.png?v=6", "category": "神射手:一转技能:被动技能", "description": "属性提升\n职业等级5级后开放学习。\n提高50%造成的伤害，提高10%最终伤害。\n特殊能力\n获得击退抵抗。\n消耗箭矢时有5%概率不消耗。每次普通攻击或五重矢技能箭矢命中目标时，都会获得1层持续20秒的箭技效果，每层箭技可提升3%最终伤害，最多可获得5层箭技效果，专精分裂射击与五重矢的每支箭矢每次穿透都可进行叠加。\n击杀任意目标会使穿空箭冷却时间缩短1秒。\n学习2转被动蓄力射击后，箭技效果最大层数额外增加5层。\n历史改动：\n- 7.3.7版本：增强技能，现在还会使玩家免疫击退。\n- 7.2.8版本：修正箭技会意外多给1层的问题。\n- 7.1.9版本：现在还会在玩家普攻或五重矢命中时给予箭技效果。\n- 7.0.0版本：移除物理远程攻击力、暴击率与暴击伤害增益，现在可以提升10%最终伤害与50%造成的伤害。射箭时若弓没有附魔无限，则有5%概率不消耗箭矢。"}], "二转技能": [{"name": "蓄力射击", "url": "https://www.mcmod.cn/item/442603.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442603.png?v=12", "category": "神射手:二转技能:被动技能", "description": "基础信息\n职业等级70级解锁2转后开放学习。\n特殊能力\n箭技效果的最大层数增加5层，持续拉弓可以蓄力，并获得弓箭蓄力buff。\n拉弓开始后，每1.5秒增加一层蓄力，获得21秒的蓄力效果，每层蓄力BUFF提高20%造成的伤害与2%最终伤害，最多叠加5层，叠加至5层时，额外给予弓箭手7秒的极限蓄力效果，持有极限蓄力时通过破甲强袭造成的伤害的最大伤害限制将提升300%config最大伤害。\n专精能力\n学习专精极速蓄力后，每层蓄力所需时间由1.5秒缩短至1秒。\n历史改动：\n- 7.1.9版本：增强技能，现在可以增加5层箭技效果上限。\n- 7.1.6版本：增强技能，现在蓄力至5层时会额外给予7秒的极限蓄力效果。\n- 7.0.0版本：重制技能，蓄力效果时长由11秒延长至20秒，每级蓄力效果由100%造成的伤害与20%最终伤害降低至20%造成的伤害与2%最终伤害。\n- 6.2.8版本：增强技能，每层蓄力给予的最终伤害由10%增加至20%。\n- 6.2.1版本：增强技能，蓄力时间由9秒增强至11秒，每层蓄力还会给予10%最终伤害。\n- 5.7.0版本：增强技能，蓄力射击增伤由单次增伤改为接下来的9秒增伤。"}, {"name": "连成一气", "url": "https://www.mcmod.cn/item/442604.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442604.png?v=13", "category": "神射手:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：330%*22抛射物\n- 段数补正：2段\n- 魔力消耗：600点\n- 冷却时间：16秒\n- 持弓时按下设定的技能按键装填，射箭后发动\n- 每升1级增加16.5%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n命中效果\n以迅雷不及掩耳的速度发射22发箭矢，每支箭矢命中敌人时可造成2段330%物理远程暴风属性穿刺伤害。\n额外效果\n此技能可以与其它射箭技能共存，共存时连成一气发射的第一发与最后一发箭矢将会额外追加一次另一个射箭技能，但只有爆裂箭、闪雷矢与破甲强袭可以共存（爆裂箭只会在连成一气的首尾两段各发射1支）。若使用穿空箭后若未使用其它射箭技能，连成一气发射的第一发与最后一发箭矢会额外追加穿空箭。\n专精能力\n学习专精分裂射击后，穿空箭会在水平方向上额外发射2支，额外的穿空箭不会消耗箭矢，穿空箭的总技能倍率将降低至0.6倍；命中非BOSS单位的额外增伤增加0.2倍。\n学习专精轻盈弓法后，通过连成一气释放的穿空箭技能倍率提升0.1倍；命中非BOSS单位的额外增伤增加0.3倍。\n注\n释放连成一气时连成一气将进入CD，而与连成一气共存释放的技能将在连成一气结束后进入CD（穿空箭除外）。\n若在连成一气释放过程中穿插装填了可以与连成一气共存的某个技能（或释放了穿空箭），该技能将只会在连成一气的最后一段被释放一次而后进入CD（穿空箭不会再次进入CD，多次装填将以最后一个装填的技能为准）。\n连成一气与共存的技能只会消耗1次箭矢，同时为连成一气与共存的技能增伤。\n历史改动：\n- 7.2.8版本：修正技能，现在连成一气会受到箭矢增伤效果。\n- 7.1.9版本：增强技能，现在连成一气每支箭矢可造成2段伤害。\n- 7.0.0版本：重制技能，魔力消耗由1200降低至600，伤害倍率由250%提高至330%，每级伤害倍率由30%降低至16.5%，移除升级技能减免魔力消耗，现在无法通过拉弓来重置连成一气释放进度，现在可以与穿空箭、爆裂箭、闪雷矢、破甲强袭共存释放。\n- 6.2.1版本：增强技能，连发速度加快，连发可发射的箭矢数量由9提升至23。\n- 6.1.7版本：削弱技能，最后一击伤害由800%降低为600%。\n- 5.6.9版本：增强技能，伤害倍率由120%提高为250%。\n- 5.5.9版本：削弱技能（bug扶正），伤害倍率由350%调整为120%，魔力消耗由400提升为1200。"}, {"name": "破甲强袭", "url": "https://www.mcmod.cn/item/442605.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442605.png?v=17", "category": "神射手:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：320%*1抛射物\n- 段数补正：11段+贯穿抛射物\n- 负面效果-刺穿：易伤10%+韧性-5%*60秒\n- 魔力消耗：800点\n- 冷却时间：24秒\n- 持弓时按下设定的技能按键装填，射箭后发动\n- 每升1级增加16%技能倍率，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n瞄准目标最为脆弱的部位，蓄力发出一箭，给予其致命性的连续伤害。破甲强袭可以穿透敌人，每tick对目标造成11次320%物理远程黑暗属性波动伤害，并给予目标60秒刺穿效果：提高10%受到的伤害，使拥有韧性的目标额外降低5%韧性。\n当拥有极限蓄力效果时，通过破甲强袭造成的伤害的最大伤害将提升300%的config二转最大伤害。\n历史改动：\n- 7.2.4版本：刺穿效果额外降低目标5%韧性。\n- 7.1.6版本：增强技能，伤害系数由600%降低至320%，每级伤害系数由30%降低至16%，攻击次数由6次增加至11次，现在持有极限蓄力时破甲强袭造成的伤害将会提高300%的config最大伤害。\n- 7.0.0版本：重制技能，魔力消耗由500提升至800，伤害系数由3600%降低至600%，每级伤害系数由60%降低至30%，冷却时间由32秒缩短至24秒，刺穿效果由16秒延长至60秒，易伤效果由30%降低至10%，每tick伤害次数由1次提升至6次。\n- 6.2.8版本：增强技能，突破时的最大伤害上限从2倍提升为4倍，技能冷却时间增加至32秒。\n- 6.1.8版本：削弱技能，伤害系数由4000%降低为3600%\n- 6.1.7版本：削弱技能，伤害系数由4800%降低为4000%。\n- 5.7.0版本：增强技能，伤害倍率由3200%提高为4800%。\n- 5.6.8版本：增强技能，发动技能后将获得5秒的突破效果。\n- 5.5.3版本：削弱技能，冷却时间由24秒提高为30秒。"}, {"name": "风神祝福", "url": "https://www.mcmod.cn/item/442606.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442606.png?v=7", "category": "神射手:二转技能:主动技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 辅助能力-风神祝福+速度II：50%造伤+10%职业增幅 * 60秒\n- 辅助半径：32米\n- 魔力消耗：800点\n- 冷却时间：90秒\n- 持弓时按下设定的技能按键发动\n- 每升1级增加6秒风神祝福与速度的持续时间，最多升为10级\n- 冷却减免倍率：100%\n技能描述\n呼唤风神的神秘力量，给予自身与距离自身32米以内所有玩家60秒的速度Ⅱ与风神祝福效果：造成的伤害+50%，职业增幅+10%。\n历史改动：\n- 7.0.0版本：重置技能，魔力消耗由600提升至800，持续时长由20秒延长至60秒，每级时长由2秒延长至6秒，冷却时间由100秒缩短至90秒，现在可以给予范围玩家状态效果，移除风神祝福的回避、穿透、暴伤、终伤增益，造伤增益由30%提高至50%，现在可以提高10%职业增幅。\n- 6.2.1版本：增强技能，现在会提高10%最终伤害；\n- 6.1.7版本：削弱技能，现在不再无视目标的韧性；\n- 5.7.0版本：增强技能，现在将提高40%暴击伤害，且持续时间内无视目标的韧性减伤。"}, {"name": "暴风箭雨", "url": "https://www.mcmod.cn/item/442607.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442607.png?v=11", "category": "神射手:二转技能:超级技能", "description": "基础信息\n- 职业等级70级解锁2转后开放学习\n- 技能倍率：500%*10段/秒*60秒\n- AOE半径：8米\n- 魔力消耗：1500点\n- 冷却时间：600秒\n- 持弓时按下设定的技能按键装填，射箭后发动\n- 每升1级增加25%技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n发射注魔之箭，命中目标后呼唤魔法风暴，在目标上方召唤巨大的暴风魔法阵，在持续时间内以极快的速度降下无数箭矢，每秒对半径8米内的所有敌人造成10段500%物理远程暴风属性风切伤害。魔法阵至多持续60秒。\n历史改动：\n- 7.0.8版本：修正暴风箭雨仍然会给予致命标记的问题。\n- 7.0.0版本：重置技能，魔力消耗由800增加至1500，伤害系数由1500%降低至500%，升级效果由减少20秒CD改为增加25%暴风箭雨攻击伤害。\n- 6.2.8版本：增强技能，技能持续时间由40秒延长到60秒。\n- 6.2.1版本：增强技能，提高攻击速度。\n- 6.1.8版本：削弱技能，伤害系数由1600%降低为1500%。\n- 6.1.7版本：削弱技能，伤害系数由2000%降低为1600%。\n- 5.7.0版本：增强技能，伤害系数由1600%提高为2000%，并给予目标致命标记效果。\n- 5.6.9版本：增强技能，伤害系数由1300%提高为1600%。\n- 5.5.3版本：削弱技能，小幅减少技能的持续时间。"}], "三转技能": [{"name": "弱点狙击", "url": "https://www.mcmod.cn/item/946620.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946620.png?v=1", "category": "神射手:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高100%造成的伤害，穿空箭技能倍率提高至原先的2倍，独立乘区。\n特殊能力\n在地下城使用瞬身术的冷却时间减半，普通攻击命中目标能获得1层持续30秒的弱点狙击效果：最终伤害提高12%，最多叠加5层。但普通攻击命中方块会损失1层弱点狙击效果，叠加层数会重置持续时间，损失层数不会重置持续时间，专精能力分裂射击带来的额外箭矢无法用于叠加弱点狙击，也不会导致损失弱点狙击。"}, {"name": "风舞射击", "url": "https://www.mcmod.cn/item/946816.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946816.png?v=3", "category": "神射手:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：100%*1200箭\n- 段数补正：3段\n- 真实物理伤害：10点*1200箭*3段\n- 自拐能力-风舞射击：持续期间可以释放风舞射击 * 60秒\n- 魔力消耗：600点\n- 冷却时间：180秒\n- 持弓射箭前按下技能按键，拉满弓时自动射击\n- 每升1级增加5%技能倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n技能效果\n以压倒性的箭矢弹幕给予目标沉重的打击，释放时给予自身持续60秒的风舞射击BUFF，并装填1200次风舞射击点数，每次发射风舞射击箭矢都会消耗1点点数，耗尽后将提前结束风舞射击技能。每发射一次风舞射击都将消耗一次箭矢，可以受到被动弓术精通与附魔无限的箭矢消耗降低的影响。\n风舞射击持续期间持续拉弓可以每秒发射20发箭矢，每发箭矢会对目标造成3段100%物理远程暴风属性震击伤害，沉默期间可以释放。学习2转被动蓄力射击后，持续拉弓发射风舞射击的同时可以进行蓄力。\n持续期间可以正常装填其它射箭技能并正常发射，发射除连成一气外的技能或普通攻击时，会继续发射20支风舞射击箭矢，弓箭蓄力层数至少3层时，会再扇形散射5支风舞射击箭矢。\n风舞射击会在拉弓开始18tick后发射，略慢于常规拉弓的16tick，且不受到世界树真言之弓的拉弓加速影响。\n历史改动：\n- 8.0.0-RC3版本：持续时间由20秒延长至60秒，增加1200次发射次数限制，现在每次射击还会发射20次风舞射击，弓箭蓄力层数至少3层时会再扇形散射5支，风舞射击期间可以进行弓箭蓄力。"}, {"name": "落星神箭", "url": "https://www.mcmod.cn/item/946817.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946817.png?v=2", "category": "神射手:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：2000%*10抛射物\n- AOE半径：5米爆炸\n- 火雨倍率：2000%*10抛射物\n- 火雨段数补正：6段\n- 火雨索敌半径：16米\n- 魔力消耗：600点\n- 冷却时间：100秒\n- 持弓时按下设定的技能按键发动\n- 每升1级增加100%技能倍率，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n技能效果\n呼唤来自天外的陨石群，在准星指向的地面上方召唤多颗陨石，陨石落地后产生爆炸，对半径5米范围内的敌人造成1次2000%物理远程火焰属性烧伤伤害。\n需要准星指向的方块上方连续3格为空气才能释放，陨石群持续落下20秒，每2秒出现1颗，共10颗，陨石每秒下落4~4.8米，出现高度为距离地面20米处，固定坠落19米后爆炸，不会因提前触碰到方块爆炸。\n额外效果\n使用普通攻击命中陨石时，陨石会分裂成火雨，火雨会追踪16米范围内所有敌人，对其造成6段2000%物理远程火焰属性烧伤伤害，并使落星神箭的冷却时间缩短5%。\n普通攻击命中陨石不会触发三转被动弱点狙击的叠层效果，专精分裂射击带来的额外箭矢也能触发陨石。\n历史改动：\n- 8.0.0-RC3版本：移除潜行释放加快下落提高伤害的设定，陨石的受击半径由1米增加至1.5米。"}, {"name": "冰霜箭阵", "url": "https://www.mcmod.cn/item/946819.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946819.png?v=5", "category": "神射手:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：150%\n- 辅助能力-冰霜箭阵：10%终伤+10%职业增幅+30回避值 * 120秒\n- 辅助半径：32米\n- 魔力消耗：600点\n- 冷却时间：240秒\n- 持弓时按下设定的技能按键发动\n- 每升1级增加7.5%技能倍率，1秒冰霜箭阵持续时间，最多升为10级\n- 冷却减免倍率：50%\n技能描述\n技能效果\n呼唤寒冰法阵，给予自身与距离自身32米距离内所有玩家120秒冰霜箭阵：提高10%最终伤害、10%职业增幅、30点回避值。\n额外效果\n持有冰霜箭阵的神射手普通攻击伤害倍率会变为原先的2倍（默认为100%，受专精影响），且射击时会召唤一波冰柱旋风，冰柱会锁定距离神射手16米范围内随机至多4名敌人发动攻击，造成1次150%物理远程寒冰属性冻伤伤害。\n专精分裂射击带来的额外箭矢不会受到冰霜箭阵的倍率加成，除风舞射击外的任意拉弓射击都能触发冰柱旋风。"}, {"name": "利箭风暴", "url": "https://www.mcmod.cn/item/946824.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/946824.png?v=3", "category": "神射手:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：750%*652抛射物（期望）\n- 段数补正：3段\n- 索敌半径：16米\n- 自拐能力-神箭守护：30%受到的伤害减免+100回避值 * 40秒\n- 魔力消耗：1500点\n- 冷却时间：900秒\n- 持弓时按下设定的技能按键发动\n- 每升1级增加37.5%技能倍率，最多升为10级\n- 冷却减免倍率：0%\n技能描述\n技能效果\n召唤12支附魔神箭在周围，每支附魔神箭随机间隔0.5~1秒发射一支巨箭攻击距离自身16米范围内的随机单体目标，巨箭命中时会造成3段750%物理远程光明属性神圣伤害，附魔神箭至多存在40秒。\n额外效果\n释放技能时附魔神箭会无视攻击间隔进行一次齐射，同时会给予释放者持续40秒的神箭守护效果：受到的伤害减免+30%，回避值+100。"}]}}, {"name": "蛊毒师", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "大", "生存": "很弱", "刷本效率": "很高", "缺蓝": "极缺", "对单": "极高", "特殊1": "削穿", "特殊2": "永续塔"}, "tiers": {"固有技能": [{"name": "蛊毒爆", "url": "https://www.mcmod.cn/item/442596.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442596.png?v=6", "category": "蛊毒师:固有技能", "description": "固有技能。\n消耗200魔力，刺激自己来召唤蛊毒力量，消除12米范围内所有敌人身上的蛊毒效果，并造成100%物理远程自然属性毒药伤害。目标拥有的蛊毒效果层数越多，伤害越高，每层蛊毒效果都可以使蛊毒爆的伤害倍率额外提升0.2倍。学习二转被动技能上古碑文后，蛊毒效果对蛊毒爆技能倍率增益将由0.2倍提高至0.5倍。\n即在10级蛊毒爆技能、11层蛊毒效果、学习了上古碑文的情况下，蛊毒爆的技能倍率为 (1+0.05×10)×(1+0.5×11) 共975%技能倍率。\n吹箭筒普通攻击、烈性毒箭、酸性毒每次对敌人造成伤害都可以叠加1层蛊毒效果，持续10秒，最多叠加至11层。\n持吹箭筒时按下武器功能键（默认V键）发动。\n技能冷却时间1秒。\n每升级一次增加5%蛊毒爆攻击伤害，最多升为10级。\n历史改动：\n- 7.2.4版本：增强技能，学习上古碑文后每层蛊毒效果对蛊毒爆的增幅由30%提升至50%。\n- 7.0.0版本：重制技能，蛊毒爆会消耗所有蛊毒效果，伤害倍率由200%降低至100%，现在每层蛊毒效果提升20%蛊毒爆的伤害倍率。\n- 5.5.3版本：强化技能，现在每使用一次减少一层蛊毒效果，而不是消除蛊毒效果。"}, {"name": "中和毒素", "url": "https://www.mcmod.cn/item/744740.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/744740.png", "category": "蛊毒师:固有技能", "description": "固有技能\n消耗 200 魔力，展开魔法阵，并呼唤草之魔法的力量，给予自身持续30秒的中和毒性效果，当持有中和毒性效果时，每次蛊毒爆引爆一个目标后都会提升一层中和毒性效果，当中和毒性效果累积至10层时将消移除所有中和毒性效果，并恢复蛊毒师自身与16米范围内的玩家2000点生命与血性值，并移除失明、饥饿、中毒与剧毒效果。\n持吹箭筒时蹲下按武器功能键（默认V键）发动。\n每升一级增加100点恢复的生命值与血性值，3秒的中和毒性持续时间，最多升为10级。"}], "一转技能": [{"name": "酸性毒", "url": "https://www.mcmod.cn/item/442592.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442592.png?v=6", "category": "蛊毒师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗200魔力，将含有剧毒的小瓶装入吹箭中，并以每秒约6.7次的速度向前方喷洒毒药，对远距离目标造成60%物理远程自然属性酸性伤害，同时对目标施加持续10秒的蛊毒效果、增加蛊毒效果的层数并重置持续时间。另外酸性毒将对目标施加持续60秒的腐败效果，提高20%受到的伤害。被酸性毒将攻击的目标将受到持续12秒的持续伤害，每秒造成15%物理远程自然属性酸性伤害。\n技能冷却时间30秒。\n每升级一次增加3%酸性毒攻击伤害，0.75%DOT伤害，最多升为10级。\n变更历史：\n7.0.0版本：\n重制技能，魔力消耗由500降低至200，伤害倍率由150%降低至60，每级伤害倍率由5%降低至3%，现在命中敌人还会给予蛊毒与持续伤害。\n6.2.0版本：\n增强技能，伤害系数从80%提升至150%。\n5.5.3版本：\n增强技能，技能造成的伤害的次数大幅提升。"}, {"name": "雾疗", "url": "https://www.mcmod.cn/item/442593.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442593.png?v=3", "category": "蛊毒师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗200魔力与治疗粉，运用药草学的知识，燃起持续30秒的拥有治疗效果的烟雾，在身边制造雾疗区域，雾疗每秒可医疗4米范围内所有玩家200点生命值，并给予他们持续60秒的草之祝福效果，提高50%造成的伤害，提高10%职业增幅，只能同时拥有一个雾疗区域。\n技能冷却时间60秒。\n每升级一次增加10点治疗量，6秒草之祝福效果时长，最多升为10级。\n历史改动：\n7.0.0版本：\n重制技能，消耗魔力由300降低至200，持续时间由40秒缩短至30秒，冷却时间由80秒延长至90秒，升级效果由增加5秒持续时间改为增加10点治疗量与6秒草之祝福效果时长。\n6.1.4版本：\n现在雾疗提供的草之祝福效果可以提高玩家25%掉宝率。"}, {"name": "烈性毒箭", "url": "https://www.mcmod.cn/item/442594.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442594.png?v=5", "category": "蛊毒师:一转技能:主动技能", "description": "一转技能。\n最低学习等级5等。\n消耗 200 魔力，将烈性毒药装入箭矢中，向前方发射4波散状飞箭，对目标造成65%物理远程自然属性植物伤害，每次直接命中敌人都能对目标施加持续10秒的蛊毒效果、增加蛊毒效果的层数并重置持续时间。飞散箭命中目标后将会引燃毒药，造成等同于直接命中伤害的半径2米的范围伤害。\n技能冷却时间10秒。\n每升级一次增加3.25%烈性毒箭攻击伤害，最多升为10级。\n命中敌人时若敌人未持有蛊毒效果，则给予2层蛊毒效果。\n历史改动：\n7.0.6版本：\n增强技能，伤害倍率由50%提升至65%。\n7.0.0版本：\n重制技能，名称由飞散箭改为烈性毒箭，调整技能图标，魔力消耗由300降低至200，伤害倍率由250%降低至50%，每级伤害倍率由10%降低至3.25%，现在命中敌人还会造成范围伤害。\n6.2.0版本：\n增强技能，伤害倍率由200%提升至250%。\n5.5.3版本：\n增强技能，攻击段数提高。"}, {"name": "致命剧毒", "url": "https://www.mcmod.cn/item/442575.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442575.png?v=4", "category": "蛊毒师:一转技能:被动技能", "description": "一转技能。\n最低学习等级5等。\n将缠绕雨林中巨蛇的毒素涂抹在吹箭上，给予敌人致命的打击，提高10%最终伤害，提高50%造成的伤害，获得抵抗击退效果。普通攻击命中目标时，可给予目标持续10秒的缓速Ⅱ效果，并对目标造成持续8秒的50%物理远程自然属性苦痛持续伤害。\n历史改动：\n- 7.3.7版本：增强技能，现在还会使玩家免疫击退。\n- 7.0.0版本：重制技能，效果由提高物理远程伤害10点、提高魔力最大值300点改为提高10%最终伤害、50%造成的伤害，现在普攻命中可给予8秒的50%DOT伤害。"}], "二转技能": [{"name": "上古碑文", "url": "https://www.mcmod.cn/item/443103.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443103.png?v=5", "category": "蛊毒师:二转技能:被动技能", "description": "通过研读远古的碑文来增强自己的能力，提高10%最终伤害，提高100%造成的伤害，强化蛊毒爆，增加30%每层蛊毒效果的伤害，另外普通攻击命中目标时，有15%的概率立即重置烈性毒箭与酸性毒的冷却时间，目标持有的每个状态效果将提升20%造成的伤害。\n历史改动：\n- 7.2.4版本：每层蛊毒爆伤害增加由10%提高至30%，重置技能概,率由10%提高至15%，新增目标持有的每个状态效果将提升20%造成伤害的效果。\n- 7.0.0版本：重制技能，移除攻击目标持有效果数量越多伤害越高的特性，现在上古碑文可以提高10%最终伤害、100%造成的伤害和10%蛊毒爆伤害倍率。\n- 5.5.3版本：增强技能，现在攻击时，目标持有的状态越多，造成越大的伤害，每个状态提高16%伤害。"}, {"name": "先祖图腾", "url": "https://www.mcmod.cn/item/443104.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443104.png?v=9", "category": "蛊毒师:二转技能:主动技能", "description": "消耗600魔力，呼唤原始力量，在身边召唤先祖图腾，并给予蛊毒师自身与附近10米范围内的玩家持续60秒的先祖呐喊效果，提高100%造成的伤害，提高10%职业增幅。先祖图腾每秒发射一次魔力脉冲攻击附近单体目标，造成75%物理远程光明属性能量伤害，只能同时拥有一个先祖图腾。\n潜行时释放该技能，会将场上属于自己的先祖图腾移动到准星指向的方块上方，移动图腾不受冷却时间与魔力值的限制。\n技能冷却时间10秒。\n每升级一次增加3.75%图腾攻击伤害，最多升为10级。\n学习专精先祖意志后，冷却时间缩短至5秒。\n历史改动：\n- 8.0.0-RC1版本：现在潜行释放该技能可以移动图腾位置。\n- 7.0.0版本：重制技能，更名为先祖图腾，魔力消耗由200提高至600，伤害倍率由200降低至75%，每级伤害倍率由10%降低至3.75%，现在最多只能同时存在1个图腾。\n- 6.1.4版本：增强技能，图腾持续时间由60秒提升至90秒，放置数量上限由5个提升至10个。\n- 5.6.2版本：削弱技能，技能伤害系数由1000%改为200%。\n- 5.5.3版本：增强技能，技能现在可以给予目标月光侵蚀效果。"}, {"name": "沼气毒火", "url": "https://www.mcmod.cn/item/745401.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/745401.png?v=6", "category": "蛊毒师:二转技能:主动技能", "description": "消耗600魔力，往吹箭中注入火之魔法，向前方扇形范围内喷射猛烈火焰，对目标造成50%物理远程火焰属性烧伤伤害并施加持续10秒的持续伤害：每秒造成沼气毒火75%倍率的物理远程火焰属性烧伤伤害。赋予目标60秒的毒沼效果：使目标受到的伤害增加10%，并且降低5%韧性防御。若施放沼气毒火时身边存在先祖图腾，先祖图腾将发射20枚火焰弹攻击附近单体目标，每枚火焰弹可造成 [先祖图腾总技能倍率/2] 技能倍率的物理远程火焰属性烧伤伤害。\n每升级一次增加2.5%沼气毒火攻击伤害，最多升为10级。\n当学习专精毁灭图腾后，释放沼气毒火使先祖图腾发射的火焰弹数量提升至25枚。\n历史改动：\n- 7.2.4版本：增强技能，伤害倍率由90%降低至50%，每级伤害倍率由4.5%降低至2.5%，火焰弹数量由10增加至20，现在技能将额外赋予目标毒沼效果，使目标受到的伤害增加10%，并且降低5%韧性防御。"}, {"name": "寒冰毒箭", "url": "https://www.mcmod.cn/item/745402.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/745402.png?v=4", "category": "蛊毒师:二转技能:主动技能", "description": "消耗800魔力，往吹箭中注入冰之魔法，向前方发射带有寒气的箭矢，对命中目标造成120%物理远程寒冰属性冻伤伤害，并给予目标持续60秒的缓慢效果。同时对目标施加持续12秒的持续伤害，每秒造成寒冰毒箭25%倍率的物理远程寒冰属性冻伤伤害。若寒冰箭矢命中目标时身边存在先祖图腾，每只命中的寒冰箭矢都将使先祖图腾召唤3道冰锥攻击该目标，造成 [先祖图腾总技能倍率*1.2] 技能倍率的物理远程寒冰属性冻伤伤害。\n每升级一次增加6%寒冰毒箭攻击伤害，最多升为10级。\n当学习专精毁灭图腾后，寒冰毒箭命中目标使先祖图腾召唤的冰锥数量提升至6道。\n历史改动：\n- 7.2.4版本：增强技能，伤害倍率由75%提高至120%，每级伤害倍率由3.75%提高至6%，专精毁灭图腾的冰锥数量由4提升至6。"}, {"name": "千针万确", "url": "https://www.mcmod.cn/item/443107.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443107.png?v=9", "category": "蛊毒师:二转技能:超级技能", "description": "超级技能。\n消耗1500魔力，发射一支箭矢，箭矢命中方块或实体后呼唤古代力量，以强大的魔咒召唤先灵图腾在目标地点，先灵图腾将以极快的速度降下千万针雨，对圆形半径8米范围，高度0.11米圆柱体内的敌人每秒造成5次600%物理远程暴风属性毒药伤害，同时对目标施加持续100秒的毒杀效果，提高50%受到的伤害，并降低10点穿透防御。先灵图腾最多存在40秒。\n技能冷却时间200秒。\n每升级一次增加30%先灵图腾攻击伤害，最多升为10级。\n历史改动：\n- 7.2.4版本：增强技能，冷却时间由600秒缩短至200秒，每秒4段增加至5段，持续时间由100秒缩短至40秒，毒杀效果增加30%受到伤害提高至增加50%受到伤害，并额外降低10点穿透防御。\n- 7.0.0版本：重制技能，消耗魔力由800提高至1500，图腾攻击力由900%降低至600%，图腾持续时间由90秒缩短至50秒。\n- 6.1.4版本：增强技能，图腾持续时间由60秒提升至90秒。\n- 5.6.2版本：削弱技能，技能伤害系数由1400%改为900%。\n- 5.4.9版本：重新调整技能的伤害值."}], "三转技能": [{"name": "巫毒之难", "url": "https://www.mcmod.cn/item/948435.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948435.png", "category": "蛊毒师:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高100%造成的伤害，提高10%最终伤害，提高10%DOT倍率，提高20%DOT间隔速度。\n特殊能力\n基础信息\n- 技能倍率：420%\n能力描述\n提升10层蛊毒效果的最大层数，并使沼气毒火也能给予目标蛊毒效果，以任何方法对目标施加蛊毒效果时，达到蛊毒效果最大层数（20层）或已达到最大层数后继续施加，都会立刻对目标造成一段420%物理远程原水属性吸收的额外伤害。\n获得职业资源诅毒值，每当叠加蛊毒触发一次额外伤害，都会累积1点诅毒值，每当施展蛊毒爆时会消耗1点诅毒值，使蛊毒爆技能倍率提升至原先的2倍，该效果为独立乘区，与蛊毒BUFF层数对蛊毒爆技能倍率增幅乘算，最多可拥有30点诅毒值。"}, {"name": "腐蚀酸雨", "url": "https://www.mcmod.cn/item/948437.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948437.png?v=1", "category": "蛊毒师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：300%*10段/秒*5秒~7.5秒\n- 真实物理伤害：10点*10段/秒*5秒~7.5秒\n- AOE半径：3米~4.5米\n- DOT倍率：150%*10段\n- 负面效果-腐蚀酸雨：穿透防御-10% * 65秒~67.5秒\n- 负面半径：3米~4.5\n- 魔力消耗：200点\n- 冷却时间：12秒\n- 持吹箭筒时按下设定的技能按键发动\n- 每升1级增加15%技能倍率\n技能描述\n命中效果\n将从极恶之地提取的酸雨注入图腾中，使先祖图腾移动到准星指向的方块上，散发毒云并降下酸雨攻击半径3米的范围内所有目标，在5秒内造成50段300%物理远程自然属性酸性伤害，并时给予目标60秒腐蚀酸雨效果：降低10%穿透防御（百分比穿透防御削减的计算在固定值穿透防御削减之后）。同时对目标造成10段持续伤害：每秒造成150%物理远程黑暗属性混乱伤害，持续10次。如果附近未拥有先祖图腾，则技能施放失败，不会进入冷却时间，潜行时施放时，会消耗10点诅毒值，腐蚀酸雨将提升50%的持续时间与范围。"}, {"name": "荆棘螺旋", "url": "https://www.mcmod.cn/item/948439.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948439.png", "category": "蛊毒师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：950%*5抛射物\n- 段数补正：贯穿抛射物\n- 负面效果：蛊毒*10秒*最大10层\n- 自拐能力-荆棘螺旋：普攻额外发射1个荆棘螺旋*30秒\n- 魔力消耗：600点\n- 冷却时间：50秒\n- 持吹箭筒时按下设定的技能按键发动\n- 每升1级增加47.5%技能倍率，1秒荆棘螺旋持续时间\n技能描述\n命中效果\n对吹箭施加巫毒咒法，召唤强大的荆棘螺旋袭击目标，立即发射5个荆棘螺旋，同时给予自身30秒的荆棘螺旋效果：普攻发射吹箭时，将额外发射1个荆棘螺旋。荆棘螺旋会往前方飞行，对目标造成950%物理远程自然属性植物伤害，并给予目标1层蛊毒效果。\n荆棘螺旋可以穿透实体，但无法穿透方块，飞行一段距离后会原路折返，并在回到发射位置前再次折返，若想3段飞行均命中，则需要在距离目标至少6米处发射荆棘螺旋。\n额外效果\n荆棘螺旋命中诅咒草人或灵体幻影时，总技能倍率会提高至原先的2倍。"}, {"name": "诅咒草人", "url": "https://www.mcmod.cn/item/948441.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948441.png?v=3", "category": "蛊毒师:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：10% * 51秒（常规）\n- 索敌半径：16米\n- 辅助能力-巫毒咒语：5%终伤+10%职业增幅 *111秒（常规）\n- 辅助半径：32米\n- 魔力消耗：600点\n- 冷却时间：130秒\n- 持吹箭筒时按下设定的技能按键发动\n- 该技能升级没有效果\n技能描述\n技能效果\n将灵魂注入稻草人中，并以巫毒咒术诅咒准星指向的目标，在自身位置召唤目标的诅咒草人，诅咒草人每秒会给予自身与附近32米范围内所有玩家60秒巫毒咒语效果：职业增幅+10%，最终伤害+5%。诅咒草人不会移动、施放技能或攻击，拥有20点生命值，并每秒流失2%生命值。诅咒草人受到攻击时，会将伤害按比例传递给目标，目标死亡后，诅咒草人会立即消失。诅咒草人必须与目标存在相同维度，并且需要目标距离诅咒草人不超过16米，才能对目标造成伤害。召唤者受到伤害时，会增加50%受到的伤害减免，并使诅咒草人损失2%生命值。\n诅咒草人至多存在60秒，但由于每秒流失2%生命值，没有干预与替召唤者承受伤害的情况下只能存活51秒。由于诅咒草人属于怪物，无法受到治愈之光、秘银竖琴、雾疗等魔法金属能力治疗，只能通过喷溅型治疗药水等原版或其它模组方式。\n对于魔法金属类型的伤害，诅咒草人会将其降低90%后传递给目标，独立乘区；对于非魔法金属类型的伤害，诅咒草人会将其基础攻击力降低90%后传递给目标。\n由于诅咒草人不会阻挡抛射物，因此部分箭矢、标枪即使不具备穿透能力也能穿透造成多段伤害，但部分命中效果无法触发，如命中后引爆。大部分抛射物由于是命中后自行消散，不会触发该特性。\n由于是传递基础伤害，因此为诅咒草人施加受到的伤害增加类效果不会增幅伤害。\n特定情况下召唤索敌距离会比16米更远，因此可能出现召唤成功但无法打出伤害的距离，释放时需注意避免该情况。\n额外效果\n荆棘螺旋命中诅咒草人时，将会造成两倍的伤害。\n你知道吗\n诅咒草人每秒流失2%最大生命，却能存活51秒，是因为计算机浮点失精特性让诅咒草人在50秒后还能剩余约0.00001013279点生命值。"}, {"name": "亵渎爆破", "url": "https://www.mcmod.cn/item/948444.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948444.png", "category": "蛊毒师:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 酸雨倍率：1500%*303段（期望）\n- 酸雨半径：12米\n- 毒囊倍率：1500%*26段*80个（理论对单最多）\n- 毒囊半径：3米\n- 负面效果-剧毒酸雨：易伤30%+穿透防御-10%+韧性-10% * 100秒\n- 负面半径：12米\n- 自拐能力-亵渎爆破：持续时间内释放蛊毒爆可以触发亵渎爆破 * 40秒\n- 魔力消耗：1500点\n- 冷却时间：900秒\n- 持吹箭筒时按下设定的技能按键发动\n- 每升1级增加75%技能倍率\n技能描述\n技能效果\n抛出剧毒孢子并成长茁壮，使毒云成为无尽的恶梦，给予自身40秒亵渎爆破效果，持续时间内，会在蛊毒爆命中的每个目标位置都产生一个毒囊，毒囊会在3秒后成长茁壮，并且引发爆炸，对半径3米内的所有敌人造成1500%物理远程自然属性死亡伤害，并对爆炸范围内所有目标叠加一次10秒的蛊毒效果，同时召唤毒云，毒云会在5秒内持续对半径3米范围内所有目标造成25段等同于爆炸伤害的伤害。当累积产生12个毒囊后，会召唤持续40秒的剧毒酸雨，每秒对半径12米范围内所有目标造成5段等同于爆炸伤害的伤害，并在酸雨出现后2.6秒开始召唤雷霆攻击附近随机目标，雷霆约每0.98秒触发一次，每道造成约1.4次或4次等同于爆炸伤害的伤害。此外酸雨还会给予目标60秒的剧毒酸雨效果：受到的伤害增加+30%，穿透防御-10%、韧性-10%。\n酸雨会在产生第12个毒囊后在第12个毒囊上方出现，生成酸雨不会清除生成毒囊的能力。"}]}}, {"name": "追猎者", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "https://www.mcmod.cn/post/4340.html", "attributes": {"操作量": "大", "生存": "很强", "刷本效率": "很高", "缺蓝": "不缺", "对单": "很高", "特殊1": "削穿", "特殊2": "无视沉默"}, "tiers": {"固有技能": [{"name": "捕捉网", "url": "https://www.mcmod.cn/item/643427.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643427.png?v=3", "category": "追猎者:固有技能", "description": "固有技能。\n消耗200魔力，抛出一个捕捉网，命中敌人后造成 120% 物理远程暴风属性束缚伤害，并对目标施加缓速与麻痹效果，持续25秒。\n持标枪时按下武器功能(默认V)发动。\n技能冷却时间6秒。\n每升一级提升6%伤害，最多升为10级。\n历史改动：\n7.0.7版本\n增强技能，技能倍率由100%提高至120%，升级倍率由5%提高至6%，缓速与麻痹持续时间由20秒缩短至25秒。\n7.0.0版本：\n重制技能，魔力消耗由300降低至200，伤害倍率由300%降低至100%，每级伤害倍率由10%降低至5%，冷却时间由8秒缩短至6秒，现在命中还会给予麻痹效果，debuff持续时间由4秒延长至20秒。"}, {"name": "荒野备战", "url": "https://www.mcmod.cn/item/643428.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643428.png?v=4", "category": "追猎者:固有技能", "description": "固有技能。\n有备而无患。消耗200点魔力值，立即补充所有追猎者标枪备弹，同时医疗追猎者自身400点生命值，并且恢复全部魔力值。\n蹲下按下武器功能（默认V）发动。\n技能冷却时间10秒。\n每升一级增加20点恢复的生命值，最多升为10级。\n历史改动：\n7.1.6版本：\n增强技能，冷却时间由12秒缩短至10秒。\n7.1.4版本：\n增强技能，冷却时间由14秒缩短至12秒。\n7.0.7版本：\n增强技能，冷却时间由16秒缩短至14秒。\n7.0.0版本：\n重制技能，现在发动需要至少拥有200点魔力值，生命值恢复量由20%最大生命值调整为400点生命值，魔力值恢复量由20%最大魔力值调整为100%最大魔力值，升级效果由增加5%恢复的最大生命值、魔力值调整为增加20点恢复的生命值。"}], "一转技能": [{"name": "银枪", "url": "https://www.mcmod.cn/item/643429.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643429.png?v=10", "category": "追猎者:一转技能:主动技能", "description": "一转技能。\n最低学习等级 5 等。\n消耗 200 魔力，将拥有奇效的银镀制在标枪上，向前方发射银枪攻击目标，对远距离目标造成5段150%物理远程光明属性纯净伤害，并对目标施加持续60秒的狩猎标记效果，提高10%受到的伤害，若发射时追猎者持有魔化猎手状态，则银枪的伤害段数会增加至8段，技能基础倍率提高30%，与原技能倍率加算。银枪命中生物或方块时，将会补充追猎者自身最大生命值10%的血性值。持标枪按下技能键时装填，随后投掷标枪发动。\n在拥有魔化猎手效果时，银枪对生命值低于65%的目标技能基础倍率增加70%，对生命值低于35%的目标技能基础倍率再提高70%，均与原技能倍率加算。\n银枪每6秒准备1个，最多可持有3个。\n每升一级提升7.5%伤害，最多升为10级。\n你知道吗：银枪是唯一一个不“锁面板”的抛射物。\n历史改动：\n- 7.2.8版本：增强技能，拥有魔化猎手时，银枪对生命值低于65%的目标将提高70%的技能伤害，对生命值低于35%的目标会再提高70%技能伤害。\n- 7.1.8版本：修正技能，修正持有魔化猎手时银枪段数与伤害不增加的问题，现在持有魔化猎手时额外增加3段银枪攻击段数与30%技能基础倍率。\n- 7.1.6版本：增强技能，基础伤害段数由3段提高至5段，伤害倍率由250%降低至150%，升级倍率由12.5%降低至7.5%，移除持有魔化猎手时额外增加1段攻击的特性。\n- 7.1.4版本：增强技能，基础伤害段数由2段提高至3段，伤害倍率由375%降低至250%，升级倍率由18.75%降低至12.5%。\n- 7.0.8版本：增强技能，基础伤害段数由1段提高至2段，现在持有魔化猎手时还会额外增加1段伤害。\n- 7.0.7版本：增强技能，伤害倍率由340%提高至375%，升级倍率由17%提高至18.75%。\n- 7.0.6版本：增强技能，伤害倍率由325%提高至340%，升级倍率由16.25%提高至17%。\n- 7.0.0版本：重制技能，伤害倍率由250%提高至325%，冷却时间由8秒缩短至6秒。"}, {"name": "爆裂标枪", "url": "https://www.mcmod.cn/item/643430.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643430.png?v=8", "category": "追猎者:一转技能:主动技能", "description": "一转技能。\n最低学习等级 5 等。\n消耗 200 魔力，呼唤火之咒法，对标枪施展火之魔咒，对直接命中的目标造成3段250%物理远程火焰属性爆破伤害，并在命中后引燃火之魔法，造成3段半径8米、伤害倍率等同于直接命中伤害的爆炸伤害，爆炸伤害对非BOSS生物的技能倍率会提高至总倍率的1.3倍。当持有魔化猎手时，技能基础倍率+65%，与原技能倍率加算，与非BOSS增伤乘算。当持有5级及以上的猎者追踪时，爆炸半径增加3米，且直接命中与爆炸伤害段数均增加1段。爆裂标枪爆炸后，将给予距离爆裂标枪32米范围内的玩家破片追踪效果，提高10%职业增幅，持标枪发射后发动。\n爆裂标枪每8秒准备1个，最多可持有2个。\n每升一级提升12.5%伤害，最多升为10级。\n历史改动：\n- 7.4.4版本：修正技能，现在爆炸的伤害段数继承直接命中的伤害段数。\n- 7.4.2版本：增强技能，伤害倍率由220%提高至250%，每级伤害倍率由11%提高至12.5%，半径由6扩大至8，持有5层猎者追踪时半径额外扩大3米。\n- 7.1.8版本：修正技能，修正持有猎者追踪时技能倍率不增加的问题。\n- 7.1.6版本：增强技能，伤害倍率由330%降低至220%，每级伤害倍率由16.5%降低至11%，伤害半径由4米增加至6米，伤害段数由2段增加至3段。\n- 7.0.8版本：增强技能，直接命中基础伤害段数由1段增加至2段，持有5级及以上魔化猎手时，额外增加1段直接命中伤害。\n- 7.0.7版本：增强技能，伤害倍率由300%提高至330%，每级伤害倍率由15%提高至16.5%。\n- 7.0.0版本：重制技能，魔力消耗由400降低至200，伤害倍率由200%提高至300%，每级伤害倍率由20%降低至15%，冷却时间由10秒缩短至8秒。"}, {"name": "草药专精", "url": "https://www.mcmod.cn/item/744545.html", "icon": "https://i.mcmod.cn/item/icon/128x128/74/744545.png?v=3", "category": "追猎者:一转技能:主动技能", "description": "一转技能。\n最低学习等级 5 等。\n消耗 200 魔力，运用对荒野植物的知识来寻找能够治疗自己的药草。给予自身持续60秒的草药专精效果，在持续时间内每采集一个狩猎点都会使草药专精的效果叠加一层。每层草药专精都会使追猎者每秒恢复100点生命。当草药专精叠至4层时，银枪与爆裂标枪立即补充一发。当草药专精叠至7层时，将补充所有魔力值，并且给予附近32米范围内的玩家持续60秒的草药精华效果，提高10%职业增幅。\n拥有草药专精效果时使用此技能将会重置草药专精的层数，草药专精最高叠加至10层，10层后采集狩猎点只会重置草药专精的持续时间。\n每升一级增加6秒草药专精与草药精华的持续时间，增加5点草药专精每层的基础恢复生命值。\n学习专精活性草药后，当草药专精叠加至7层时，将会移除草药专精效果，并给予3000点临时生命，最多持续300秒，同时银枪与爆裂标枪额外补充一发。\n历史改动：\n- 7.4.2版本：草药专精与草药精华的持续时间由30秒延长至60秒，每级持续时间由3秒延长至6秒。"}, {"name": "猎者追踪", "url": "https://www.mcmod.cn/item/643432.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643432.png?v=8", "category": "追猎者:一转技能:被动技能", "description": "一转技能。\n最低学习等级 5 等。\n透过长久的狩猎经验，领悟猎物的行动状态，获得抵抗击退效果，持标枪时每10秒周围会生成4个狩猎点，当碰触到狩猎点时补充3点备弹并给予自身5秒的速度与126秒的猎者追踪效果，每层猎者追踪提高60%造成的伤害与6%最终伤害，最高5层，猎者追踪叠加5层时，爆裂标枪的直接命中伤害额外增加1段，爆炸半径增加3米。每当触发狩猎点或所有狩猎点皆未在10秒内被触发时，现有狩猎点全数移除并立即重新生成狩猎点。\n触发狩猎点虽然会重置所有狩猎点数量与位置，但不会重置自然生成狩猎点的时间，因此部分时间玩家可以看到8个狩猎点，狩猎点生成时至少距离玩家4米，至多距离玩家15米。\n当学习专精高速追踪后，触发狩猎点给予的速度效果由5秒提升至10秒，效果由1级提升至2级。\n历史改动：\n- 7.4.2版本：增强技能，狩猎点生成数量由3个增加至4个，持有5层猎者追踪时爆裂标枪的爆炸半径增加3米。\n- 7.3.7版本：增强技能，现在还会使玩家免疫击退。\n- 7.0.8版本：增强技能，现在持有5层猎者追踪将会使爆裂标枪额外造成1段直接命中伤害。\n- 7.0.7版本：增强技能，猎者追踪BUFF的造成的伤害与最终伤害增益由50%/5%提高至60%/6%。\n- 7.0.0版本：重制技能，触发狩猎点后补充的备弹由2点提高至3点，移除触发狩猎点给予的强击与猎手效果，现在触发狩猎点还会给予猎者追踪效果。"}], "二转技能": [{"name": "魔化猎手", "url": "https://www.mcmod.cn/item/643433.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643433.png?v=8", "category": "追猎者:二转技能:被动技能", "description": "持续不断的钻研狩猎知识，并且以威力强大的魔法强化自身.\n狩猎点生成数量增加1个，每次踩到狩猎点时，补充的备弹数量增加2点，并且透过狩猎点补充的备弹数量最多可获得20点。\n强化猎者追踪技能，BUFF最高层数提高2等，当碰触到狩猎点时给予自身魔化猎手效果，提高100%造成的伤害，降低15%受到的伤害，且拥有魔化猎手效果时，银枪的攻击段数增加3段、提升30%基础技能倍率，爆裂标枪提升65%基础技能倍率。\n每次发射标枪时有33%概率不消耗备弹，发动螺旋标枪、荆棘飞枪、银枪、爆裂标枪时可无视沉默效果发动。\n强化银枪技能，银枪对生命值低于65%的目标将提高70%的技能伤害，对生命值低于35%的目标会再提高70%技能伤害。\n当学习专精双重魔化后，触发狩猎点给予的魔化猎手效果由1级提升至2级，即造成的伤害增加由100%提高至140%。\n历史改动：\n- 7.2.8版本：现在会使银枪在目标低生命值时增加技能倍率。\n- 7.2.5版本：魔化猎手每级提供的伤害加成由20%增加至40%。\n- 7.2.4版本：移除消耗魔化猎手效果抵御非混沌伤害的能力，改为拥有该效果时，受到伤害减少15%。\n- 7.1.6版本：现在使银枪的攻击段数+3，技能倍率+30%，爆裂标枪技能倍率+65%。\n- 7.1.4版本：增强技能，魔化猎手BUFF时间由10秒延长至60秒，增加效果：现在可以使猎者追踪触碰狩猎点补充备弹+2，触碰狩猎点补充的备弹上限+10，猎者追踪最大等级+2。\n- 7.0.8版本：增强技能，现在持有魔化猎手时还会使银枪增加1段攻击段数。\n- 7.0.0版本：重制技能，由强化猎手效果改为给予魔化猎手效果。"}, {"name": "螺旋标枪", "url": "https://www.mcmod.cn/item/643434.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643434.png?v=7", "category": "追猎者:二转技能:主动技能", "description": "消耗 600 魔力，将强大的风之魔咒注入标枪中，向前方发射螺旋标枪攻击目标，螺旋标枪能够穿透复数目标并对目标造成5段200%物理远程魔法属性波动伤害，并对目标施加持续60秒的螺旋穿刺效果，提高20%受到的伤害，并降低10点穿透防御，持标枪发射后发动。\n螺旋标枪每8秒准备1个，最多可持有3个。\n每升一级提升10%伤害，最多升为10级。\n历史改动：\n- 7.2.5版本：增强技能，段数由4段增加至5段，伤害倍率由100%回调至200%。\n- 7.2.4版本：增强技能，段数从1段增加至4段，伤害倍率由200%降低至100%，螺旋穿刺效果额外降低目标10点穿透防御。\n- 7.0.8版本：增强技能，伤害倍率由180%提高至200%，每级伤害倍率由9%提高至10%。\n- 7.0.7版本：增强技能，伤害倍率由165%提高至180%，每级伤害倍率由8.25%提高至9%。\n- 7.0.6版本：增强技能，伤害倍率由150%提高至165%，每级伤害倍率由7.5%提高至8.25%。\n- 7.0.0版本：重制技能，魔力消耗由400提高至600，伤害倍率由3300%降低至150%，每级伤害倍率由20%降低至7.5%，"}, {"name": "荆棘飞枪", "url": "https://www.mcmod.cn/item/643435.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643435.png?v=6", "category": "追猎者:二转技能:主动技能", "description": "消耗 600 魔力，将缠绕雨林中的剧毒藤蔓注入标枪中，向前方发射荆棘飞枪攻击目标，对直接命中的目标造成130%物理远程火焰属性植物伤害，命中后在命中点同平面的3米范围内随机召唤4道荆棘，每道荆棘将在4.25秒的持续时间内至多攻击球形半径2米内的目标10次，每次攻击都会造成等同于直接命中伤害的范围伤害，每道荆棘每次命中敌人都将医疗追猎者自身100点生命值，荆棘丛不会击退怪物。持标枪发射后发动。\n荆棘飞枪每16秒准备1个，最多可持有2个。\n每升一级提升3.25%伤害，5点荆棘命中时的治疗量，最多升为10级。\n历史改动：\n- 7.2.5版本：增强技能，伤害倍率由65%提高至130%，荆棘数量由3个增加至4个。\n- 7.2.4版本：取消荆棘丛的击退效果。\n- 7.1.4版本：增强技能，伤害倍率由55%提高至65%，每级伤害倍率由2.75%提高至3.25%。\n- 7.0.7版本：增强技能，伤害倍率由50%提高至55%，每级伤害倍率由2.5%提高至2.75%。\n- 7.0.0版本：重制技能，魔力消耗由500提高至600，伤害倍率由600%降低至50%，每级伤害倍率由30%降低至2.5%。"}, {"name": "战斗组装", "url": "https://www.mcmod.cn/item/643436.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643436.png?v=4", "category": "追猎者:二转技能:主动技能", "description": "消耗 800 魔力，使用非常快的速度原地建造自动弩炮塔，自动弩炮塔将以每秒2次的速度自动攻击16米范围内的目标，造成 150% 物理远程暴风属性穿刺伤害，持续60秒。只能同时拥有1个自动弩炮塔。\n技能冷却时间60秒。\n每升一级提升3.75%伤害，最多升为10级。\n学习专精强化组装后，攻击间隔将由10tick缩短至7tick，即攻击速度由每秒2次提升至每秒2.8次。\n历史改动：\n- 7.2.5版本：增强技能，伤害倍率由75%提高至150%。\n- 7.1.4版本：增强技能，伤害倍率由50%提高至75%，每级伤害倍率由2.5%提高至3.75%。\n- 7.0.0版本：重制技能，魔力消耗由600提高至800，伤害倍率由600%降低至50%，每级伤害倍率由20%降低至2.5%，持续时间由90秒缩短至60秒，移除大型弩炮机塔。"}, {"name": "断界神枪", "url": "https://www.mcmod.cn/item/643505.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643505.png?v=7", "category": "追猎者:二转技能:超级技能", "description": "消耗 1500 魔力，超级技能，透过至高无上的狩猎技巧，召唤具有毁灭力量的断界神枪，向前方发射注魔标枪攻击目标，并在命中后召唤巨大的标枪将从天空中坠落，造成范围伤害，断界神枪将持续吸引16米范围内的目标，并对5米范围内的目标每秒造成4次450%物理远程暴风属性引力伤害，并施加60秒的缓慢II，断界神枪持续40秒。持标枪发射后发动。在释放技能后，若20秒内没有释放标枪，则断界神枪自动取消并返还冷却时间。\n断界神枪每300秒准备1个，最多可持有2个。\n每升一级提升11%伤害，最多升为10级。\n历史改动：\n- 7.2.8版本：新增效果：施放技能后，20秒内若未发射标枪，将会自动取消施放，并且返回冷却时间。\n- 7.2.5版本：增强技能，技能倍率由225%增加至450%。\n- 7.2.4版本：增强技能，断界神枪的准备时间由500秒缩短至300秒。\n- 7.1.4版本：增强技能，断界神枪的准备时间由600秒缩短至500秒。\n- 7.0.0版本：重制技能，魔力消耗由800提高至1500，伤害倍率由2000%降低至225%，升级效果由减少20秒冷却改为增加11%每级伤害倍率，现在可以同时持有2个断界神枪。"}], "三转技能": [{"name": "狩猎契约", "url": "https://www.mcmod.cn/item/948452.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948452.png?v=2", "category": "追猎者:三转技能:被动技能", "description": "属性提升\n职业等级130级解锁3转后开放学习。\n提高100%造成的伤害，提高20%最终伤害，提高10点备弹上限。\n特殊能力\n基础信息\n- 技能倍率：367.5%*5段/秒*5秒\n- AOE半径：2米\n- 负面效果：吸引*5秒\n- 负面半径：6米\n能力描述\n仔细专研投掷技巧，发挥标枪的真正力量，每次采集狩猎点时，会获得1点镰鼬点数，最多可累计10点。任意普攻或技能标枪命中方块或实体时，会消耗3点镰鼬点数并召唤镰鼬旋风，持续吸引半径6米范围内所有敌人，并对半径2米范围内所有敌人每秒造成5段367.5%物理远程暴风属性风切伤害，镰鼬旋风至多持续5秒，每柄标枪最多只能触发一次该效果。\n额外效果\n启用镰鼬死神时，镰鼬旋风的技能倍率会变为原先的2倍，但会失去吸引效果。"}, {"name": "灵魂神器", "url": "https://www.mcmod.cn/item/948572.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948572.png", "category": "追猎者:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：950%*7抛射物*14~15轮\n- 真实物理伤害：15点*7抛射物*14~15轮\n- 索敌半径：12米\n- 魔力消耗：600点\n- 冷却时间：180秒\n- 持标枪时按下设定的技能按键发动\n- 每升1级增加47.5%技能倍率\n技能描述\n命中效果\n将猎物的灵魂注入武器中，使其获得灵魂力量，消耗10点备弹并召唤5个灵魂神器在身后漂浮，若拥有五层猎者追踪效果，则会额外召唤2个灵魂神器，投掷任意普攻或技能标枪时，身后的灵魂神器会全数射出，攻击距离自身12米以内的随机目标，造成950%物理远程暴风属性神圣伤害，并且附加15点真实物理伤害，射出的灵魂神器会在2秒后重新召唤，技能至多持续30秒。\n长按发射标枪可触发14轮灵魂神器，连点发射标枪可触发15轮灵魂神器 MC里连点左/右键比长按左/右键快 ，创造模式下标枪发射没有间隔，此时可以发射至多16轮灵魂神器。"}, {"name": "紫电牢笼", "url": "https://www.mcmod.cn/item/948577.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948577.png?v=1", "category": "追猎者:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：350%*41段\n- AOE半径：6米\n- 负面效果：缓慢1*13秒\n- 负面半径：6米\n- 辅助能力-紫电牢笼：10%终伤+10%职业增幅 * 8秒\n- 辅助半径：16米（除自身外）\n- 魔力消耗：600点\n- 冷却时间：20秒\n- 持标枪时按下设定的技能按键发动\n- 每升1级增加17.5%技能倍率\n技能描述\n投出事先准备好的狂雷爆弹，狂雷爆弹落地后将对半径6米范围内所有目标造成1次350%物理远程闪电属性雷霆伤害，并展开强大的紫电牢笼，紫电牢笼将持续攻击半径6米范围内所有目标，在8秒内造成至多40段等同于狂雷爆弹的伤害，并持续给予其中的目标5秒缓慢I效果。\n投掷狂雷爆弹时给予除自身外半径16米范围内所有玩家持续8秒的紫电牢笼IX效果：职业增幅+10%，最终伤害+10%。"}, {"name": "镰鼬死神", "url": "https://www.mcmod.cn/item/948579.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948579.png", "category": "追猎者:三转技能:主动技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 自拐能力-镰鼬死神：持续期间召唤的镰鼬旋风伤害倍率提升至原先的2倍，但失去吸引效果 * 3600秒\n- 魔力消耗：100点\n- 冷却时间：5秒\n- 持标枪时按下设定的技能按键发动\n- 该技能升级没有效果\n技能描述\n技能效果\n掌握旋风力量，使镰鼬风暴化作为猎物的死亡恶梦，给予自身3600秒镰鼬死神效果：改变召唤的镰鼬旋风，使其技能倍率提升至原先的2倍，但失去吸引效果。拥有镰鼬死神效果时施放此技能，将会移除镰鼬死神效果。\n只会对持有效果时召唤的镰鼬旋风生效，镰鼬旋风存在期间内切换镰鼬死神不会使已有的镰鼬旋风发生改变。"}, {"name": "索命追猎", "url": "https://www.mcmod.cn/item/948581.html", "icon": "https://i.mcmod.cn/item/icon/128x128/94/948581.png?v=1", "category": "追猎者:三转技能:终极技能", "description": "基础信息\n- 职业等级130级解锁3转后开放学习\n- 技能倍率：950%*7抛射物*7狩猎点\n- 段数补正：10段直接命中+1段爆炸\n- 爆炸半径：5米\n- 收割者长枪倍率：950%*7狩猎点\n- 段数补正：10段+1镰鼬旋风\n- DOT倍率：200%*12段*7抛射物\n- 自拐能力-索命追猎：持续期间可以释放索命追猎 * 60秒\n- 自我治疗：6250点*7抛射物\n- 魔力消耗：1500点\n- 冷却时间：900秒\n- 持标枪时按下设定的技能按键发动\n- 每升1级增加47.5%技能倍率，312.5点自我治疗量\n技能描述\n技能效果\n仔细观察战场，找出真正的优势领域，对猎物造成致命的一击，给予自身60秒索命追猎效果，拥有此效果时，将不再生成狩猎点，并改为生成索命狩猎点，并立刻清除原有狩猎点重新生成一轮索命狩猎点。当采集到索命狩猎点时，如果未持有标枪技能，则使手上的标枪转化为收割者长枪，转化后直至投出前无法切换标枪技能，当收割者长枪命中目标或方块后会立即召唤镰鼬旋风，同时对目标造成10段950%物理远程黑暗属性地狱伤害，并施加12段持续伤害：每秒造成200%物理远程黑暗属性地狱伤害，持续12次。同时恢复自身6250点生命值。\n连续采集多个索命狩猎点不会叠加收割者长枪的数量，索命狩猎点可以提供镰鼬点数，释放收割者长枪不会尝试触发狩猎契约的镰鼬旋风，只会召唤收割者长枪的镰鼬旋风，收割者长枪的镰鼬旋风与狩猎契约的镰鼬旋风相同。收割者长枪的镰鼬旋风也可以被镰鼬死神切换状态。\n最多可采集7个索命狩猎点，采集完后将清除索命追猎效果，不再生成索命狩猎点。\n额外效果\n每次采集到索命狩猎点时，都会召唤共7把索命神枪，攻击附近的随机目标，对直接命中的目标造成10段950%物理远程黑暗属性地狱伤害，并在6秒后爆炸，对半径5米范围内所有敌人造成1段等同于直接命中伤害的爆炸伤害。每把索命神枪只能进行1次直接命中攻击。\n采集到索命狩猎点召唤的索命神枪相互独立，不会因为连续采集而导致索命神枪的损失。"}]}}, {"name": "已移除", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "", "attributes": {}, "tiers": {"已移除": [{"name": "死亡印记", "url": "https://www.mcmod.cn/item/439702.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/439702.png?v=7", "category": "已移除", "description": "7.0.0版本移除此技能，由短刃:飞毒刃代替。\n固有技能。\n消耗600魔力，魔法石*1，给予自己死亡印记效果，攻击时，可给予目标死亡印记效果，增加目标50%受到的伤害，持续8秒。\n持匕首时按下武器功能键（默认V键）发动。\n技能冷却时间30秒。\n每升级一次增加1秒死亡印记效果持续时间，最多升为10级。\n变更历史：\n- 7.0.0：移除技能。\n- 6.2.0：增强技能，受到的伤害增加系数由40%提升至50%。"}, {"name": "魔连弹", "url": "https://www.mcmod.cn/item/440069.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/440069.png?v=3", "category": "已移除", "description": "7.0.0版本移除此技能，由幻影悦灵代替。\n一转技能。\n最低学习等级5等。\n消耗300魔力，召唤魔连弹，连续发射扇状魔法球攻击前方目标，每个造成160%魔法攻击魔法属性能量伤害。\n技能冷却时间12秒。\n每升级一次增加10%魔连弹攻击伤害，最多升为10级。\n变更历史：\n- 7.0.0：移除技能。\n- 6.2.0：增强技能，伤害系数由120%提升至160%。"}, {"name": "哑刺", "url": "https://www.mcmod.cn/item/442595.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442595.png?v=1", "category": "已移除", "description": "7.0.0版本移除此技能，由中和毒素代替。\n固有技能。\n消耗300魔力，给予自己哑刺效果，伤害增加40%，持续20秒。\n持吹箭筒时蹲下按武器功能键（默认V键）发动。\n每升级一次增加4秒哑刺效果持续时间，最多升为10级。"}, {"name": "共鸣召唤", "url": "https://www.mcmod.cn/item/443088.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443088.png?v=4", "category": "已移除", "description": "7.0.0版本移除此技能，由引导之矢代替。\n消耗600魔力，杀死附近所有基本召唤物，并一次将所有召唤物召唤出来，并补充所有召唤师的生命值与魔力，持续时间结束后，召唤物会消失。持续90秒。\n技能冷却时间360秒。\n每升级一次增加3秒技能持续时间，最多升为10级。\n变更历史：\n- 7.0.0版本：移除技能。\n- 5.6.7版本：削弱技能，技能冷却时间由150秒提高为360秒。"}, {"name": "连环星降", "url": "https://www.mcmod.cn/item/443093.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443093.png?v=5", "category": "已移除", "description": "7.0.0版本移除此技能，由灵转符代替。\n消耗600魔力，召唤数波流星来攻击范围内所有目标，每个流星造成 500% 魔法攻击圣光属性能量伤害，另外，当持有日蚀效果时，流星会额外产生一次爆破伤害，当持有星蚀效果时，流星波数会增加。\n未持有星蚀时，连环星降最多攻击50次，每秒攻击5次。持有星蚀时，攻击次数+50，攻速不变。\n技能冷却时间16秒。\n每升级一次流星段数增加1段，最多升为10级。\n历史：\n6.3.1：增强技能，现在连环星降基础攻击次数为50，星蚀增加的攻击次数由40次提高至50次。\n5.6.8：调整技能，连环星降自动锁敌现在必须是玩家能看见的目标。"}, {"name": "天空护佑", "url": "https://www.mcmod.cn/item/443094.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443094.png?v=5", "category": "已移除", "description": "7.0.0版本移除此技能，由守灵结界代替。\n消耗600魔力，给予自己60秒天空护佑效果，持续时间内，自己全能力将大幅增加，并且最大伤害上限突破至原来两倍。另外，发动技能时，若持有日蚀效果，重置所有一转技能CD时间；若持有星蚀效果，自己与附近的队友会恢复 60% 的生命值与魔法值。\n技能冷却时间100秒。\n每升级一次增加3秒效果持续时间，最多升为10级。\n历史改动：\n- 7.0.0：移除技能。\n- 6.3.2：修复冷却时长错误，技能冷却时间由错误的20秒修正为100秒。\n- 6.3.1：增强技能，提高造成的伤害增加值，并且最大伤害上限突破至原来的两倍。"}, {"name": "日夜轮回", "url": "https://www.mcmod.cn/item/443095.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443095.png?v=7", "category": "已移除", "description": "7.0.0版本移除此技能，由式神斩代替。\n消耗600魔力，施放时，若未持有日蚀效果或已经持有星蚀效果时，将清除星蚀并获得日蚀效果，否则清除日蚀并获得星蚀效果，持续120秒，日蚀效果将提高攻击力并增加穿透值，星蚀效果将在攻击目标时，恢复自己的生命与魔力。\n每次施放时，对附近所有怪物造成3段当前魔力值*16的魔法攻击光明属性诅咒伤害。\n技能冷却时间20秒。\n每升级一次伤害值提高10%，增加2秒持续时间，最多升为10级。\n历史：\n- 7.0.0版本：移除技能。\n- 6.3.1版本：增强技能，现在可以造成3段伤害，每段伤害由10倍当前魔力值提升至16倍当前魔力值。\n- 5.6.8版本：削弱技能，魔力伤害倍率由30倍降低为10倍，且该伤害无法享受到玩家伤害倍率加成。\n- 5.6.7版本：增强技能，冷却时间降低为20秒，使用时造成额外伤害。"}, {"name": "太阳图腾", "url": "https://www.mcmod.cn/item/443105.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443105.png?v=6", "category": "已移除", "description": "7.0.0版本移除此技能，由沼气毒火代替。\n消耗200魔力，呼唤日光图腾的力量，召唤太阳图腾，太阳图腾每秒造成附近所有目标100%物理远程火焰属性燃烧伤害，并给予目标阳光烈炎效果，最多一次召唤10个图腾，持续90秒。\n技能冷却时间5秒。\n每升级一次增加5%图腾攻击伤害，最多升为10级。\n历史改动：\n- 6.1.4版本：增强技能，图腾持续时间由60秒提升至90秒，放置数量上限由5个提升至10个。\n- 5.6.2版本：削弱技能，技能伤害系数由800%改为100%。\n- 5.5.3版本：增强技能，技能现在可以给予目标阳光烈炎效果。"}, {"name": "先祖呐喊", "url": "https://www.mcmod.cn/item/443106.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443106.png?v=2", "category": "已移除", "description": "7.0.0版本移除此技能，由寒冰毒箭代替。\n消耗400魔力，发动先祖呐喊效果，效果发动后，附近所有图腾的运作速度大幅提高，并且时间内，自己的全属性都将提升，持续30秒。\n技能冷却时间100秒。\n每升级一次增加3秒技能效果持续时间，最多升为10级。"}, {"name": "治愈铃兰", "url": "https://www.mcmod.cn/item/643431.html", "icon": "https://i.mcmod.cn/item/icon/128x128/64/643431.png?v=4", "category": "已移除", "description": "7.0.0版本移除此技能，由草药专精代替。\n一转技能。\n最低学习等级 5 等。\n消耗 500 魔力、治疗粉 1 个，种植一朵治愈铃兰，施放技能召唤铃兰种子，五秒钟后种子成熟为治愈铃兰，将持续治疗半径7格内的玩家，只要待在铃兰附近，所有一转技能的冷却速度将会增加200%。\n技能冷却时间60秒。\n每升一级持续时间增加2秒，最多升为10级。\n释放治愈铃兰时，若场上已有自己释放的治愈铃兰且距离自己小于32格，将移除更早释放的治愈铃兰。"}]}}, {"name": "职业通用", "source_url": "https://www.mcmod.cn/item/list/1111-163.html", "review_url": "", "attributes": {}, "tiers": {"一转技能": [{"name": "瞬身术", "url": "https://www.mcmod.cn/item/438164.html", "icon": "https://i.mcmod.cn/item/icon/128x128/43/438164.png?v=7", "category": "职业通用:一转技能", "description": "消耗50 SP（耐力值），向玩家移动的方向快速位移，或向上方跳跃，获得4秒摔伤无效，免疫摔落伤害，冷却时间0.5秒。\n移动、跳跃时同时使用动作按钮（默认C键）发动。\n在地下城使用时，只能向玩家移动方向快速位移，不能向上方跳跃，且冷却时间为3秒。\n历史改动：\n- 7.3.8版本：现在瞬身术可以在地下城使用了，但不能向上方跳跃，且冷却时间为3秒。"}], "二转技能": [{"name": "黑暗力量", "url": "https://www.mcmod.cn/item/442597.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/442597.png?v=6", "category": "职业通用:二转技能", "description": "消耗1000魔力与黑魔法水晶，凝聚全身力量呼唤黑暗力量，以玛夏达巴之名，召唤黑暗能源来强化自己，持续时间内，攻击力、穿透值大幅提高，持续60秒。\n无需也无法设置技能按键，手持黑魔法水晶右键即可发动，技能冷却时间600秒。\n提高玩家30%最终伤害、30%造成的伤害，8点暴击率，8点回避率，16点防御力，4点穿透值，2点创伤降低概率。\n每升级一次增加3秒黑暗力量的持续，最多升为10级。\n变更历史：\n- 7.0.7版本：增强技能，冷却时间由1200秒缩短至600秒。\n- 7.0.0版本：增强技能，冷却时间由2400秒缩短至1200秒，升级效果由缩短冷却时间调整为延长持续时间。\n- 5.7.2版本：增强技能，现在还会额外提高30%最终伤害。\n- 5.5.4版本：现在黑暗力量还可以给予创伤降低概率。"}, {"name": "战斗思想", "url": "https://www.mcmod.cn/item/443102.html", "icon": "https://i.mcmod.cn/item/icon/128x128/44/443102.png?v=2", "category": "职业通用:二转技能", "description": "沉淀自己，通过冥想来增加自己的能力，提高物理近战/远程与魔法攻击力。\n每升级一次提高5点物理\\魔法攻击力，最多升为10级。\n历史改动：\n- 7.0.0版本：效果由增加4%造成的伤害调整为增加5点人物攻击力。"}]}}]};
